50: pub struct CoreLoopConfig {
51:     pub host: String,
52:     pub database: String,
53:     pub seed: Seed,
54:     pub population: u32,
55:     pub cycles: u32,
56:     pub duration_days: u32,
57:     pub party_size: u32,
58:     pub run_nonce: String,
59:     /// Validated disease identity used only by the disposable fixture.
60:     #[serde(default = "default_simulation_disease")]
61:     pub fixture_disease: String,
62:     /// Install and require the deterministic two-party quest acceptance fixture.
63:     #[serde(default)]
64:     pub require_quest_coverage: bool,
65:     pub use_imported_world: bool,
66:     pub expected_world_manifest_digest: Option<String>,
67:     /// Immutable, public-safe diagnostic artifact written if the run fails.
68:     pub failure_output: Option<PathBuf>,
69: }
