206: #[derive(Clone, Debug, Eq, PartialEq)]
207: enum ReducerCallFailureKind {
208:     Dispatch(String),
209:     Rejected {
210:         code: Option<ReducerErrorCode>,
211:         detail: String,
212:     },
213:     TimedOut,
214: }
215: 
216: #[derive(Clone, Debug, Eq, PartialEq)]
217: pub struct ReducerCallFailure {
218:     operation: ReducerOperation,
219:     kind: ReducerCallFailureKind,
220: }
221: 
222: impl ReducerCallFailure {
223:     fn dispatch(operation: ReducerOperation, detail: impl Into<String>) -> Self {
224:         Self {
225:             operation,
226:             kind: ReducerCallFailureKind::Dispatch(detail.into()),
227:         }
228:     }
229: 
230:     fn rejected(operation: ReducerOperation, detail: impl Into<String>) -> Self {
231:         let detail = detail.into();
232:         Self {
233:             operation,
234:             kind: ReducerCallFailureKind::Rejected {
235:                 code: parse_reducer_error(&detail),
236:                 detail,
237:             },
238:         }
239:     }
240: 
241:     const fn timed_out(operation: ReducerOperation) -> Self {
242:         Self {
243:             operation,
244:             kind: ReducerCallFailureKind::TimedOut,
245:         }
246:     }
247: 
248:     const fn code(&self) -> Option<ReducerErrorCode> {
249:         match &self.kind {
250:             ReducerCallFailureKind::Rejected { code, .. } => *code,
251:             ReducerCallFailureKind::Dispatch(_) | ReducerCallFailureKind::TimedOut => None,
252:         }
253:     }
254: }
