256: #[derive(Clone, Debug, Eq, PartialEq)]
257: pub enum CoreLoopError {
258:     Reducer(ReducerCallFailure),
259:     Operation {
260:         operation: ReducerOperation,
261:         detail: String,
262:     },
263:     Other(String),
264:     AuthoredThreat(AuthoredThreatError),
265: }
266: 
267: impl CoreLoopError {
268:     fn reducer_dispatch(operation: ReducerOperation, detail: impl Into<String>) -> Self {
269:         Self::Reducer(ReducerCallFailure::dispatch(operation, detail))
270:     }
271: 
272:     fn reducer_rejected(operation: ReducerOperation, detail: impl Into<String>) -> Self {
273:         Self::Reducer(ReducerCallFailure::rejected(operation, detail))
274:     }
275: 
276:     const fn reducer_timed_out(operation: ReducerOperation) -> Self {
277:         Self::Reducer(ReducerCallFailure::timed_out(operation))
278:     }
279: 
280:     const fn reducer_failure(&self) -> Option<&ReducerCallFailure> {
281:         match self {
282:             Self::Reducer(failure) => Some(failure),
283:             Self::Operation { .. } | Self::Other(_) | Self::AuthoredThreat(_) => None,
284:         }
285:     }
286: 
287:     fn operation(operation: ReducerOperation, detail: impl Into<String>) -> Self {
288:         Self::Operation {
289:             operation,
290:             detail: detail.into(),
291:         }
292:     }
293: 
294:     const fn operation_kind(&self) -> Option<ReducerOperation> {
295:         match self {
296:             Self::Reducer(failure) => Some(failure.operation),
297:             Self::Operation { operation, .. } => Some(*operation),
298:             Self::Other(_) | Self::AuthoredThreat(_) => None,
299:         }
300:     }
301: 
302:     const fn reducer_code(&self) -> Option<ReducerErrorCode> {
303:         match self.reducer_failure() {
304:             Some(failure) => failure.code(),
305:             None => None,
306:         }
307:     }
308: }
309: 
310: impl std::fmt::Display for CoreLoopError {
311:     fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
312:         match self {
313:             Self::Reducer(failure) => match &failure.kind {
314:                 ReducerCallFailureKind::Dispatch(detail) => write!(
315:                     formatter,
316:                     "could not send {}: {detail}",
317:                     failure.operation.as_str()
318:                 ),
319:                 ReducerCallFailureKind::Rejected { detail, .. } => {
320:                     write!(formatter, "{} failed: {detail}", failure.operation.as_str())
321:                 }
322:                 ReducerCallFailureKind::TimedOut => write!(
323:                     formatter,
324:                     "{} timed out after {ACTION_TIMEOUT:?}",
325:                     failure.operation.as_str()
326:                 ),
327:             },
328:             Self::Operation { operation, detail } => {
329:                 write!(formatter, "{} failed: {detail}", operation.as_str())
330:             }
331:             Self::Other(detail) => formatter.write_str(detail),
332:             Self::AuthoredThreat(error) => std::fmt::Display::fmt(error, formatter),
333:         }
334:     }
335: }
