327:     pub(super) fn record_journey_hold(
328:         &mut self,
329:         party_id: &str,
330:         phase: &str,
331:         reason: &str,
332:     ) -> Result<JourneyTravelOutcome, String> {
333:         let party = self.party_by_id(party_id)?;
334:         let members = self.expedition_member_observations(party_id)?;
335:         let supplies = self.expedition_supplies(party_id);
336:         let living_count = members.iter().filter(|member| member.alive).count() as u32;
337:         let required_food_kcal =
338:             living_count as f32 * adventuresim_core::provisioning::STRATEGIC_TRAVEL_KCAL_PER_DAY;
339:         let required_water_ml = living_count as f32
340:             * adventuresim_core::provisioning::STRATEGIC_TRAVEL_WATER_ML_PER_DAY;
341:         let supplies_cover_one_day = expedition_supplies_cover_one_rest_day(&members, supplies);
342:         let journey = self
343:             .connection
344:             .db
345:             .party_journey()
346:             .iter()
347:             .find(|row| row.party_id == party_id);
348:         let active_interval = journey.as_ref().and_then(|journey| {
349:             projected_camp_rest_minutes(
350:                 journey.completed_elapsed_minutes,
351:                 journey.total_elapsed_minutes,
352:                 &journey.forecast_camp_intervals,
353:             )
354:         });
355:         let journey_completed_elapsed = journey.as_ref().map_or_else(
356:             || "none".into(),
357:             |row| row.completed_elapsed_minutes.to_string(),
358:         );
359:         let journey_total_elapsed = journey.as_ref().map_or_else(
360:             || "none".into(),
361:             |row| row.total_elapsed_minutes.to_string(),
362:         );
363:         let journey_remaining_elapsed = journey.as_ref().map_or_else(
364:             || "none".into(),
365:             |row| {
366:                 row.total_elapsed_minutes
367:                     .saturating_sub(row.completed_elapsed_minutes)
368:                     .to_string()
369:             },
370:         );
371:         let journey_destination = journey.as_ref().map_or_else(
372:             || {
373:                 party
374:                     .camp_destination
375:                     .as_ref()
376:                     .map_or_else(|| "none".into(), public_journey_endpoint)
377:             },
378:             |row| public_journey_endpoint(&row.destination),
379:         );
380:         let (active_interval_start, active_interval_minutes) = active_interval.map_or_else(
381:             || ("none".into(), "none".into()),
382:             |(start, minutes)| (start.to_string(), minutes.to_string()),
383:         );
384:         self.metrics.expedition_holds = self.metrics.expedition_holds.saturating_add(1);
385:         let diagnostic_agent = members.first().map_or(0, |member| member.agent_id);
386:         self.event(
387:             diagnostic_agent,
388:             CoreLoopEventKind::ExpeditionRecovery,
389:             format!(
390:                 "party={};phase={};action=hold_position;reason={};journey_completed_elapsed={journey_completed_elapsed};journey_total_elapsed={journey_total_elapsed};journey_remaining_elapsed={journey_remaining_elapsed};journey_destination={};camp_remaining_minutes={};active_forecast_interval_start={active_interval_start};active_forecast_interval_minutes={active_interval_minutes};living_count={living_count};one_day_food_kcal_required={required_food_kcal:.0};stored_food_kcal={:.0};one_day_water_ml_required={required_water_ml:.0};portable_water_ml={:.0};supplies_cover_one_rest_day={supplies_cover_one_day}",
391:                 bounded_event_field(party_id),
392:                 bounded_event_field(phase),
393:                 bounded_event_field(reason),
394:                 bounded_event_field(&journey_destination),
395:                 party.camp_remaining_minutes,
396:                 supplies.stored_food_kcal,
397:                 supplies.portable_water_ml,
398:             ),
399:         );
400:         self.emit_expedition_diagnostics(
401:             ExpeditionDiagnosticContext {
402:                 party_id,
403:                 phase,
404:                 action: "hold_position",
405:                 reason,
406:             },
407:             ExpeditionObservationChange {
408:                 members_before: &members,
409:                 members_after: &members,
410:                 supplies_before: supplies,
411:                 supplies_after: supplies,
412:             },
413:         );
414:         Ok(JourneyTravelOutcome::HeldNoActionableActor)
415:     }
