417:     pub(super) fn expedition_recovery_actor(
418:         &self,
419:         party_id: &str,
420:     ) -> Option<(u64, u32, &'static str)> {
421:         let party = self
422:             .connection
423:             .db
424:             .party()
425:             .iter()
426:             .find(|party| party.id == party_id)?;
427:         let mut ready = self
428:             .expedition_member_observations(party_id)
429:             .ok()?
430:             .into_iter()
431:             .filter(|member| {
432:                 member.alive
433:                     && member.condition_status == Some(DomainIncapacitationStatus::Ready)
434:                     && !member.symptomatic
435:                     && !member.critical
436:             })
437:             .collect::<Vec<_>>();
438:         ready.sort_by_key(|member| (member.character_id != party.leader_id, member.character_id));
439:         if let Some(actor) = ready.into_iter().next() {
440:             let role = if actor.character_id == party.leader_id {
441:                 "ready_leader"
442:             } else {
443:                 "ready_companion"
444:             };
445:             return Some((actor.character_id, actor.agent_id, role));
446:         }
447:         None
448:     }
