450:     pub(super) fn expedition_recovery_rest_actor(
451:         &self,
452:         party_id: &str,
453:     ) -> Option<ExpeditionRecoveryRestActor> {
454:         let party = self
455:             .connection
456:             .db
457:             .party()
458:             .iter()
459:             .find(|party| party.id == party_id)?;
460:         let members = self.expedition_member_observations(party_id).ok()?;
461:         let supplies = self.expedition_supplies(party_id);
462:         if self.party_has_unresolved_public_encounter(party_id)
463:             || (party.camp_destination.is_some()
464:                 && self.public_journey_camp_state(party_id).is_err())
465:             || (party.camp_destination.is_none() && party.current_case_site_id.is_none())
466:         {
467:             return None;
468:         }
469:         if let Some((character_id, agent_id, role)) = self.expedition_recovery_actor(party_id) {
470:             return Some(ExpeditionRecoveryRestActor::Actionable(
471:                 ActionableRecoveryRestActor {
472:                     character_id,
473:                     agent_id,
474:                     role,
475:                 },
476:             ));
477:         }
478:         if !passive_no_actionable_rest_allowed(
479:             &members,
480:             supplies,
481:             party.current_settlement_id.is_none(),
482:             true,
483:             party.leader_id,
484:             false,
485:         ) {
486:             return None;
487:         }
488:         let leader = members
489:             .iter()
490:             .find(|member| member.character_id == party.leader_id && member.alive)?;
491:         Some(ExpeditionRecoveryRestActor::PassiveNoActionable(
492:             PassiveNoActionableRestActor {
493:                 leader_id: leader.character_id,
494:                 agent_id: leader.agent_id,
495:             },
496:         ))
497:     }
