519:     pub(super) fn public_expedition_return_settlement(&self, party_id: &str) -> Option<String> {
520:         if let Some(journey) = self
521:             .connection
522:             .db
523:             .party_journey()
524:             .iter()
525:             .find(|journey| journey.party_id == party_id)
526:         {
527:             if let JourneyEndpoint::Settlement(origin) = journey.origin {
528:                 return Some(origin.id);
529:             }
530:             if let JourneyEndpoint::Settlement(destination) = journey.destination {
531:                 return Some(destination.id);
532:             }
533:         }
534:         let party = self
535:             .connection
536:             .db
537:             .party()
538:             .iter()
539:             .find(|party| party.id == party_id)?;
540:         let current_site = party.current_case_site_id.as_ref()?;
541:         let member_ids = self
542:             .connection
543:             .db
544:             .party_member()
545:             .iter()
546:             .filter(|membership| membership.party_id == party_id)
547:             .map(|membership| membership.character_id)
548:             .collect::<HashSet<_>>();
549:         let mut origins = self
550:             .connection
551:             .db
552:             .backend_case_site_pins()
553:             .iter()
554:             .filter(|pin| {
555:                 member_ids.contains(&pin.owner_character_id) && &pin.case_site_id == current_site
556:             })
557:             .map(|pin| pin.origin_settlement_id)
558:             .collect::<Vec<_>>();
559:         origins.sort();
560:         origins.dedup();
561:         if origins.len() == 1 {
