592:     fn return_idle_ready_party_from_case_site(
593:         &mut self,
594:         party_id: &str,
595:     ) -> Result<Option<ExpeditionRecoveryOutcome>, String> {
596:         let party = self.party_by_id(party_id)?;
597:         let Some(current_site_id) = party.current_case_site_id.clone()
598:         else {
599:             return Ok(None);
600:         };
601:         // A persisted journey, accepted direct contract, or unresolved generated
602:         // case already has its own continuation policy. This fallback is only
603:         // for a ready party left idle at a publicly known site by another
604:         // authoritative action, such as an activity incident.
605:         if party.camp_destination.is_some() || self.active_direct_contract(&party).is_some() {
606:             return Ok(None);
607:         }
608:         let member_ids = self
609:             .connection
610:             .db
611:             .party_member()
612:             .iter()
613:             .filter(|membership| membership.party_id == party_id)
614:             .map(|membership| membership.character_id)
615:             .collect::<HashSet<_>>();
616:         let mut pins = self
617:             .connection
618:             .db
619:             .backend_case_site_pins()
620:             .iter()

621:             .filter(|pin| {
622:                 member_ids.contains(&pin.owner_character_id)
623:                     && pin.case_site_id == current_site_id
624:             })
625:             .collect::<Vec<_>>();
626:         if pins
627:             .iter()
628:             .any(|pin| pin.generated_case && !pin.case_resolved)
629:         {
630:             return Ok(None);
631:         }
632:         pins.sort_by_key(|pin| {
633:             (
634:                 pin.origin_settlement_id.clone(),
635:                 pin.owner_character_id,
636:                 pin.case_id.clone(),
637:             )
638:         });
639:         let Some(return_settlement) = self.public_expedition_return_settlement(party_id) else {
640:             self.record_journey_hold(
641:                 party_id,
642:                 "idle_case_site_return",
643:                 "journey_held_no_unique_public_idle_site_origin",
644:             )?;
645:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
646:         };
647:         let return_pin = pins
648:             .into_iter()
649:             .find(|pin| pin.origin_settlement_id == return_settlement);
650:         let members = self.expedition_member_observations(party_id)?;
651:         let supplies = self.expedition_supplies(party_id);
652:         let observed_unpinned_activity_return = return_pin.is_none()
653:             && observed_activity_return_origin(
654:                 &self.observed_activity_site_origins,
655:                 party_id,
656:                 Some(&current_site_id.value),
657:             )
658:             .as_deref()
659:                 == Some(return_settlement.as_str());
660:         if !expedition_party_can_resume(&members) {
661:             self.record_journey_hold(
662:                 party_id,
663:                 "idle_case_site_return",
664:                 "journey_held_idle_site_return_condition_not_ready",
665:             )?;
666:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
667:         }
668:         if !observed_unpinned_activity_return
669:             && !expedition_supplies_cover_one_rest_day(&members, supplies)
670:         {
671:             self.record_journey_hold(
672:                 party_id,
673:                 "idle_case_site_return",
674:                 "journey_held_idle_site_return_supplies_unavailable",
675:             )?;
676:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
677:         }
678:         if !observed_unpinned_activity_return
679:             && !matches!(
680:                 self.validate_party_departure_readiness(party_id),
681:                 DepartureReadiness::Ready
682:             )
683:         {
684:             self.record_journey_hold(
685:                 party_id,
686:                 "idle_case_site_return",
687:                 "journey_held_idle_site_return_departure_not_ready",
688:             )?;
689:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
690:         }
691:         if return_pin.as_ref().is_some_and(|pin| {
692:             !matches!(
693:                 self.generated_action_return_thermal_decision(party_id, pin, 0),
694:                 OnSiteActionDecision::Ready | OnSiteActionDecision::ReturnNow
695:             )
696:         }) {
697:             self.record_journey_hold(
698:                 party_id,
699:                 "idle_case_site_return",
700:                 "journey_held_unsafe_idle_site_return_forecast",
701:             )?;
702:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
703:         }
704:         let Some((return_actor_id, return_actor_agent)) = self.current_leader(party_id) else {
705:             self.record_journey_hold(
706:                 party_id,
707:                 "idle_case_site_return",
708:                 "journey_held_no_idle_site_return_actor",
709:             )?;
710:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
711:         };
712:         let result = reducer_call!(self, ReducerOperation::IdleCaseSiteReturn, |cb| self
713:             .connection
714:             .reducers
715:             .travel_to_settlement_then(return_actor_id, return_settlement.clone(), cb));
716:         self.call(result)?;
717:         self.event(
718:             return_actor_agent,
719:             CoreLoopEventKind::Travel,
720:             format!(
721:                 "party={};phase=idle_case_site_return;case_site={};destination={};reason=public_idle_site_return",
722:                 bounded_event_field(party_id),
723:                 bounded_event_field(&current_site_id.value),
724:                 bounded_event_field(&return_settlement),
725:             ),
726:         );
727:         if self.travel_camps(party_id)? != JourneyTravelOutcome::Completed {
728:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
729:         }
730:         self.observe_deaths();
731:         let returned_party = self.party_by_id(party_id)?;
732:         if returned_party.current_settlement_id.as_deref() != Some(return_settlement.as_str())
733:             || returned_party.camp_destination.is_some()
734:             || !self
735:                 .expedition_member_observations(party_id)?
736:                 .iter()
737:                 .any(|member| member.alive)
738:         {
739:             self.record_journey_hold(
740:                 party_id,
741:                 "idle_case_site_return",
742:                 "journey_held_idle_site_return_not_publicly_complete",
743:             )?;
744:             return Ok(Some(ExpeditionRecoveryOutcome::Held));
745:         }
746:         self.event(
747:             return_actor_agent,
748:             CoreLoopEventKind::Travel,
749:             format!(
750:                 "party={};phase=idle_case_site_return_complete;destination={};reason=public_idle_site_return",
751:                 bounded_event_field(party_id),
752:                 bounded_event_field(&return_settlement),
753:             ),
754:         );
755:         self.observed_activity_site_origins
756:             .retain(|(observed_party_id, _), _| observed_party_id != party_id);
757:         Ok(Some(ExpeditionRecoveryOutcome::Returned))
758:     }
