760:     fn surrender_affordable_authority_arrest(
761:         &mut self,
762:         party_id: &str,
763:         current_site_id: &str,
764:     ) -> Result<AuthoritySurrenderOutcome, String> {
765:         let controlled_character_ids = self.character_ids.iter().copied().collect::<HashSet<_>>();
766:         let Some(action) = select_affordable_authority_surrender_action(
767:             self.connection.db.backend_authority_arrest_actions().iter(),
768:             party_id,
769:             current_site_id,
770:             &controlled_character_ids,
771:         ) else {
772:             return Ok(AuthoritySurrenderOutcome::NotApplicable);
773:         };
774:         let Some(agent) = self
775:             .character_ids
776:             .iter()
777:             .position(|character_id| *character_id == action.instigator_id)
778:             .map(|index| index as u32)
779:         else {
780:             return Ok(AuthoritySurrenderOutcome::NotApplicable);
781:         };
782:         if !self
783:             .connection
784:             .db
785:             .backend_characters()
786:             .iter()
787:             .find(|character| character.id == action.instigator_id)
788:             .is_some_and(|character| {
789:                 character.alive && character.party_id.as_deref() == Some(party_id)
790:             })
791:         {
792:             return Ok(AuthoritySurrenderOutcome::NotApplicable);
793:         }
794: 
795:         let action_token = action.action_token;
796:         let origin_settlement_id = action.origin_settlement_id;
797:         let instigator_id = action.instigator_id;
798:         let fine = action.fine;
799:         let result = reducer_call!(self, ReducerOperation::SurrenderToAuthority, |cb| self
800:             .connection
801:             .reducers
802:             .surrender_to_authority_then(instigator_id, action_token.clone(), cb));
803:         self.call(result)?;
804:         let action_remains = self
805:             .connection
806:             .db
807:             .backend_authority_arrest_actions()
808:             .iter()
809:             .any(|action| {
810:                 action.action_token == action_token
811:                     && action.party_id == party_id
812:                     && action.case_site_id.value == current_site_id
813:             });
814:         let party_remains = self
815:             .party_by_id(party_id)?
816:             .current_case_site_id
817:             .as_ref()
818:             .is_some_and(|site| site.value == current_site_id);
819:         if action_remains || !party_remains {
820:             self.record_journey_hold(
821:                 party_id,
822:                 "authority_surrender",
823:                 "journey_held_authority_surrender_not_publicly_confirmed",
824:             )?;
825:             self.event(
826:                 agent,
827:                 CoreLoopEventKind::AuthoritySurrender,
828:                 format!(
829:                     "party={};case_site={};origin_settlement={};reason=authority_surrender_not_publicly_confirmed",
830:                     bounded_event_field(party_id),
831:                     bounded_event_field(current_site_id),
832:                     bounded_event_field(&origin_settlement_id),
833:                 ),
834:             );
835:             return Ok(AuthoritySurrenderOutcome::Held);
836:         }
837:         self.observed_activity_site_origins
838:             .retain(|(observed_party_id, _), _| observed_party_id != party_id);
839:         self.observed_activity_site_origins.insert(
840:             (party_id.to_owned(), current_site_id.to_owned()),
841:             origin_settlement_id.clone(),
842:         );
843:         self.metrics.authority_surrenders = self.metrics.authority_surrenders.saturating_add(1);
844:         self.metrics.authority_fines_paid = self.metrics.authority_fines_paid.saturating_add(fine);
845:         self.event(
846:             agent,
847:             CoreLoopEventKind::AuthoritySurrender,
848:             format!(
849:                 "party={};case_site={};origin_settlement={};fine={fine};reason=affordable_pending_authority_arrest",
850:                 bounded_event_field(party_id),
851:                 bounded_event_field(current_site_id),
852:                 bounded_event_field(&origin_settlement_id),
853:             ),
854:         );
855:         Ok(AuthoritySurrenderOutcome::Surrendered)
856:     }
