116: pub(super) enum ExpeditionRecoveryRestActor {
117:     Actionable(ActionableRecoveryRestActor),
118:     PassiveNoActionable(PassiveNoActionableRestActor),
119: }
120: 
121: impl ExpeditionRecoveryRestActor {
122:     pub(super) fn character_id(self) -> u64 {
123:         match self {
124:             Self::Actionable(actor) => actor.character_id,
125:             Self::PassiveNoActionable(actor) => actor.leader_id,
126:         }
127:     }
128: 
129:     pub(super) fn agent_id(self) -> u32 {
130:         match self {
131:             Self::Actionable(actor) => actor.agent_id,
132:             Self::PassiveNoActionable(actor) => actor.agent_id,
133:         }
134:     }
135: 
136:     pub(super) fn role(self) -> &'static str {
137:         match self {
138:             Self::Actionable(actor) => actor.role,
139:             Self::PassiveNoActionable(_) => "passive_no_actionable_rest",
140:         }
141:     }
142: 
143:     pub(super) fn is_passive(self) -> bool {
144:         matches!(self, Self::PassiveNoActionable(_))
145:     }
146: }
147: 
148: pub(super) fn expedition_member_needs_recovery(member: &ExpeditionMemberObservation) -> bool {
149:     member.alive
150:         && (member.condition_status != Some(DomainIncapacitationStatus::Ready)
151:             || member.symptomatic
152:             || member.critical)
153: }
154: 
155: pub(super) fn public_journey_endpoint(endpoint: &JourneyEndpoint) -> String {
156:     match endpoint {
157:         JourneyEndpoint::Settlement(settlement) => format!("settlement:{}", settlement.id),
158:         JourneyEndpoint::CaseSite(site) => format!("case_site:{}", site.id.value),
159:         JourneyEndpoint::Camp(camp) => format!("camp:{}", bounded_event_field(camp)),
160:     }
161: }
162: 
163: pub(super) fn expedition_party_can_resume(members: &[ExpeditionMemberObservation]) -> bool {
164:     let living = members
165:         .iter()
166:         .filter(|member| member.alive)
167:         .collect::<Vec<_>>();
168:     !living.is_empty()
169:         && living.iter().any(|member| {
170:             member.condition_status == Some(DomainIncapacitationStatus::Ready)
171:                 && !member.symptomatic
172:                 && !member.critical
173:         })
174:         && living
175:             .iter()
176:             .all(|member| !expedition_member_needs_recovery(member))
177: }
178: 
179: pub(super) fn expedition_supplies_cover_one_rest_day(
180:     members: &[ExpeditionMemberObservation],
181:     supplies: ExpeditionSuppliesObservation,
182: ) -> bool {
183:     let living = members.iter().filter(|member| member.alive).count() as f32;
184:     living > 0.0
185:         && supplies.stored_food_kcal
186:             >= living * adventuresim_core::provisioning::STRATEGIC_TRAVEL_KCAL_PER_DAY
187:         && supplies.portable_water_ml
188:             >= living * adventuresim_core::provisioning::STRATEGIC_TRAVEL_WATER_ML_PER_DAY
189: }
190: 
191: pub(super) fn observed_activity_return_origin(
192:     observations: &HashMap<(String, String), String>,
193:     party_id: &str,
194:     current_case_site_id: Option<&str>,
195: ) -> Option<String> {
196:     let site_id = current_case_site_id?;
197:     observations
198:         .get(&(party_id.to_owned(), site_id.to_owned()))
199:         .cloned()
200: }
201: 
202: pub(super) fn passive_no_actionable_rest_allowed(
203:     members: &[ExpeditionMemberObservation],
204:     supplies: ExpeditionSuppliesObservation,
205:     off_settlement: bool,
206:     persisted_camp_journey: bool,
207:     leader_id: u64,
208:     actionable_actor_exists: bool,
209: ) -> bool {
210:     let living = members
211:         .iter()
212:         .filter(|member| member.alive)
213:         .collect::<Vec<_>>();
214:     off_settlement
215:         && persisted_camp_journey
216:         && !actionable_actor_exists
217:         && !living.is_empty()
218:         && living.iter().any(|member| member.character_id == leader_id)
219:         && living
220:             .iter()
221:             .all(|member| member.condition_status.is_some() && !member.critical)
222:         && expedition_supplies_cover_one_rest_day(members, supplies)
223: }
224: 
225: pub(super) fn expedition_elapsed_delta(
226:     before: &[ExpeditionMemberObservation],
227:     after: &[ExpeditionMemberObservation],
228: ) -> u64 {
229:     let before_max = before
230:         .iter()
231:         .map(|member| member.elapsed_minutes)
232:         .max()
233:         .unwrap_or(StrategicMinute::ZERO);
234:     let after_max = after
235:         .iter()
236:         .map(|member| member.elapsed_minutes)
237:         .max()
238:         .unwrap_or(before_max);
239:     after_max.elapsed_since(before_max)
240: }

