508:     pub(super) fn start_public_dialogue(
509:         &mut self,
510:         character_id: u64,
511:         cycle: u32,
512:         candidate: &PublicNpcCandidate,
513:         purpose: GeneratedDialoguePurpose,
514:     ) -> Result<PublicDialogueStartOutcome<String>, PublicDialogueStartError<CoreLoopError>> {
515:         self.dialogue_nonce = self.dialogue_nonce.saturating_add(1);
516:         let session_id = format!(
517:             "dialogue:{character_id}:sim-{cycle}-{}-{}",
518:             self.dialogue_nonce,
519:             purpose.stable_id()
520:         );
521:         let result = reducer_call!(self, ReducerOperation::StartDialogue, |cb| self
522:             .connection
523:             .reducers
524:             .start_dialogue_then(
525:                 character_id,
526:                 session_id.clone(),
527:                 candidate.conversation_id.clone(),
528:                 candidate.resident_character_id.to_string(),
529:                 candidate.location_id.clone(),
530:                 adventuresim_dialogue::CATALOG_DIGEST.to_owned(),
531:                 cb,
532:             ));
533:         if result
534:             .as_ref()
535:             .is_err_and(dialogue_contact_presence_changed)
536:         {
537:             // The public presence row can change between selection and the
538:             // authoritative reducer call. Treat that observer-safe mismatch
539:             // as a replan instead of weakening authority or aborting the run.
540:             return Ok(PublicDialogueStartOutcome::ContactUnavailable);
541:         }
542:         self.observe_call_result(result)
543:             .map_err(PublicDialogueStartError::Reducer)?;
544:         let session_is_owned = self
545:             .connection
546:             .db
547:             .backend_dialogue_sessions()
548:             .iter()
549:             .any(|row| row.id == session_id && row.owner_character_id == character_id);
550:         if !session_is_owned {
551:             return Err(PublicDialogueStartError::SessionProjectionMissing);
552:         }
553:         Ok(PublicDialogueStartOutcome::Started(session_id))
554:     }
