566:     pub(super) fn public_discovery_fingerprint(
567:         &self,
568:         character_id: u64,
569:         official_minute: StrategicMinute,
570:         candidates: &[PublicNpcCandidate],
571:     ) -> (PublicDiscoveryFingerprint, usize, &'static str) {
572:         let settlement_id = self
573:             .connection
574:             .db
575:             .backend_characters()
576:             .iter()
577:             .find(|row| row.id == character_id)
578:             .and_then(|row| row.current_settlement_id)
579:             .unwrap_or_default();
580:         let mut contacts = candidates
581:             .iter()
582:             .map(public_discovery_contact_identity)
583:             .collect::<Vec<_>>();
584:         contacts.sort();
585:         let mut active_symptoms = self
586:             .connection
587:             .db
588:             .local_problem_symptom()
589:             .iter()
590:             .filter(|symptom| {
591:                 symptom.settlement_id == settlement_id
592:                     && StrategicMinute::new(symptom.active_from.minutes) <= official_minute
593:                     && official_minute < StrategicMinute::new(symptom.active_until.minutes)
594:             })
595:             .map(|symptom| {
596:                 (
597:                     symptom.symptom,
598:                     symptom.public_summary,
599:                     StrategicMinute::new(symptom.active_from.minutes),
600:                     StrategicMinute::new(symptom.active_until.minutes),
601:                 )
602:             })
603:             .collect::<Vec<_>>();
604:         active_symptoms.sort();
605:         let oldest_age = active_symptoms
606:             .iter()
607:             .map(|(_, _, active_from, _)| official_minute.elapsed_since(*active_from))
608:             .max();
609:         let active_symptom_count = active_symptoms.len();
610:         (
611:             PublicDiscoveryFingerprint {
612:                 settlement_id,
613:                 contacts,
614:                 active_symptoms,
615:             },
616:             active_symptom_count,
617:             public_symptom_age_bucket(oldest_age),
618:         )
619:     }
