621:     pub(super) fn discover_generated_case(
622:         &mut self,
623:         character_id: u64,
624:         agent: u32,
625:         cycle: u32,
626:     ) -> Result<GeneratedDiscoveryOutcome, String> {
627:         let before = self
628:             .connection
629:             .db
630:             .backend_investigation_cases()
631:             .iter()
632:             .filter(|row| {
633:                 row.owner_character_id == character_id
634:                     && DomainCaseStatus::from_stable_id(&row.status) == Some(DomainCaseStatus::Open)
635:             })
636:             .map(|row| row.case_id)
637:             .collect::<HashSet<_>>();
638:         let before_referrals = self
639:             .connection
640:             .db
641:             .backend_investigation_leads()
642:             .iter()
643:             .filter(|row| row.owner_character_id == character_id)
644:             .map(PublicDiscoveryReferral::from)
645:             .map(|lead| (lead.lead_id.clone(), lead))
646:             .collect::<HashMap<_, _>>();
647:         let candidates = self.visible_npc_candidates(character_id, None, None);
648:         let visible_candidate_count = candidates.len();
649:         let official_minute = self.official_world_minute();
650:         let official_time = official_minute;
651:         let (public_fingerprint, active_symptom_count, oldest_symptom_age_bucket) =
652:             self.public_discovery_fingerprint(character_id, official_minute, &candidates);
653:         let previous_contact = public_discovery_previous_contact(
654:             self.generated_discovery_backoff.get(&character_id),
655:             &public_fingerprint,
656:         );
657:         let candidate = stable_discovery_action_candidate(candidates, previous_contact);
658:         let location_class = discovery_location_class(candidate.as_ref());
659:         if self.generated_discovery_backoff.get(&character_id).is_some_and(|backoff| {
660:             public_discovery_backoff_active(backoff, &public_fingerprint, official_time)
661:         }) {
662:             self.metrics.generated_discovery_public_backoff_suppressions = self
663:                 .metrics
664:                 .generated_discovery_public_backoff_suppressions
665:                 .saturating_add(1);
666:             self.event(
667:                 agent,
668:                 CoreLoopEventKind::GeneratedDiscoveryResult,
669:                 format!(
670:                     "official_minute={official_minute};active_symptom_count={};oldest_symptom_age_bucket={oldest_symptom_age_bucket};visible_candidate_count={};location_class={location_class};owner_open_case_count={};public_backoff=true;result=suppressed;reason=unchanged_public_state",
671:                     public_count_bucket(active_symptom_count),
672:                     visible_candidate_count.min(32),
673:                     before.len().min(32),
674:                 ),
675:             );
676:             return Ok(GeneratedDiscoveryOutcome::PublicBackoff);
677:         }
678:         self.generated_discovery_backoff.remove(&character_id);
679: 
680:         let Some(candidate) = candidate else {
681:             self.metrics.generated_discovery_decisions_unproductive = self
682:                 .metrics
683:                 .generated_discovery_decisions_unproductive
684:                 .saturating_add(1);
685:             self.event(
686:                 agent,
687:                 CoreLoopEventKind::GeneratedDiscoveryResult,
688:                 format!(
689:                     "official_minute={official_minute};active_symptom_count={};oldest_symptom_age_bucket={oldest_symptom_age_bucket};visible_candidate_count={};location_class=none;owner_open_case_count={};public_backoff=false;dialogue_success=false;session_success=false;new_open_cases=0;rumor_delivered=false;result=unproductive;reason=no_visible_contacts;fallback=no_visible_contacts;activity_fallback=true",
690:                     public_count_bucket(active_symptom_count),
691:                     visible_candidate_count.min(32),
692:                     before.len().min(32),
693:                 ),
694:             );
695:             return Ok(GeneratedDiscoveryOutcome::NoVisibleContacts);
696:         };
697: 
698:         self.metrics.generated_discovery_actions_attempted = self
699:             .metrics
700:             .generated_discovery_actions_attempted

701:             .saturating_add(1);
702:         self.event(
703:             agent,
704:             CoreLoopEventKind::GeneratedDiscoveryAttempt,
705:             format!(
706:                 "official_minute={official_minute};active_symptom_count={};oldest_symptom_age_bucket={oldest_symptom_age_bucket};visible_candidate_count={};location_class={location_class};owner_open_case_count={};public_backoff=false",
707:                 public_count_bucket(active_symptom_count),
708:                 visible_candidate_count.min(32),
709:                 before.len().min(32),
710:             ),
711:         );
712:         let dialogue_start = self.start_public_dialogue(
713:             character_id,
714:             cycle,
715:             &candidate,
716:             GeneratedDialoguePurpose::Discovery,
717:         );
718:         if matches!(
719:             &dialogue_start,
720:             Ok(PublicDialogueStartOutcome::ContactUnavailable)
721:         ) {
722:             self.metrics.generated_discovery_decisions_unproductive = self
723:                 .metrics
724:                 .generated_discovery_decisions_unproductive
725:                 .saturating_add(1);
726:             self.event(
727:                 agent,
728:                 CoreLoopEventKind::GeneratedDiscoveryResult,
729:                 format!(
730:                     "official_minute={official_minute};active_symptom_count={};oldest_symptom_age_bucket={oldest_symptom_age_bucket};visible_candidate_count={};location_class={location_class};owner_open_case_count={};public_backoff=false;dialogue_success=false;session_success=false;new_open_cases=0;rumor_delivered=false;result=unproductive;reason=contact_presence_changed;fallback=settlement_activity;activity_fallback=true",
731:                     public_count_bucket(active_symptom_count),
732:                     visible_candidate_count.min(32),
733:                     before.len().min(32),
734:                 ),
735:             );
736:             return Ok(GeneratedDiscoveryOutcome::NoVisibleContacts);
737:         }
738:         if let Err(error) = dialogue_start {
739:             let dialogue_succeeded =
740:                 matches!(error, PublicDialogueStartError::SessionProjectionMissing);
741:             self.event(
742:                 agent,
743:                 CoreLoopEventKind::GeneratedDiscoveryResult,
744:                 format!(
745:                     "official_minute={official_minute};active_symptom_count={};oldest_symptom_age_bucket={oldest_symptom_age_bucket};visible_candidate_count={};location_class={location_class};owner_open_case_count={};public_backoff=false;dialogue_success={dialogue_succeeded};session_success=false;new_open_cases=0;rumor_delivered=false;result=failed;reason={};fallback=none;activity_fallback=false",
746:                     public_count_bucket(active_symptom_count),
747:                     visible_candidate_count.min(32),
748:                     before.len().min(32),
749:                     if dialogue_succeeded {
750:                         "session_projection_missing"
751:                     } else {
752:                         "dialogue_failed"
753:                     },
754:                 ),
755:             );
756:             let detail = if dialogue_succeeded {
757:                 "owner-scoped dialogue session unavailable"
758:             } else {
759:                 "public discovery contact failed"
760:             };
761:             self.failure_recorder.record(CoreLoopError::operation(
762:                 ReducerOperation::StartDiscoveryDialogue,
763:                 detail,
764:             ));
765:             return Err(format!("start_discovery_dialogue failed: {detail}"));
766:         }
767: 
768:         // The owner-scoped open-case projection is the public postcondition of
769:         // receiving a generated rumor. It avoids inspecting private delivery
770:         // receipts or generation eligibility.
771:         let mut after = self.owned_open_generated_cases(character_id);
772:         let mut discovered = after
773:             .iter()
774:             .filter(|(case_id, _)| !before.contains(case_id))
775:             .cloned()
776:             .collect::<Vec<_>>();
777:         if discovered.is_empty()
778:             && let Some(referral) = public_discovery_referral_to_follow(
779:                 character_id,
780:                 &before_referrals,
781:                 &before,
782:                 self.connection
783:                     .db
784:                     .backend_investigation_leads()
785:                     .iter()
786:                     .map(PublicDiscoveryReferral::from),
787:             )
788:         {
789:             let preferred_location = if referral.current_learned_location.is_empty() {
790:                 &referral.expected_location
791:             } else {
792:                 &referral.current_learned_location
793:             };
794:             if self.try_generated_dialogue_topic(GeneratedDialogueTopicRequest {
795:                 character_id,
796:                 agent,
797:                 cycle,
798:                 case_id: &referral.case_id,
799:                 subject: &referral.summary,
800:                 topics: &[GeneratedDialogueTopic::ReferredTestimony],
801:                 preferred_name: Some(&referral.witness_name),
802:                 preferred_location: Some(preferred_location),
803:             })? {
804:                 after = self.owned_open_generated_cases(character_id);
805:                 discovered = after
806:                     .iter()
807:                     .filter(|(case_id, _)| !before.contains(case_id))
808:                     .cloned()
809:                     .collect();
810:             }
811:         }
812:         discovered.sort();
813:         let new_open_cases = discovered.len();
814:         if let Some((case_id, subject)) = discovered.into_iter().next() {
815:             self.metrics.generated_discovery_actions_fruitful = self
816:                 .metrics
817:                 .generated_discovery_actions_fruitful
818:                 .saturating_add(1);
819:             self.event(
820:                 agent,
821:                 CoreLoopEventKind::GeneratedDiscoveryResult,
822:                 format!(
823:                     "official_minute={official_minute};active_symptom_count={};oldest_symptom_age_bucket={oldest_symptom_age_bucket};visible_candidate_count={};location_class={location_class};owner_open_case_count={};public_backoff=false;dialogue_success=true;session_success=true;new_open_cases={};rumor_delivered=true;result=fruitful;reason=rumor_delivered;fallback=none;activity_fallback=false",
824:                     public_count_bucket(active_symptom_count),
825:                     visible_candidate_count.min(32),
826:                     after.len().min(32),
827:                     new_open_cases.min(32),
828:                 ),
829:             );
830:             self.generated_discovery_backoff.remove(&character_id);
831:             self.observe_generated_case_intake(
832:                 agent,
833:                 character_id,
834:                 &case_id,
835:                 &subject,
836:                 GeneratedCaseIntakeSource::DialogueRumor,
837:             );
838:             self.metrics.generated_quests_discovered += 1;
839:             self.metrics.generated_unique_party_cases_discovered += 1;
840:             let party_id = self
841:                 .connection
842:                 .db
843:                 .backend_characters()
844:                 .iter()
845:                 .find(|character| character.id == character_id)
846:                 .and_then(|character| character.party_id)
847:                 .unwrap_or_default();
848:             self.generated_case_event(
849:                 agent,
850:                 CoreLoopEventKind::GeneratedQuestDiscovered,
851:                 &party_id,
852:                 &case_id,
853:                 format!(
854:                     "party={};case={};subject={};npc={};location={}",
855:                     bounded_event_field(&party_id),
856:                     bounded_event_field(&case_id),
857:                     bounded_event_field(&subject),
858:                     bounded_event_field(&candidate.name),
859:                     bounded_event_field(&candidate.location_id)
860:                 ),
861:             );
862:             return Ok(GeneratedDiscoveryOutcome::Discovered);
863:         }
864: 
865:         self.metrics.generated_discovery_decisions_unproductive = self
866:             .metrics
867:             .generated_discovery_decisions_unproductive
868:             .saturating_add(1);
869:         self.event(
870:             agent,
871:             CoreLoopEventKind::GeneratedDiscoveryResult,
872:             format!(
873:                 "official_minute={official_minute};active_symptom_count={};oldest_symptom_age_bucket={oldest_symptom_age_bucket};visible_candidate_count={};location_class={location_class};owner_open_case_count={};public_backoff=false;dialogue_success=true;session_success=true;new_open_cases=0;rumor_delivered=false;result=unproductive;reason=no_public_rumor_available;fallback=no_public_rumor_available;activity_fallback=true",
874:                 public_count_bucket(active_symptom_count),
875:                 visible_candidate_count.min(32),
876:                 after.len().min(32),
877:             ),
878:         );
879:         self.generated_discovery_backoff.insert(
880:             character_id,
881:             PublicDiscoveryBackoff {
882:                 fingerprint: public_fingerprint,
883:                 last_contact: public_discovery_contact_identity(&candidate),
884:                 retry_at: official_time.saturating_add_minutes(PUBLIC_DISCOVERY_BACKOFF_MINUTES),
885:             },
886:         );
887:         Ok(GeneratedDiscoveryOutcome::NoPublicRumor)
888:     }
889: 
890:     pub(super) fn try_generated_dialogue_topic(
891:         &mut self,
892:         request: GeneratedDialogueTopicRequest<'_>,
893:     ) -> Result<bool, String> {
894:         let GeneratedDialogueTopicRequest {
895:             character_id,
896:             agent,
897:             cycle,
898:             case_id,
899:             subject,
900:             topics,
901:             preferred_name,
902:             preferred_location,
903:         } = request;
904:         let mut candidates =
905:             self.visible_npc_candidates(character_id, preferred_name, preferred_location);
906:         if let Some(name) = preferred_name {
907:             candidates.retain(|candidate| candidate.name.eq_ignore_ascii_case(name));
908:         }
909:         for candidate in candidates.into_iter().take(8) {
910:             let contact = public_discovery_contact_identity(&candidate);
911:             let public_before_dialogue =
912:                 self.public_dialogue_progress_fingerprint(character_id, case_id);
913:             if topics.iter().all(|topic| {
914:                 let key = PublicDialogueAttemptKey {
915:                     owner_character_id: character_id,
916:                     case_id: case_id.to_owned(),
917:                     topic_id: topic.stable_id().to_owned(),
918:                     contact: contact.clone(),
919:                 };
920:                 !public_dialogue_topic_attempt_allowed(
921:                     self.generated_dialogue_no_progress.get(&key),
922:                     &public_before_dialogue,
923:                 )
924:             }) {
925:                 continue;
926:             }
927:             let dialogue_start = self.start_public_dialogue(
928:                 character_id,
929:                 cycle,
930:                 &candidate,
931:                 GeneratedDialoguePurpose::Case,
932:             );
933:             let session_id = match dialogue_start {
934:                 Ok(PublicDialogueStartOutcome::Started(session_id)) => session_id,
935:                 Ok(PublicDialogueStartOutcome::ContactUnavailable) => continue,
936:                 Err(PublicDialogueStartError::SessionProjectionMissing) => {
937:                     let error = CoreLoopError::operation(
938:                         ReducerOperation::StartDialogue,
939:                         "owner-scoped dialogue session unavailable",
940:                     );
941:                     self.failure_recorder.record(error.clone());
942:                     return Err(error.to_string());
943:                 }
944:                 Err(PublicDialogueStartError::Reducer(error)) => return Err(error.to_string()),
945:             };
946:             let mut options = self
947:                 .connection
948:                 .db
949:                 .backend_dialogue_topic_options()
950:                 .iter()
951:                 .filter_map(|row| {
952:                     let topic = GeneratedDialogueTopic::from_stable_id(&row.topic_id)?;
953:                     (row.owner_character_id == character_id
954:                         && row.session_id == session_id
955:                         && topics.contains(&topic)
956:                         && row.public_case_id == case_id)
957:                         .then_some((topic, row))
958:                 })
959:                 .collect::<Vec<_>>();
960:             options.sort_by_key(|(topic, row)| (topic.stable_id(), row.id.clone()));
961:             let Some((topic, _option)) = options.into_iter().next() else {
962:                 continue;
963:             };
964:             let session = self
965:                 .connection
966:                 .db
967:                 .backend_dialogue_sessions()
968:                 .iter()
969:                 .find(|row| row.owner_character_id == character_id && row.id == session_id)
970:                 .ok_or("projected dialogue session disappeared")?;
971:             let action_id = format!("sim-topic-{cycle}-{}", self.sequence.saturating_add(1));
972:             let topic_id = topic.stable_id().to_owned();
973:             let attempt_key = PublicDialogueAttemptKey {
974:                 owner_character_id: character_id,
975:                 case_id: case_id.to_owned(),
976:                 topic_id: topic_id.clone(),
977:                 contact,
978:             };
979:             let public_before = self.public_dialogue_progress_fingerprint(character_id, case_id);
980:             if !public_dialogue_topic_attempt_allowed(
981:                 self.generated_dialogue_no_progress.get(&attempt_key),
982:                 &public_before,
983:             ) {
984:                 continue;
985:             }
986:             let result = reducer_call!(self, ReducerOperation::ChooseDialogueTopic, |cb| self
987:                 .connection
988:                 .reducers
989:                 .choose_dialogue_topic_then(
990:                     character_id,
991:                     session_id.clone(),
992:                     topic_id.clone(),
993:                     action_id.clone(),
994:                     session.revision,
995:                     session.catalog_revision.clone(),
996:                     cb,
997:                 ));
998:             self.call(result)?;
999:             let public_after = self.public_dialogue_progress_fingerprint(character_id, case_id);
1000:             if !public_dialogue_topic_made_progress(&public_before, &public_after) {
1001:                 self.generated_dialogue_no_progress
1002:                     .insert(attempt_key, public_before);
1003:                 continue;
1004:             }
1005:             self.generated_dialogue_no_progress.remove(&attempt_key);
1006:             if topic == GeneratedDialogueTopic::ReferredTestimony {
1007:                 self.metrics.generated_witness_dialogues += 1;
1008:                 self.event(
1009:                     agent,
1010:                     CoreLoopEventKind::GeneratedWitnessDialogue,
1011:                     format!(
1012:                         "case={};subject={};npc={};location={};topic={}",
1013:                         bounded_event_field(case_id),
1014:                         bounded_event_field(subject),
1015:                         bounded_event_field(&candidate.name),
1016:                         bounded_event_field(&candidate.location_id),
1017:                         bounded_event_field(&topic_id)
1018:                     ),
1019:                 );
1020:             } else {
1021:                 self.event(
1022:                     agent,
1023:                     CoreLoopEventKind::GeneratedInvestigationAction,
1024:                     format!(
1025:                         "case={};subject={};npc={};location={};topic={}",
1026:                         bounded_event_field(case_id),
1027:                         bounded_event_field(subject),
1028:                         bounded_event_field(&candidate.name),
1029:                         bounded_event_field(&candidate.location_id),
1030:                         bounded_event_field(&topic_id)
1031:                     ),
1032:                 );
1033:             }
1034:             self.observe_generated_case_transition(agent, character_id, case_id, subject, true);
1035:             return Ok(true);
1036:         }
1037:         Ok(false)
1038:     }
