1040:     pub(super) fn public_dialogue_progress_fingerprint(
1041:         &self,
1042:         character_id: u64,
1043:         case_id: &str,
1044:     ) -> PublicDialogueProgressFingerprint {
1045:         let mut cases = self
1046:             .connection
1047:             .db
1048:             .backend_investigation_cases()
1049:             .iter()
1050:             .filter(|row| row.owner_character_id == character_id && row.case_id == case_id)

1051:             // A journal timestamp can advance when dialogue republishes an
1052:             // already-known fact. Only a changed public case status is new
1053:             // investigative knowledge.
1054:             .map(|row| (row.case_id, row.status))
1055:             .collect::<Vec<_>>();
1056:         cases.sort();
1057:         let mut leads = self
1058:             .connection
1059:             .db
1060:             .backend_investigation_leads()
1061:             .iter()
1062:             .filter(|row| row.owner_character_id == character_id && row.case_id == case_id)
1063:             .map(|row| PublicDialogueLeadSemantic {
1064:                 summary: row.summary,
1065:                 source_label: row.source_label,
1066:                 confidence_bps: row.confidence_bps,
1067:                 destination_stage: core_destination_knowledge_stage(row.destination_stage),
1068:                 directions: row.directions,
1069:                 exact_location_id: row.exact_location_id,
1070:                 latitude_e7: row.latitude_e_7,
1071:                 longitude_e7: row.longitude_e_7,
1072:                 witness_name: row.witness_name,
1073:                 witness_description: row.witness_description,
1074:                 witness_occupation_or_relationship: row.witness_occupation_or_relationship,
1075:                 expected_location: row.expected_location,
1076:                 current_learned_location: row.current_learned_location,
1077:                 contradiction_group: row.contradiction_group,
1078:                 corrected_by: row.corrected_by,
1079:             })
1080:             .collect::<Vec<_>>();
1081:         leads.sort();
1082:         // Repeating the same testimony may republish it with a fresh row ID
1083:         // and timestamp. Treat identical public knowledge as one fact so the
1084:         // dialogue no-progress guard remains stable.
1085:         leads.dedup();
1086:         let mut actions = self
1087:             .connection
1088:             .db
1089:             .backend_investigation_actions()
1090:             .iter()
1091:             .filter(|row| row.owner_character_id == character_id && row.case_id == case_id)
1092:             .map(|row| PublicDialogueActionSemantic {
1093:                 action_id: row.action_id,
1094:                 method: row.method,
1095:                 summary: row.summary,
1096:                 known_prerequisites: row.known_prerequisites,
1097:                 duration_min_minutes: row.duration_min_minutes,
1098:                 duration_max_minutes: row.duration_max_minutes,
1099:                 uncertainty_bps: row.uncertainty_bps,
1100:                 skill_contributions: row.skill_contributions,
1101:                 weather_available: row.weather_available,
1102:                 required_case_site_id: row.required_case_site_id,
1103:                 availability: row.availability,
1104:             })
1105:             .collect::<Vec<_>>();
1106:         actions.sort_by(|left, right| left.action_id.cmp(&right.action_id));
1107:         let mut outcomes = self
1108:             .connection
1109:             .db
1110:             .backend_investigation_action_outcomes()
1111:             .iter()
1112:             .filter(|row| row.owner_character_id == character_id && row.case_id == case_id)
1113:             .map(|row| (row.outcome_id, row.action_id))
1114:             .collect::<Vec<_>>();
1115:         outcomes.sort();
1116:         let mut sites = self
1117:             .connection
1118:             .db
1119:             .backend_case_site_pins()
1120:             .iter()
1121:             .filter(|row| row.owner_character_id == character_id && row.case_id == case_id)
1122:             .map(|row| {
1123:                 (
1124:                     row.case_site_id.value,
1125:                     core_destination_knowledge_stage(row.knowledge_stage),
1126:                     row.tracked,
1127:                     row.case_resolved,
1128:                     row.combat_available,
1129:                 )
1130:             })
1131:             .collect::<Vec<_>>();
1132:         sites.sort();
1133:         PublicDialogueProgressFingerprint {
1134:             cases,
1135:             leads,
1136:             actions,
1137:             outcomes,
1138:             sites,
1139:         }
1140:     }
