1142:     pub(super) fn generated_actor_ready_after_time(
1143:         &mut self,
1144:         party_id: &str,
1145:         owner_character_id: u64,
1146:         case_id: &str,
1147:     ) -> Result<bool, String> {
1148:         self.synchronize_generated_party_for_action(party_id, owner_character_id, case_id, 0)
1149:     }
1150: 
1151:     pub(super) fn synchronize_generated_party_for_action(
1152:         &mut self,
1153:         party_id: &str,
1154:         owner_character_id: u64,
1155:         case_id: &str,
1156:         cycle: u32,
1157:     ) -> Result<bool, String> {
1158:         let Some((current_leader, leader_agent)) = self.current_leader(party_id) else {
1159:             return Ok(false);
1160:         };
1161:         if current_leader != owner_character_id {
1162:             return Ok(false);
1163:         }
1164:         let at_case_site = self.party_by_id(party_id)?.current_case_site_id.is_some();
1165:         if at_case_site {
1166:             let current_site = self
1167:                 .party_by_id(party_id)?
1168:                 .current_case_site_id
1169:                 .ok_or("case-site synchronization lost its public location")?;
1170:             let Some(pin) = self
1171:                 .connection
1172:                 .db
1173:                 .backend_case_site_pins()
1174:                 .iter()
1175:                 .find(|pin| {
1176:                     pin.owner_character_id == owner_character_id
1177:                         && pin.case_id == case_id
1178:                         && pin.case_site_id == current_site
1179:                 })
1180:             else {
1181:                 return Ok(false);
1182:             };
1183:             let medically_critical =
1184:                 self.living_party_member_ids(party_id)
1185:                     .into_iter()
1186:                     .any(|character_id| {
1187:                         self.connection
1188:                             .db
1189:                             .character_illness_status()
1190:                             .iter()
1191:                             .any(|row| row.character_id == character_id && row.critical)
1192:                     });
1193:             if medically_critical {
1194:                 if self.generated_action_return_thermal_decision(party_id, &pin, 0)
1195:                     == OnSiteActionDecision::ReturnNow
1196:                 {
1197:                     self.evacuate_generated_party_to_origin(
1198:                         party_id,
1199:                         owner_character_id,
1200:                         leader_agent,
1201:                         case_id,
1202:                         &pin,
1203:                     )?;
1204:                 }
1205:                 return Ok(false);
1206:             }
1207:             if !self.generated_case_site_sync_safe(party_id, &pin) {
1208:                 if matches!(
1209:                     self.generated_action_return_thermal_decision(party_id, &pin, 0),
1210:                     OnSiteActionDecision::Ready | OnSiteActionDecision::ReturnNow
1211:                 ) {
1212:                     self.evacuate_generated_party_to_origin(
1213:                         party_id,
1214:                         owner_character_id,
1215:                         leader_agent,
1216:                         case_id,
1217:                         &pin,
1218:                     )?;
1219:                 }
1220:                 return Ok(false);
1221:             }
1222:         }
1223:         let result = reducer_call!(self, ReducerOperation::SynchronizePartyForActivity, |cb| {
1224:             self.connection
1225:                 .reducers
1226:                 .synchronize_party_for_activity_then(owner_character_id, cb)
1227:         });
1228:         self.call(result)?;
1229:         self.observe_deaths();
1230:         if self.current_leader(party_id).map(|(leader, _)| leader) != Some(owner_character_id) {
1231:             return Ok(false);
1232:         }
1233:         let mut party_medically_ready = true;
1234:         for party_agent in self.party_agents(owner_character_id)? {
1235:             if !self.ensure_medically_safe(party_agent)? {
1236:                 party_medically_ready = false;
1237:                 self.metrics.quests_suppressed_for_health += 1;
1238:                 self.generated_case_event(
1239:                     party_agent,
1240:                     CoreLoopEventKind::QuestSuppressed,
1241:                     party_id,
1242:                     case_id,
1243:                     format!(
1244:                         "generated_case={};cycle={cycle};reason=not_ready_after_party_clock_sync",
1245:                         bounded_event_field(case_id)
1246:                     ),
1247:                 );
1248:                 continue;
1249:             }
1250:             self.maintain_equipment(party_agent)?;
1251:         }
1252:         // Recovery and maintenance advance individual clocks. Re-align after
1253:         // those actions so the preflight does not reject its own care work as
1254:         // persistent party clock skew.
1255:         if at_case_site {
1256:             let current_site = self
1257:                 .party_by_id(party_id)?
1258:                 .current_case_site_id
1259:                 .ok_or("case-site resynchronization lost its public location")?;
1260:             let Some(pin) = self
1261:                 .connection
1262:                 .db
1263:                 .backend_case_site_pins()
1264:                 .iter()
1265:                 .find(|pin| {
1266:                     pin.owner_character_id == owner_character_id
1267:                         && pin.case_id == case_id
1268:                         && pin.case_site_id == current_site
1269:                 })
1270:             else {
1271:                 return Ok(false);
1272:             };
1273:             if !self.generated_case_site_sync_safe(party_id, &pin) {
1274:                 if matches!(
1275:                     self.generated_action_return_thermal_decision(party_id, &pin, 0),
1276:                     OnSiteActionDecision::Ready | OnSiteActionDecision::ReturnNow
1277:                 ) {
1278:                     self.evacuate_generated_party_to_origin(
1279:                         party_id,
1280:                         owner_character_id,
1281:                         leader_agent,
1282:                         case_id,
1283:                         &pin,
1284:                     )?;
1285:                 }
1286:                 return Ok(false);
1287:             }
1288:         }
1289:         let result = reducer_call!(
1290:             self,
1291:             ReducerOperation::ResynchronizePartyAfterGeneratedPreflight,
1292:             |cb| self
1293:                 .connection
1294:                 .reducers
1295:                 .synchronize_party_for_activity_then(owner_character_id, cb)
1296:         );
1297:         self.call(result)?;
1298:         self.observe_deaths();
1299:         if !party_medically_ready {
1300:             return Ok(false);
1301:         }
1302:         if self
1303:             .refreshed_safe_party_for_owner(party_id, owner_character_id)?
1304:             .is_none()
1305:         {
1306:             return Ok(false);
1307:         }
1308:         Ok(true)
1309:     }
1310: 
1311:     pub(super) fn refreshed_safe_party_for_owner(
1312:         &mut self,
1313:         party_id: &str,
1314:         owner_character_id: u64,
1315:     ) -> Result<Option<(u32, Party)>, String> {
1316:         self.observe_deaths();
1317:         let Some((current_leader, current_agent)) = self.current_leader(party_id) else {
1318:             return Ok(None);
1319:         };
1320:         if current_leader != owner_character_id {
1321:             return Ok(None);
1322:         }
1323:         let party_agents = self.party_agents(current_leader)?;
1324:         if !self.unsafe_party_agents(&party_agents).is_empty() {
1325:             return Ok(None);
1326:         }
1327:         let party = self.party_for(current_leader)?;
1328:         if party.id != party_id {
1329:             return Ok(None);
1330:         }
1331:         Ok(Some((current_agent, party)))
1332:     }
