1334:     pub(super) fn emit_generated_investigation_attempt(
1335:         &mut self,
1336:         attempt: GeneratedInvestigationAttempt<'_>,
1337:     ) -> Result<(), String> {
1338:         let GeneratedInvestigationAttempt {
1339:             party_id,
1340:             character_id,
1341:             agent,
1342:             case_id,
1343:             subject,
1344:             action,
1345:             attempt,
1346:         } = attempt;
1347:         let actor_time = self
1348:             .connection
1349:             .db
1350:             .backend_character_times()
1351:             .iter()
1352:             .find(|row| row.character_id == character_id)
1353:             .map(|row| StrategicMinute::new(row.minutes.minutes))
1354:             .ok_or("projected investigation actor clock is unavailable")?;
1355:         let party_member_ids = self
1356:             .connection
1357:             .db
1358:             .party_member()
1359:             .iter()
1360:             .filter(|row| row.party_id == party_id)
1361:             .map(|row| row.character_id)
1362:             .collect::<Vec<_>>();
1363:         let mut party_times = party_member_ids
1364:             .iter()
1365:             .map(|member_id| {
1366:                 self.connection
1367:                     .db
1368:                     .backend_character_times()
1369:                     .iter()
1370:                     .find(|row| row.character_id == *member_id)
1371:                     .map(|row| StrategicMinute::new(row.minutes.minutes))
1372:                     .ok_or("projected investigation party clock is unavailable")
1373:             })
1374:             .collect::<Result<Vec<_>, _>>()?;
1375:         party_times.sort_unstable();
1376:         let party_time_min = party_times
1377:             .first()
1378:             .copied()
1379:             .ok_or("projected investigation party clock is unavailable")?;
1380:         let party_time_max = party_times
1381:             .last()
1382:             .copied()
1383:             .ok_or("projected investigation party clock is unavailable")?;
1384:         let (available, reason_code, wait_minutes) = match &action.availability {
1385:             InvestigationActionAvailability::Available => (true, "none", 0),
1386:             InvestigationActionAvailability::Unavailable(unavailable) => (
1387:                 false,
1388:                 investigation_unavailable_reason_key(unavailable.reason),
1389:                 unavailable.wait_minutes,
1390:             ),
1391:         };
1392:         self.investigation_action_event(
1393:             agent,
1394:             CoreLoopEventKind::GeneratedInvestigationAttempt,
1395:             case_id,
1396:             &action.action_id,
1397:             format!(
1398:                 "case={};subject={};action={};method={};summary={};attempt={};expected_version={};available={};unavailable_reason_code={};wait_minutes={};actor_time={actor_time};party_time_min={party_time_min};party_time_max={party_time_max}",
1399:                 bounded_event_field(case_id),
1400:                 bounded_event_field(subject),

1401:                 bounded_event_field(&action.action_id),
1402:                 bounded_event_field(&action.method),
1403:                 bounded_event_field(&action.summary),
1404:                 bounded_event_field(attempt),
1405:                 action.expected_version,
1406:                 available,
1407:                 bounded_event_field(reason_code),
1408:                 wait_minutes,
1409:             ),
1410:         );
1411:         Ok(())
1412:     }
