1414:     pub(super) fn wait_for_generated_investigation_window(
1415:         &mut self,
1416:         window: GeneratedInvestigationWindow<'_>,
1417:     ) -> Result<bool, String> {
1418:         let GeneratedInvestigationWindow {
1419:             party_id,
1420:             owner_character_id,
1421:             agent,
1422:             case_id,
1423:             action_id,
1424:             reason,
1425:             wait_minutes,
1426:         } = window;
1427:         let wait_minutes = projected_investigation_wait_minutes(reason, wait_minutes)
1428:             .ok_or("projected investigation wait hint was invalid")?;
1429:         let at_settlement = self
1430:             .party_for(owner_character_id)?
1431:             .current_settlement_id
1432:             .is_some();
1433:         let settlement_venue = if at_settlement && wait_minutes >= 60 {
1434:             self.settlement_activity_venue(owner_character_id, 0)?
1435:         } else {
1436:             None
1437:         };
1438:         if at_settlement && wait_minutes >= 60 && settlement_venue.is_none() {
1439:             self.event(
1440:                 agent,
1441:                 CoreLoopEventKind::QuestSuppressed,
1442:                 format!(
1443:                     "generated_case={};action={};reason=insufficient_visible_resources;wait_minutes={wait_minutes}",
1444:                     bounded_event_field(case_id),
1445:                     bounded_event_field(action_id),
1446:                 ),
1447:             );
1448:             return Ok(false);
1449:         }
1450:         let wait_mode = if let Some(venue) = settlement_venue {
1451:             let result = reducer_call!(
1452:                 self,
1453:                 ReducerOperation::WaitForInvestigationWindowSettlement,
1454:                 |cb| {
1455:                     self.connection.reducers.rest_at_settlement_hours_then(
1456:                         owner_character_id,
1457:                         u64::from(wait_minutes),
1458:                         stdb_settlement_action_service(venue),
1459:                         cb,
1460:                     )
1461:                 }
1462:             );
1463:             self.call(result)?;
1464:             match venue {
1465:                 DomainSettlementActionService::Inn => "settlement_inn",
1466:                 DomainSettlementActionService::Temple => "settlement_temple",
1467:             }
1468:         } else {
1469:             let shelter = self.rest_at_camp_with_party_shelter(
1470:                 owner_character_id,
1471:                 u64::from(wait_minutes),
1472:                 ReducerOperation::WaitForInvestigationWindowCamp,
1473:             )?;
1474:             if matches!(shelter, FieldShelter::Tent) {
1475:                 "field_tent"
1476:             } else {
1477:                 "field_bivouac"
1478:             }
1479:         };
1480:         self.metrics.generated_investigation_waits += 1;
1481:         self.metrics.generated_investigation_wait_minutes = self
1482:             .metrics
1483:             .generated_investigation_wait_minutes
1484:             .saturating_add(u64::from(wait_minutes));
1485:         self.event(
1486:             agent,
1487:             CoreLoopEventKind::GeneratedInvestigationWait,
1488:             format!(
1489:                 "case={};action={};reason={};wait_minutes={wait_minutes};mode={wait_mode}",
1490:                 bounded_event_field(case_id),
1491:                 bounded_event_field(action_id),
1492:                 bounded_event_field(investigation_unavailable_reason_key(reason)),
1493:             ),
1494:         );
1495:         self.generated_actor_ready_after_time(party_id, owner_character_id, case_id)
1496:     }
