1498:     pub(super) fn return_completed_generated_party_to_origin(
1499:         &mut self,
1500:         party_id: &str,
1501:         owner_character_id: u64,
1502:         case_id: &str,
1503:     ) -> Result<bool, String> {
1504:         let Some(occupied_site_id) = self.party_by_id(party_id)?.current_case_site_id else {
1505:             return Ok(true);
1506:         };
1507:         let pin = self
1508:             .connection
1509:             .db
1510:             .backend_case_site_pins()
1511:             .iter()
1512:             .find(|pin| {
1513:                 occupied_case_pin_matches(
1514:                     owner_character_id,
1515:                     case_id,
1516:                     &occupied_site_id,
1517:                     pin.owner_character_id,
1518:                     &pin.case_id,
1519:                     &pin.case_site_id,
1520:                 )
1521:             })
1522:             .ok_or("completed generated case site has no exact owner-scoped return pin")?;
1523:         let Some((current_leader, current_agent)) = self.current_leader(party_id) else {
1524:             return Ok(false);
1525:         };
1526:         let settlement_id = pin.origin_settlement_id.clone();
1527:         let result = reducer_call!(self, ReducerOperation::ReturnCompletedGeneratedCase, |cb| {
1528:             self.connection.reducers.travel_to_settlement_then(
1529:                 current_leader,
1530:                 settlement_id.clone(),
1531:                 cb,
1532:             )
1533:         });
1534:         self.call(result)?;
1535:         self.event(
1536:             current_agent,
1537:             CoreLoopEventKind::Travel,
1538:             format!("generated_case={case_id};case_completed=true;return_started={settlement_id}"),
1539:         );
1540:         let journey_outcome = self.travel_camps(party_id)?;
1541:         self.observe_deaths();
1542:         if journey_outcome == JourneyTravelOutcome::Completed {
1543:             self.event(
1544:                 current_agent,
1545:                 CoreLoopEventKind::Travel,
1546:                 format!("generated_case={case_id};return_completed={settlement_id}"),
1547:             );
1548:         }
1549:         Ok(journey_outcome == JourneyTravelOutcome::Completed)
1550:     }
1551: 
1552:     fn evacuate_generated_party_to_origin(
1553:         &mut self,
1554:         party_id: &str,
1555:         owner_character_id: u64,
1556:         _agent: u32,
1557:         case_id: &str,
