2654:     pub(super) fn turn_in_ready_direct_contract(
2655:         &mut self,
2656:         party_id: &str,
2657:         leader: u64,
2658:         leader_agent: u32,
2659:         quest: &BackendContract,
2660:     ) -> Result<(), String> {
2661:         let party = self.party_by_id(party_id)?;
2662:         let publicly_ready = party.current_settlement_id.as_deref()
2663:             == Some(quest.settlement_id.as_str())
2664:             && party.current_case_site_id.is_none()
2665:             && party.camp_destination.is_none()
2666:             && party.active_contract_id.as_deref() == Some(quest.id.as_str())
2667:             && self
2668:                 .connection
2669:                 .db
2670:                 .backend_contracts()
2671:                 .iter()
2672:                 .any(|contract| {
2673:                     contract.id == quest.id
2674:                         && contract.status == ContractStatus::ReadyToReport
2675:                         && contract.accepted_by.as_deref() == Some(party_id)
2676:                 });
2677:         if !publicly_ready {
2678:             self.event(
2679:                 leader_agent,
2680:                 CoreLoopEventKind::QuestSuppressed,
2681:                 format!(
2682:                     "quest={};reason=direct_contract_report_arrival_not_proven",
2683:                     bounded_event_field(&quest.id)
2684:                 ),
2685:             );
2686:             return Ok(());
2687:         }
2688:         if !self.public_contract_issuer_available(leader, quest) {
2689:             return self.defer_unavailable_contract_issuer(
2690:                 party_id,
2691:                 leader_agent,
2692:                 quest,
2693:                 "public_presence_projection",
2694:             );
2695:         }
2696:         let result = reducer_call!(self, ReducerOperation::InteractReportContract, |cb| self
2697:             .connection
2698:             .reducers
2699:             .simulate_contract_issuer_interaction_then(
2700:                 leader,
2701:                 quest.id.clone(),
2702:                 ContractInteractionStage::Report,
2703:                 cb,
2704:             ));
2705:         if let Err(error) = result {
2706:             if contract_issuer_unavailable_failure(&error) {
2707:                 return self.defer_unavailable_contract_issuer(
2708:                     party_id,
2709:                     leader_agent,
2710:                     quest,
2711:                     "authoritative_interaction_rejection",
2712:                 );
2713:             }
2714:             return self.call(Err(error));
2715:         }
2716:         let result = reducer_call!(self, ReducerOperation::TurnInQuest, |cb| self
2717:             .connection
2718:             .reducers
2719:             .report_contract_then(leader, quest.id.clone(), cb));
2720:         self.call(result)?;
2721:         self.metrics.quests_completed += 1;
2722:         self.metrics.direct_contracts_completed += 1;
2723:         self.direct_contract_event(
2724:             leader_agent,
2725:             CoreLoopEventKind::TurnIn,
2726:             party_id,
2727:             &quest.id,
2728:             format!(
2729:                 "party={};quest={}",
2730:                 bounded_event_field(party_id),
2731:                 bounded_event_field(&quest.id)
2732:             ),
2733:         );
2734:         Ok(())
2735:     }
2736: }

