125: pub(super) fn round_trip_walking_window_minutes(
126:     current_walking_minutes: u16,
127:     movement_minutes: u64,
128:     action_minutes: u64,
129: ) -> Option<u16> {
130:     let required = movement_minutes
131:         .checked_mul(2)?
132:         .checked_add(action_minutes)?;
133:     let required_breakpoint = required.checked_add(59)?.checked_div(60)?.checked_mul(60)?;
134:     u16::try_from(required_breakpoint.max(u64::from(current_walking_minutes)))
135:         .ok()
136:         .filter(|minutes| u64::from(*minutes) <= MINUTES_PER_DAY)
137: }
138: 
139: pub(super) fn generated_action_walking_windows(
140:     current_walking_minutes: u16,
141:     movement_minutes: u64,
142:     action_minutes: u64,
143: ) -> Vec<u16> {
144:     let mut windows = Vec::new();
145:     let mut push = |minutes: u64| {
146:         if let Ok(minutes) = u16::try_from(minutes)
147:             && (adventuresim_core::strategic_time::MIN_WALKING_MINUTES_PER_DAY
148:                 ..=adventuresim_core::strategic_time::MAX_WALKING_MINUTES_PER_DAY)
149:                 .contains(&minutes)
150:             && !windows.contains(&minutes)
151:         {
152:             windows.push(minutes);
153:         }
154:     };
155:     push(u64::from(current_walking_minutes));
156:     if let Some(widened) =
157:         round_trip_walking_window_minutes(current_walking_minutes, movement_minutes, action_minutes)
158:     {
159:         push(u64::from(widened));
160:     }
161:     let exact_action_breakpoint = movement_minutes.saturating_add(action_minutes);
162:     push(exact_action_breakpoint);
163:     push(movement_minutes);
164:     let descent_start = exact_action_breakpoint.min(u64::from(
165:         adventuresim_core::strategic_time::MAX_WALKING_MINUTES_PER_DAY,
166:     ));
167:     for minutes in (u64::from(adventuresim_core::strategic_time::MIN_WALKING_MINUTES_PER_DAY)
168:         ..descent_start)
169:         .rev()
170:     {
171:         push(minutes);
172:     }
173:     windows
174: }
