176: pub(super) fn select_generated_case_site_plan<T>(
177:     current_walking_minutes: u16,
178:     movement_minutes: u64,
179:     action_minutes: u64,
180:     current_travel_at_night: bool,
181:     starting_minute: StrategicMinute,
182:     mut evaluate: impl FnMut(u16, bool, u64) -> Option<T>,
183: ) -> Option<T> {
184:     let windows =
185:         generated_action_walking_windows(current_walking_minutes, movement_minutes, action_minutes);
186:     for travel_at_night in [current_travel_at_night, !current_travel_at_night] {
187:         for (window_index, &walking_minutes) in windows.iter().enumerate() {
188:             if adventuresim_core::strategic_time::is_walking_time(
189:                 starting_minute,
190:                 walking_minutes,
191:                 travel_at_night,
192:             ) && let Some(plan) = evaluate(walking_minutes, travel_at_night, 0)
193:             {
194:                 return Some(plan);
195:             }
196:             let candidate_waits = if window_index < 4 {
197:                 generated_safe_departure_waits(starting_minute, walking_minutes, travel_at_night)
198:             } else {
199:                 generated_daily_walking_start_waits(
200:                     starting_minute,
201:                     walking_minutes,
202:                     travel_at_night,
203:                 )
204:             };
205:             for wait_minutes in candidate_waits {
206:                 if let Some(plan) = evaluate(walking_minutes, travel_at_night, wait_minutes) {
207:                     return Some(plan);
208:                 }
209:             }
210:         }
211:     }
212:     None
213: }
