235: pub(super) fn generated_action_score(
236:     profile: &AgentProfile,
237:     action: &BackendInvestigationAction,
238: ) -> (u8, u32, u16, u32, u32) {
239:     let progress = match projected_investigation_action_state(&action.availability) {
240:         ProjectedInvestigationActionState::Available => 3,
241:         ProjectedInvestigationActionState::Travel => 2,
242:         ProjectedInvestigationActionState::Wait(_) => 1,
243:         ProjectedInvestigationActionState::Blocked => 0,
244:     };
245:     let wait_minutes = match &action.availability {
246:         InvestigationActionAvailability::Available => 0,
247:         InvestigationActionAvailability::Unavailable(unavailable) => unavailable.wait_minutes,
248:     };
249:     (
250:         progress,
251:         generated_method_skill_fit(profile, &action.method),
252:         10_000_u16.saturating_sub(action.uncertainty_bps),
253:         u32::MAX.saturating_sub(action.duration_max_minutes),
254:         u32::MAX.saturating_sub(wait_minutes),
255:     )
256: }
