280: pub(crate) fn balanced_party_groups(

281:     profiles: &[AgentProfile],
282:     party_size: usize,
283: ) -> Vec<Vec<usize>> {
284:     let group_count = profiles.len().div_ceil(party_size);
285:     if group_count == 0 {
286:         return Vec::new();
287:     }
288:     let mut targets = vec![profiles.len() / group_count; group_count];
289:     for target in targets.iter_mut().take(profiles.len() % group_count) {
290:         *target += 1;
291:     }
292:     let mut order = (0..profiles.len()).collect::<Vec<_>>();
293:     order.sort_by_key(|&index| {
294:         (
295:             role_rank(profiles[index].build.role),
296:             profiles[index].agent_id,
297:         )
298:     });
299:     let mut groups = vec![Vec::new(); group_count];
300:     let mut cursor = 0;
301:     for index in order {
302:         let group = (0..group_count)
303:             .map(|offset| (cursor + offset) % group_count)
304:             .find(|&group| groups[group].len() < targets[group])
305:             .expect("party target capacity covers every profile");
306:         groups[group].push(index);
307:         cursor = (group + 1) % group_count;
308:     }
309:     for group in &mut groups {
310:         group.sort_by_key(|&index| {
311:             (
312:                 profiles[index].build.activity_only,
313:                 profiles[index].agent_id,
314:             )
315:         });
316:     }
317:     groups
318: }
