346: pub(super) enum ProjectedInvestigationActionState {
347:     Available,
348:     Travel,
349:     Wait(u32),
350:     Blocked,
351: }
352: 
353: pub(super) fn projected_investigation_action_state(
354:     availability: &InvestigationActionAvailability,
355: ) -> ProjectedInvestigationActionState {
356:     match availability {
357:         InvestigationActionAvailability::Available => ProjectedInvestigationActionState::Available,
358:         InvestigationActionAvailability::Unavailable(unavailable)
359:             if unavailable.can_travel_to_required_site =>
360:         {
361:             ProjectedInvestigationActionState::Travel
362:         }
363:         InvestigationActionAvailability::Unavailable(unavailable) => {
364:             projected_investigation_wait_minutes(unavailable.reason, unavailable.wait_minutes)
365:                 .map_or(ProjectedInvestigationActionState::Blocked, |minutes| {
366:                     ProjectedInvestigationActionState::Wait(minutes)
367:                 })
