457: pub(super) fn projected_case_site_journey_minutes(
458:     distance_m: u64,
459:     walking_minutes_per_day: u16,
460: ) -> Option<u64> {
461:     if distance_m == 0
462:         || walking_minutes_per_day == 0
463:         || u64::from(walking_minutes_per_day) > MINUTES_PER_DAY
464:     {
465:         return None;
466:     }
467:     let movement_minutes = case_site_movement_minutes(distance_m)?;
468:     let walking_minutes = u64::from(walking_minutes_per_day);
469:     let completed_walking_days = movement_minutes.saturating_sub(1) / walking_minutes;
470:     Some(
471:         movement_minutes
472:             .saturating_add(
473:                 completed_walking_days
474:                     .saturating_mul(MINUTES_PER_DAY.saturating_sub(walking_minutes)),
475:             )
476:             .saturating_mul(JOURNEY_PROVISION_ELAPSED_BOUND_FACTOR),
477:     )
478: }
