480: pub(super) fn projected_camp_rest_minutes(
481:     completed_elapsed_minutes: u64,
482:     total_elapsed_minutes: u64,
483:     intervals: &[JourneyCampInterval],
484: ) -> Option<(u64, u64)> {
485:     if completed_elapsed_minutes >= total_elapsed_minutes {
486:         return None;
487:     }
488:     let mut active = intervals.iter().filter_map(|camp| {
489:         let camp_start = camp.elapsed_start_minute.max(completed_elapsed_minutes);
490:         let camp_end = camp
491:             .elapsed_start_minute
492:             .saturating_add(camp.elapsed_minutes)
493:             .min(total_elapsed_minutes);
494:         (camp.elapsed_start_minute <= completed_elapsed_minutes && camp_end > camp_start)
495:             .then(|| (camp_start, camp_end - camp_start))
496:     });
497:     let result = active.next()?;
498:     active.next().is_none().then_some(result)
499: }
500: 
501: pub(super) fn projected_active_camp_interval_count(
502:     completed_elapsed_minutes: u64,
503:     total_elapsed_minutes: u64,
504:     intervals: &[JourneyCampInterval],
505: ) -> usize {
506:     if completed_elapsed_minutes >= total_elapsed_minutes {
507:         return 0;
508:     }
509:     intervals
510:         .iter()
511:         .filter(|camp| {
512:             let camp_start = camp.elapsed_start_minute.max(completed_elapsed_minutes);
513:             let camp_end = camp
514:                 .elapsed_start_minute
515:                 .saturating_add(camp.elapsed_minutes)
516:                 .min(total_elapsed_minutes);
517:             camp.elapsed_start_minute <= completed_elapsed_minutes && camp_end > camp_start
518:         })
519:         .count()
520: }
