90: pub(super) fn classify_post_rest_progress(
91:     before_completed_elapsed: u64,
92:     requested_rest_minutes: u64,
93:     after_completed_elapsed: u64,
94:     after_total_elapsed: u64,
95:     interrupted: bool,
96:     terminal_state_change: bool,
97: ) -> Result<PostRestProgress, &'static str> {
98:     if after_completed_elapsed > after_total_elapsed {
99:         return Err("post_rest_completed_after_total");
100:     }
101:     let actual_rest_minutes = after_completed_elapsed
102:         .checked_sub(before_completed_elapsed)
103:         .ok_or("post_rest_progress_regressed")?;
104:     if actual_rest_minutes > requested_rest_minutes {
105:         return Err("post_rest_overshot_request");
106:     }
107:     if terminal_state_change {
108:         return Ok(PostRestProgress::TerminalBoundary {
109:             actual_rest_minutes,
110:         });
111:     }
112:     if actual_rest_minutes == 0 {
113:         return Err("post_rest_zero_progress");
114:     }
115:     if actual_rest_minutes < requested_rest_minutes {
116:         return if interrupted {
117:             Ok(PostRestProgress::InterruptedShort {
118:                 actual_rest_minutes,
119:             })
120:         } else {
121:             Err("post_rest_short_without_interruption")
122:         };
123:     }
124:     Ok(PostRestProgress::Exact {
125:         actual_rest_minutes,
126:     })
127: }
