129: pub(super) fn public_alive_to_dead_ids(before: &[(u64, bool)], after: &[(u64, bool)]) -> Vec<u64> {
130:     let mut deaths = before
131:         .iter()
132:         .filter(|(_, alive)| *alive)
133:         .filter_map(|(character_id, _)| {
134:             after
135:                 .iter()
136:                 .find(|(after_id, _)| after_id == character_id)
137:                 .is_some_and(|(_, alive)| !*alive)
138:                 .then_some(*character_id)
139:         })
140:         .collect::<Vec<_>>();
141:     deaths.sort_unstable();
142:     deaths
143: }
