148:     after: &[(u64, StrategicMinute)],
149: ) -> Option<u64> {
150:     terminal_ids
151:         .iter()
152:         .map(|character_id| {
153:             let before_elapsed = before
154:                 .iter()
155:                 .find(|(before_id, _)| before_id == character_id)?
156:                 .1;
157:             let after_elapsed = after
158:                 .iter()
159:                 .find(|(after_id, _)| after_id == character_id)?
160:                 .1;
161:             after_elapsed.checked_elapsed_since(before_elapsed)
162:         })
163:         .collect::<Option<Vec<_>>>()?
164:         .into_iter()
165:         .min()
