178: pub(super) fn classify_post_encounter_journey(
179:     state: PublicPostEncounterJourneyState,
180: ) -> Result<PostEncounterJourneyAction, &'static str> {
181:     if state.unresolved_encounter || !state.active_destination {
182:         return Ok(PostEncounterJourneyAction::ReclassifyPublicState);
183:     }
184:     if state.journey_count != 1 || !state.destination_matches {
185:         return Err("post_encounter_journey_projection_mismatch");
186:     }
187:     if !state.actionable_actor {
188:         return Ok(PostEncounterJourneyAction::HoldNoActionableActor);
189:     }
190:     if state.unsafe_member_count > 0 && !state.evacuation {
191:         return Ok(PostEncounterJourneyAction::HoldForRecovery);
192:     }
193:     match state.active_interval_count {
194:         0 => Ok(PostEncounterJourneyAction::ContinueTravel),
195:         1 => Ok(PostEncounterJourneyAction::HandleActiveCamp),
196:         _ => Err("post_encounter_overlapping_active_camps"),
197:     }
198: }
