79: /// Score only the observer-safe weighted differential and public generic
80: /// preparation profiles. Positive values mean expected meter relief exceeds
81: /// direct and adverse meter burden. Quantization makes tie-breaking replayable.
82: fn public_intervention_score(
83:     differential: &[BackendPhysiologyDifferential],
84:     profile: &adventuresim_core::physiology::InterventionProfile,
85: ) -> i64 {
86:     const INTERVENTION_SCORE_SCALE: f64 = 1_000_000.0;
87:     use adventuresim_core::physiology::{METER_COUNT, Meter};
88:     let total_likelihood = differential
89:         .iter()
90:         .filter(|row| row.disease_id.parse::<adventuresim_core::disease::DiseaseId>().is_ok())
91:         .map(|row| u64::from(row.likelihood_bps))
92:         .sum::<u64>();
93:     if total_likelihood == 0 {
94:         return 0;
95:     }
96:     let mut expected_loss = [0.0_f64; METER_COUNT];
97:     for row in differential {
98:         let Ok(disease_id) = row.disease_id.parse::<adventuresim_core::disease::DiseaseId>() else {
99:             continue;
100:         };
101:         let weight = f64::from(row.likelihood_bps) / total_likelihood as f64;
102:         for (meter, peak_loss) in adventuresim_core::disease::disease_peak_meters(disease_id) {
103:             expected_loss[meter.index()] += weight * f64::from(*peak_loss).max(0.0);
104:         }
105:     }
106:     let mut benefit = 0.0_f64;
107:     let mut burden = 0.0_f64;
108:     for meter in Meter::ALL {
109:         let expected = expected_loss[meter.index()];
110:         let direct = f64::from(profile.loss_delta_per_unit.get(meter));
111:         benefit += expected * (-direct).max(0.0);
112:         burden += expected * direct.max(0.0);
113:         let adverse = f64::from(profile.adverse_delta_per_unit.get(meter)).max(0.0);
114:         burden += adverse * (0.5 + expected);
115:     }
116:     ((benefit - burden) * INTERVENTION_SCORE_SCALE).round() as i64
117: }
