139: fn choose_medical_action(context: MedicalActionContext) -> (MedicalChoice, &'static str) {
140:     let MedicalActionContext {
141:         condition_status,
142:         symptomatic,
143:         at_settlement,
144:         intervention_available,
145:         purse,
146:         observable_quote,
147:         natural_rest_venue,
148:         medicated_rest_venue,
149:     } = context;
150:     if condition_status == DomainIncapacitationStatus::Ready && !symptomatic {
151:         return (MedicalChoice::Ready, "ready_without_symptoms");
152:     }
153:     if !at_settlement {
154:         return (MedicalChoice::SuppressQuest, "not_at_settlement");
155:     }
156:     if natural_rest_venue.is_none() {
157:         return (
158:             MedicalChoice::SuppressQuest,
159:             "rest_venue_unavailable_or_unaffordable",
160:         );
161:     }
162:     if !symptomatic {
163:         return (
164:             MedicalChoice::RestNaturally,
165:             "convalescing_without_symptoms",
166:         );
167:     }
168:     if !intervention_available {
169:         return (MedicalChoice::RestNaturally, "intervention_unavailable");
170:     }
171:     let Some(quote) = observable_quote else {
172:         return (MedicalChoice::RestNaturally, "observable_quote_unavailable");
173:     };
174:     if purse < quote || medicated_rest_venue.is_none() {
175:         return (MedicalChoice::RestNaturally, "observable_care_unaffordable");
176:     }
177:     (MedicalChoice::BuyAndRest, "symptomatic_and_affordable")
178: }
