324: fn reallocate_disabled_crime_to_labor(mut schedule: ScheduleAllocation) -> ScheduleAllocation {
325:     let disabled_crime_minutes = schedule
326:         .thievery_minutes
327:         .checked_add(schedule.raiding_minutes)
328:         .expect("valid daily schedule crime allocation");
329:     schedule.labor_minutes = schedule
330:         .labor_minutes
331:         .checked_add(disabled_crime_minutes)
332:         .expect("valid daily schedule labor allocation");
333:     schedule.thievery_minutes = 0;
334:     schedule.raiding_minutes = 0;
335:     schedule
336: }
