338: fn live_schedule(profile: &AgentProfile) -> ScheduleAllocation {
339:     let s = profile.schedule;
340:     // The live reducer accepts quarter-hour allocations. Native profiles are
341:     // intentionally more granular, so use the conservative lower notch and
342:     // leave the remainder as leisure instead of failing after medical rest.
343:     let quarter_hour = |minutes: u16| minutes / 15 * 15;
344:     reallocate_disabled_crime_to_labor(ScheduleAllocation {
345:         reading_minutes: 0,
346:         combat_training_minutes: quarter_hour(s.combat_training_minutes),
347:         carousing_minutes: quarter_hour(s.carousing_minutes),
348:         socializing_minutes: 0,
349:         // Simulation profiles may express future profession preferences that
350:         // the disposable character has not learned yet. Do not submit those
351:         // locked activities to the authoritative schedule reducer.
352:         apprenticeship_minutes: 0,
353:         apprenticeship_organization_id: None,
354:         profession_practice_minutes: 0,
355:         practice_organization_id: None,
356:         labor_minutes: quarter_hour(s.labor),
357:         prayer_minutes: quarter_hour(s.prayer),
358:         // Crime activities can open a tactical incident and move the party to
359:         // its case site. This authoritative evaluator deliberately leaves the
360:         // tactical layer untouched. Preserve the authored time allocation by
361:         // assigning those minutes to legal subsistence labor instead.
362:         thievery_minutes: quarter_hour(s.thievery),
363:         raiding_minutes: quarter_hour(s.raiding),
364:     })
365: }
366: 
367: fn schedule_allocated_minutes(schedule: &ScheduleAllocation) -> u16 {
368:     [
369:         schedule.combat_training_minutes,
370:         schedule.carousing_minutes,
371:         schedule.socializing_minutes,
372:         schedule.apprenticeship_minutes,
373:         schedule.profession_practice_minutes,
374:         schedule.labor_minutes,
375:         schedule.prayer_minutes,
376:         schedule.thievery_minutes,
377:         schedule.raiding_minutes,
378:         schedule.reading_minutes,
379:     ]
380:     .into_iter()
381:     .sum()
382: }
