384: fn activity_schedule_plan(
385:     profile: &AgentProfile,
386:     temple_food_covers_day: bool,
387:     purse: u64,
388:     committed_reserve: u64,
389:     inn_cost: Option<u64>,
390: ) -> (ScheduleAllocation, &'static str, &'static str) {
391:     let mut schedule = live_schedule(profile);
392:     let crime_fallback = matches!(
393:         profile.preferred_activity,
394:         ActivityPreference::Thievery | ActivityPreference::Raiding
395:     );
396:     let reserve_pressure =
397:         inn_cost.is_some_and(|cost| purse <= committed_reserve.saturating_add(cost));
398:     if schedule.labor_minutes == 0 && !temple_food_covers_day && reserve_pressure {
399:         let prayer_minutes = schedule.prayer_minutes;
400:         schedule.prayer_minutes = 0;
401:         if prayer_minutes > 0 {
402:             schedule.labor_minutes = prayer_minutes;
403:         } else {
404:             let daily_minutes = u16::try_from(MINUTES_PER_DAY)
405:                 .expect("strategic day length must fit the persisted schedule width");
406:             let discretionary_minutes =
407:                 daily_minutes.saturating_sub(schedule_allocated_minutes(&schedule));
408:             schedule.labor_minutes = discretionary_minutes.min(480);
409:         }
410:         if schedule.labor_minutes > 0 {
411:             return (schedule, "Labor", "subsistence_reserve_to_labor");
412:         }
413:     }
414:     if crime_fallback {
415:         (schedule, "Labor", "crime_disabled_to_labor")
416:     } else {
417:         (
418:             schedule,
419:             match profile.preferred_activity {
420:                 ActivityPreference::Labor => "Labor",
421:                 ActivityPreference::Prayer => "Prayer",
422:                 ActivityPreference::Thievery | ActivityPreference::Raiding => {
423:                     unreachable!("crime preferences are handled above")
424:                 }
425:             },
426:             "none",
427:         )
428:     }
429: }
