232: /// Additive run-flight waveform with contacts at 0/.5 and flight peaks at
233: /// .25/.75. Authored joint translation remains the base pose. This is
234: /// presentation-only and is never applied to the authoritative owner/controller
235: /// transform.
236: pub(super) fn locomotion_height_wave(
237:     skeleton: &SkeletonState,
238: ) -> AnimationValueResult<HeightDistance> {
239:     if !skeleton.is_grounded()
240:         || skeleton.is_posture_transitioning()
241:         || skeleton.action_kind() != SkeletonAction::None
242:     {
243:         return Ok(HeightDistance::ZERO);
244:     }
245:     if skeleton.weapon_guard() == WeaponGuardState::Raised && !skeleton.is_guarded_sprinting() {
246:         return Ok(HeightDistance::ZERO);
247:     }
248:     let speed = skeleton.animation_speed()?;
249:     if speed <= playback_tuning().initial_locomotion_speed_metres_per_second {
250:         return Ok(HeightDistance::ZERO);
251:     }
252:     let profile = locomotion_profile(skeleton, speed)?;
253:     let moving_weight = smoothstep(
254:         playback_tuning()
255:             .initial_locomotion_speed_metres_per_second
256:             .metres_per_second(),
257:         runtime_animation_config()
258:             .locomotion
259:             .blend_speed
260:             .metres_per_second(),
261:         speed.metres_per_second(),
262:     );
263:     if profile.flight_apex_metres <= HeightDistance::ZERO {
264:         return Ok(HeightDistance::ZERO);
265:     }
266:     profile.flight_apex_metres.flight_wave(
267:         skeleton.gait_phase,
268:         UnitInterval::from_fraction(moving_weight).map_err(|error| {
269:             AnimationValueError::from(error).for_quantity(AnimationQuantity::HeightDistance)
270:         })?,
271:     )
272: }
273: pub(super) fn authored_height_compensation(
274:     skeleton: &SkeletonState,
275: ) -> AnimationValueResult<HeightDistance> {
276:     if !skeleton.is_grounded()
277:         || skeleton.action_kind() != SkeletonAction::None
278:         || skeleton.animation_pack != AnimationPackId::HUMANOID_UNARMED
279:         || skeleton.posture() != Posture::Upright
280:         || skeleton.weapon_guard() != WeaponGuardState::Lowered
281:     {
282:         return Ok(HeightDistance::ZERO);
283:     }
284:     let run_weight = locomotion_profile(skeleton, skeleton.animation_speed()?)?
285:         .flight_apex_metres
286:         .metres()
287:         / run_locomotion_profile().flight_apex_metres.metres();
288:     if !run_weight.is_finite() {
289:         return Err(AnimationValueError::Overflow {
290:             quantity: AnimationQuantity::HeightDistance,
291:         });
292:     }
293:     procedural_tuning()
294:         .authored_ordinary_passing_rise_metres
295:         .scaled_by(UnitInterval::from_fraction(run_weight.clamp(0.0, 1.0))?)?
296:         .scaled_by(
297:             UnitInterval::from_fraction(smoothstep(
298:                 playback_tuning()
299:                     .initial_locomotion_speed_metres_per_second
300:                     .metres_per_second(),
301:                 runtime_animation_config()
302:                     .locomotion
303:                     .blend_speed
304:                     .metres_per_second(),
305:                 skeleton.animation_speed()?.metres_per_second(),
306:             ))
307:             .map_err(|error| {
308:                 AnimationValueError::from(error).for_quantity(AnimationQuantity::HeightDistance)
309:             })?,
310:         )
311: }
