348: fn grounded_height_wave(
349:     phase: CyclePhase,
350:     amplitude: HeightDistance,
351: ) -> AnimationValueResult<HeightDistance> {
352:     // A native periodic metre-amplitude kernel; the signed offset is computed afterward.
353:     let sine = (phase.wrapped().cycles() * std::f32::consts::TAU).sin();
354:     HeightDistance::from_arithmetic(amplitude.metres() * sine * sine)
355: }
