1: //! Checked signed offsets in the presentation height frame.
2: 
3: use adventuresim_building_generator::spatial_geometry::SignedLength;
4: use adventuresim_tactical_core::animation::{
5:     AnimationQuantity, AnimationValueError, AnimationValueResult,
6: };
7: pub(crate) use adventuresim_tactical_core::animation::{HeightDistance, HeightSpeed};
8: 
9: /// Advance a signed retained offset in its metre frame, rejecting intermediate overflow.
10: pub(super) fn advance_offset(
11:     current: SignedLength,
12:     maximum_delta: HeightDistance,
13: ) -> AnimationValueResult<SignedLength> {
14:     let difference = -current.metres();
15:     offset_result(
16:         current.metres()
17:             + difference.clamp(
18:                 -maximum_delta.metres().max(0.0),
19:                 maximum_delta.metres().max(0.0),
20:             ),
21:     )
22: }
23: pub(super) fn subtract_offsets(
24:     left: SignedLength,
25:     right: SignedLength,
26: ) -> AnimationValueResult<SignedLength> {
27:     offset_result(left.metres() - right.metres())
28: }
29: pub(super) fn add_offsets(
30:     left: SignedLength,
31:     right: SignedLength,
32: ) -> AnimationValueResult<SignedLength> {
33:     offset_result(left.metres() + right.metres())
34: }
35: fn offset_result(value: f32) -> AnimationValueResult<SignedLength> {
36:     SignedLength::from_metres(value).map_err(|_| AnimationValueError::Overflow {
37:         quantity: AnimationQuantity::HeightOffset,
38:     })
39: }
