37: /// Readiness requires a resolved procedural mesh, its material and a bound skin.
38: /// Loading cuboid proxies never qualify as captured armor.
39: #[derive(SystemParam)]
40: pub(in crate::animation_viewer) struct EquipmentVisualStatus<'w, 's> {
41:     roots: Query<
42:         'w,
43:         's,
44:         (
45:             &'static ItemPlaceholder,
46:             Has<ProceduralEquipmentResolved>,
47:             Has<ProceduralEquipmentFailed>,
48:         ),
49:     >,
50:     parts: Query<'w, 's, EquipmentRenderPart>,
51:     meshes: Res<'w, Assets<Mesh>>,
52:     materials: Res<'w, Assets<StandardMaterial>>,
53:     images: Res<'w, Assets<Image>>,
54:     render_materials: Option<Res<'w, Assets<InteriorMaterial>>>,
55: }
