1: //! Inspect the four affine coefficients consumed by Bevy's actual vertex shader.
2: use bevy::{mesh::VertexAttributeValues, prelude::*};
3: use serde::Serialize;
4: 
5: const PRIMARY_WEIGHT_SUM_TOLERANCE: f32 = 1e-4;
6: 
7: #[derive(Serialize)]
8: pub(super) struct WeightSummary {
9:     pub vertices: usize,
10:     pub minimum_sum: Option<f32>,
11:     pub maximum_sum: Option<f32>,
12:     pub invalid_vertices: usize,
13: }
14: 
15: impl WeightSummary {
16:     pub fn from_mesh(mesh: &Mesh) -> Option<Self> {
17:         let VertexAttributeValues::Float32x4(weights) =
18:             mesh.attribute(Mesh::ATTRIBUTE_JOINT_WEIGHT)?
19:         else {
20:             return None;
21:         };
22:         let mut result = Self {
23:             vertices: weights.len(),
24:             minimum_sum: None,
25:             maximum_sum: None,
26:             invalid_vertices: 0,
27:         };
28:         for weights in weights {
29:             let sum = weights.iter().sum::<f32>();
30:             if sum.is_finite() {
31:                 result.minimum_sum = Some(result.minimum_sum.map_or(sum, |old| old.min(sum)));
32:                 result.maximum_sum = Some(result.maximum_sum.map_or(sum, |old| old.max(sum)));
33:             }
34:             if weights
35:                 .iter()
36:                 .any(|weight| !weight.is_finite() || *weight < 0.0)
37:                 || (sum - 1.0).abs() > PRIMARY_WEIGHT_SUM_TOLERANCE
38:             {
39:                 result.invalid_vertices += 1;
40:             }
41:         }
42:         Some(result)
43:     }
44: 
45:     pub fn valid(&self) -> bool {
46:         self.vertices > 0 && self.invalid_vertices == 0
47:     }
48: }

