4: pub(super) fn occupancies(
5:     item: &ItemDefinition,
6:     placement: &EquipmentPlacement,
7:     previous: &[(&ItemDefinition, Entity, &EquipmentPlacement)],
8: ) -> Vec<EquipmentTopologyOccupancy> {
9:     let mut result = placement
10:         .occupancy
11:         .iter()
12:         .enumerate()
13:         .map(|(index, requirement)| EquipmentTopologyOccupancy {
14:             occupancy_id: format!("armor-review:{}:{}:{index}", item.id, placement.id),
15:             anchor: TacticalEquipmentAnchor::CharacterLocation(requirement.location),
16:             channel: requirement.channel,
17:             order: requirement.order,
18:             requirement_index: index as u16,
19:             capacity_index: 0,
20:         })
21:         .collect::<Vec<_>>();
22:     let equipment = item.equipment.as_ref().expect("harness equipment");
23:     for (index, requirement) in placement.parents.iter().enumerate() {
24:         let (parent, point) = previous
25:             .iter()
26:             .find_map(|(definition, entity, parent_placement)| {
27:                 if requirement.location.is_some_and(|location| {
28:                     !parent_placement
29:                         .occupancy
30:                         .iter()
31:                         .any(|occupied| occupied.location == location)
32:                 }) {
33:                     return None;
34:                 }
35:                 definition
36:                     .equipment
37:                     .as_ref()?
38:                     .attachment_points
39:                     .iter()
40:                     .find(|point| {
41:                         point.channel == requirement.channel
42:                             && point.order == requirement.order
43:                             && point.capacity > 0
44:                             && (point.accepts_tags.is_empty()
45:                                 || point
46:                                     .accepts_tags
47:                                     .iter()
48:                                     .any(|tag| equipment.attachment_tags.contains(tag)))
49:                     })
50:                     .map(|point| (*entity, point))
51:             })
52:             .expect("harness must equip a compatible supporting garment first");
53:         result.push(EquipmentTopologyOccupancy {
54:             occupancy_id: format!("armor-review:{}:{}:parent:{index}", item.id, placement.id),
55:             anchor: TacticalEquipmentAnchor::ItemAttachment {
56:                 parent,
57:                 attachment_point_id: point.id.clone(),
58:             },
59:             channel: requirement.channel,
60:             order: requirement.order,
61:             requirement_index: index as u16,
62:             capacity_index: 0,
63:         });
64:     }
65:     result
66: }
