38: pub(super) fn inspect_materials(
39:     inspection: Res<CaptureInspection>,
40:     parts: Query<(&ProceduralEquipmentPart, &MeshMaterial3d<InteriorMaterial>)>,
41:     items: Query<&ItemProperties>,
42:     mut materials: ResMut<Assets<InteriorMaterial>>,
43: ) {
44:     if !inspection.diffuse_armor {
45:         return;
46:     }
47:     for (part, handle) in &parts {
48:         let (Ok(item), Some(mut material)) = (items.get(part.item), materials.get_mut(&handle.0))
49:         else {
50:             continue;
51:         };
52:         let alpha = if item.id == "cuirass" {
53:             SUPPORTING_CUIRASS_ALPHA
54:         } else {
55:             1.0
56:         };
57:         if material.base.metallic == 0.0 && material.base.base_color.alpha() == alpha {
58:             continue;
59:         }
60:         material.base.metallic = 0.0;
61:         material.base.perceptual_roughness = 1.0;
62:         material.base.base_color.set_alpha(alpha);
63:         if alpha < 1.0 {
64:             material.base.alpha_mode = AlphaMode::Blend;
65:         }
66:     }
