1: //! Sustained catastrophic horizontal foot-displacement acceptance policy.
2: 
3: use super::{BoneRole, FrameSample, body_local, procedural_leg_solver_gates_apply};
4: use bevy::prelude::*;
5: 
6: const CATASTROPHIC_FOOT_HORIZONTAL_HIP_OFFSET_METRES: f32 = 0.65;
7: const CATASTROPHIC_FOOT_DISPLACEMENT_SECONDS: f32 = 0.1;
8: 
9: pub(in crate::animation_viewer::report) fn catastrophic_foot_displacement(
10:     frames: &[FrameSample],
11: ) -> bool {
12:     let mut duration = 0.0_f32;
13:     for pair in frames.windows(2) {
14:         let [before, after] = pair else {
15:             continue;
16:         };
17:         if before.scenario != after.scenario || !procedural_leg_solver_gates_apply(&after.scenario)
18:         {
19:             duration = 0.0;
20:             continue;
21:         }
22:         let displaced = [
23:             (BoneRole::ThighLeft, BoneRole::FootLeft),
24:             (BoneRole::ThighRight, BoneRole::FootRight),
25:         ]
26:         .into_iter()
27:         .any(|(hip, foot)| {
28:             body_local(after, hip)
29:                 .zip(body_local(after, foot))
30:                 .is_some_and(|(hip, foot)| catastrophic_horizontal_foot_offset(hip, foot))
31:         });
32:         if displaced {
33:             duration += (after.time_seconds.seconds() - before.time_seconds.seconds()).max(0.0);
34:             if duration >= CATASTROPHIC_FOOT_DISPLACEMENT_SECONDS {
35:                 return true;
36:             }
37:         } else {
38:             duration = 0.0;
39:         }
40:     }
41:     false
42: }
43: 
44: fn catastrophic_horizontal_foot_offset(hip: Vec3, foot: Vec3) -> bool {
45:     (foot - hip).xz().length() > CATASTROPHIC_FOOT_HORIZONTAL_HIP_OFFSET_METRES
46: }
