1: //! Peak prominence and phase-window checks for sampled visual height.
2: 
3: // Ignore sub-3 mm sampling noise, but reject any additional visible beat in
4: // the phase-owned vertical curve.
5: const HEIGHT_PEAK_PROMINENCE_METRES: f32 = 0.003;
6: const PASSING_PEAK_PHASE_WINDOW: f32 = 0.10;
7: 
8: pub(super) fn prominent_height_peaks(samples: &[(f32, f32)]) -> (usize, bool) {
9:     if samples.len() < 3 {
10:         return (0, false);
11:     }
12:     let mut peaks = Vec::new();
13:     for (index, &(phase, height)) in samples.iter().enumerate() {
14:         let previous = samples[(index + samples.len() - 1) % samples.len()].1;
15:         let next = samples[(index + 1) % samples.len()].1;
16:         if height <= previous || height < next {
17:             continue;
18:         }
19:         let left_minimum = samples
20:             .iter()
21:             .filter_map(|&(candidate_phase, candidate_height)| {
22:                 let distance = (phase - candidate_phase).rem_euclid(1.0);
23:                 (distance > 0.0 && distance <= 0.125).then_some(candidate_height)
24:             })
25:             .fold(f32::INFINITY, f32::min);
26:         let right_minimum = samples
27:             .iter()
28:             .filter_map(|&(candidate_phase, candidate_height)| {
29:                 let distance = (candidate_phase - phase).rem_euclid(1.0);
30:                 (distance > 0.0 && distance <= 0.125).then_some(candidate_height)
31:             })
32:             .fold(f32::INFINITY, f32::min);
33:         let prominence = height - left_minimum.max(right_minimum);
34:         if prominence >= HEIGHT_PEAK_PROMINENCE_METRES {
35:             peaks.push(phase);
36:         }
37:     }
38:     let phase_distance = |phase: f32, target: f32| {
39:         let distance = (phase - target).abs();
40:         distance.min(1.0 - distance)
41:     };
42:     let in_passing_windows = [0.25, 0.75].into_iter().all(|target| {
43:         peaks
44:             .iter()
45:             .filter(|&&phase| phase_distance(phase, target) <= PASSING_PEAK_PHASE_WINDOW)
46:             .count()
47:             == 1
48:     });
49:     (peaks.len(), in_passing_windows)
50: }
