379:         let horizontal = Vec3::new(outward.x, 0.0, outward.z).normalize_or_zero();
380:         let alignment = self
381:             .root_directions
382:             .iter()
383:             .map(|direction| horizontal.dot(*direction).max(0.0).powi(8))
384:             .fold(0.0_f32, f32::max);
385:         let base = self
386:             .segments
387:             .iter()
388:             .map(|segment| segment.start.y)
389:             .fold(f32::INFINITY, f32::min);
390:         let height_fade = (1.0 - ((point.y - base) / 1.35).clamp(0.0, 1.0)).powi(2);
391:         self.bark.root_lobe_height_metres * alignment * height_fade
392:     }
