55: fn sample_field(
56:     dimensions: [usize; 3],
57:     position_at: &(impl Fn([usize; 3]) -> Vec3 + Sync),
58:     field: &(impl Fn(Vec3) -> TerrainRecipeResult<f32> + Sync),
59: ) -> TerrainRecipeResult<(Vec<Vec3>, Vec<f32>)> {
60:     let count = dimensions[0]
61:         .checked_mul(dimensions[1])
62:         .and_then(|n| n.checked_mul(dimensions[2]))
63:         .ok_or(TerrainRecipeError::SampleCountOverflow)?;
64:     let samples = (0..count)
65:         .into_par_iter()
66:         .map(|index| {
67:             let yz = index / dimensions[0];
68:             let coordinate = [
69:                 index % dimensions[0],
70:                 yz % dimensions[1],
71:                 yz / dimensions[1],
72:             ];
73:             let position = position_at(coordinate);
74:             let value = field(position)?;
75:             let value = snap_field_zero(value);
76:             (position.is_finite() && value.is_finite())
77:                 .then_some((position, value))
78:                 .ok_or(TerrainRecipeError::NonFiniteField)
79:         })
80:         .collect::<TerrainRecipeResult<Vec<_>>>()?;
81:     Ok(samples.into_iter().unzip())
82: }
