134: fn area(polygon: &[Vec2]) -> f64 {
135:     let Some(origin) = polygon.first() else {
136:         return 0.0;
137:     };
138:     polygon
139:         .iter()
140:         .zip(polygon.iter().cycle().skip(1))
141:         .take(polygon.len())
142:         .map(|(a, b)| {
143:             let a = (*a - *origin).as_dvec2();
144:             let b = (*b - *origin).as_dvec2();
145:             a.perp_dot(b)
146:         })
147:         .sum::<f64>()
148:         .abs()
149:         * 0.5
150: }
