pr-working:crates/fabelgeist-compute/src/host_float/arithmetic.rs
   1: //! The fence, the correctly rounded operations, and the vector forms the
   2: //! host's `[f32; 3]` arithmetic takes.
   3: 
   4: /// Every function fences its operands as well as its result: an operand the
   5: /// caller computed inline -- `host_add(a * b, c)` -- rounds before the
   6: /// operation meets it, as the host's `a * b + c` does, instead of fusing.
   7: pub(super) const ARITHMETIC: &str = r#"
   8: // The largest finite float. Beyond it -- and for NaN -- a quotient or root
   9: // is the device's own, which is the host's special value too.
  10: const HOST_FLOAT_MAX: f32 = 0x1.fffffep+127f;
  11: // How many units in the last place a quotient or root may walk. The
  12: // device's division and square root are within a few units of the nearest.
  13: const HOST_FLOAT_WALK: u32 = 4u;
  14: 
  15: // `x` exactly as rounded. Its bits pass through an integer OR with a zero
  16: // the compiler cannot see, so no float operation fuses with it or is
  17: // reassociated across it.
  18: fn host_fence(x: f32) -> f32 {
  19:     return bitcast<f32>(bitcast<u32>(x) | host_zero());
  20: }
  21: 
  22: fn host_fence3(v: vec3<f32>) -> vec3<f32> {
  23:     return vec3<f32>(host_fence(v.x), host_fence(v.y), host_fence(v.z));
  24: }
  25: 
  26: fn host_add(a: f32, b: f32) -> f32 {
  27:     return host_fence(host_fence(a) + host_fence(b));
  28: }
  29: 
  30: fn host_sub(a: f32, b: f32) -> f32 {
  31:     return host_fence(host_fence(a) - host_fence(b));
  32: }
  33: 
  34: fn host_mul(a: f32, b: f32) -> f32 {
  35:     return host_fence(host_fence(a) * host_fence(b));
  36: }
  37: 
  38: // The float next to `x` toward positive (`up`) or negative infinity.
  39: fn host_next_float(x: f32, up: bool) -> f32 {
  40:     if (x == 0.0) {
  41:         return select(-bitcast<f32>(1u), bitcast<f32>(1u), up);
  42:     }
  43:     let bits = bitcast<u32>(x);
  44:     return bitcast<f32>(select(bits - 1u, bits + 1u, up == (x > 0.0)));
  45: }
  46: 
  47: // Of two adjacent candidates bracketing the true quotient, the one whose
  48: // exact residual is smaller; residuals scale with the distance to the
  49: // quotient by the same divisor, so smaller is nearer.
  50: fn host_nearer(q: f32, r: f32, q2: f32, r2: f32) -> f32 {
  51:     if (abs(r2) < abs(r)) {
  52:         return q2;
  53:     }
  54:     if (abs(r2) > abs(r)) {
  55:         return q;
  56:     }
  57:     return select(q2, q, (bitcast<u32>(q) & 1u) == 0u);
  58: }
  59: 
  60: // The correctly rounded quotient: the device's, walked toward the true
  61: // quotient by exact fused residuals until two neighbours bracket it.
  62: fn host_div(a_: f32, b_: f32) -> f32 {
  63:     let a = host_fence(a_);
  64:     let b = host_fence(b_);
  65:     var q = host_fence(a / b);
  66:     if (!(abs(q) <= HOST_FLOAT_MAX) || q == 0.0) {
  67:         return q;
  68:     }
  69:     // Retain the exact walk without expanding its body at every call site.
  70:     for (var k = 0u; k < HOST_FLOAT_WALK + host_zero(); k = k + 1u) {
  71:         // a - q b, exact once q is within a unit of a / b.
  72:         let r = fma(-q, b, a);
  73:         if (r == 0.0) {
  74:             return q;
  75:         }
  76:         let q2 = host_next_float(q, (r > 0.0) == (b > 0.0));
  77:         let r2 = fma(-q2, b, a);
  78:         if (r2 == 0.0) {
  79:             return q2;
  80:         }
  81:         if ((r2 > 0.0) != (r > 0.0)) {
  82:             return host_nearer(q, r, q2, r2);
  83:         }
  84:         q = q2;
  85:     }
  86:     return q;
  87: }
  88: 
  89: // The correctly rounded square root. With s's significand an integer S
  90: // units u, x - s^2 and s u are both whole multiples of u^2, and the root
  91: // lies above the midpoint s + u/2 exactly when x - (s + u/2)^2 =
  92: // (x - s^2) - s u - u^2/4 is positive: when the exact residual
  93: // `fma(-s, s, x)` exceeds s u. Below, likewise, with the unit under s.
  94: // Unlike comparing the two neighbours' residuals, which weigh the distance
  95: // to the root by different factors, this never picks the farther one.
  96: fn host_sqrt(x_: f32) -> f32 {
  97:     let x = host_fence(x_);
  98:     if (!(x > 0.0) || !(x <= HOST_FLOAT_MAX)) {
  99:         return host_fence(sqrt(x));
 100:     }
 101:     // s u would underflow for a root this small; scaling by an even power
 102:     // of two moves the root by exactly half as many, so it stays nearest.
 103:     if (x < HOST_SQRT_SCALED_BELOW) {
 104:         return host_fence(host_sqrt_walked(host_fence(x * HOST_SQRT_SCALE)) * HOST_SQRT_UNSCALE);
 105:     }
 106:     return host_sqrt_walked(x);
 107: }
 108: 
 109: // Beneath this, a square root is taken of the argument times 2^64.
 110: const HOST_SQRT_SCALED_BELOW: f32 = 0x1p-64f;
 111: const HOST_SQRT_SCALE: f32 = 0x1p64f;
 112: const HOST_SQRT_UNSCALE: f32 = 0x1p-32f;
 113: 
 114: // The nearest root of a positive x at least 2^-64.
 115: fn host_sqrt_walked(x: f32) -> f32 {
 116:     var s = host_fence(sqrt(x));
 117:     for (var k = 0u; k < HOST_FLOAT_WALK + host_zero(); k = k + 1u) {
 118:         let r = fma(-s, s, x);
 119:         let above = host_next_float(s, true);
 120:         let below = host_next_float(s, false);
 121:         if (r > host_fence(s * (above - s))) {
 122:             s = above;
 123:         } else if (-r >= host_fence(s * (s - below))) {
 124:             s = below;
 125:         } else {
 126:             break;
 127:         }
 128:     }
 129:     return s;
 130: }
 131: 
 132: fn host_add3(a: vec3<f32>, b: vec3<f32>) -> vec3<f32> {
 133:     return vec3<f32>(host_add(a.x, b.x), host_add(a.y, b.y), host_add(a.z, b.z));
 134: }
 135: 
 136: fn host_sub3(a: vec3<f32>, b: vec3<f32>) -> vec3<f32> {
 137:     return vec3<f32>(host_sub(a.x, b.x), host_sub(a.y, b.y), host_sub(a.z, b.z));
 138: }
 139: 
 140: fn host_scale3(v: vec3<f32>, s: f32) -> vec3<f32> {
 141:     return vec3<f32>(host_mul(v.x, s), host_mul(v.y, s), host_mul(v.z, s));
 142: }
 143: 
 144: fn host_div3(v: vec3<f32>, s: f32) -> vec3<f32> {
 145:     return vec3<f32>(host_div(v.x, s), host_div(v.y, s), host_div(v.z, s));
 146: }
 147: 
 148: // The host's `(a[0] * b[0] + a[1] * b[1]) + a[2] * b[2]`.
 149: fn host_dot(a: vec3<f32>, b: vec3<f32>) -> f32 {
 150:     return host_add(host_add(host_mul(a.x, b.x), host_mul(a.y, b.y)), host_mul(a.z, b.z));
 151: }
 152: 
 153: fn host_cross(a: vec3<f32>, b: vec3<f32>) -> vec3<f32> {
 154:     return vec3<f32>(
 155:         host_sub(host_mul(a.y, b.z), host_mul(a.z, b.y)),
 156:         host_sub(host_mul(a.z, b.x), host_mul(a.x, b.z)),
 157:         host_sub(host_mul(a.x, b.y), host_mul(a.y, b.x)),
 158:     );
 159: }
 160: 
 161: fn host_length(v: vec3<f32>) -> f32 {
 162:     return host_sqrt(host_dot(v, v));
 163: }
 164: 
 165: // The host's `a + (b - a) * t`.
 166: fn host_lerp(a: f32, b: f32, t: f32) -> f32 {
 167:     return host_add(a, host_mul(host_sub(b, a), t));
 168: }
 169: 
 170: // The host's clamped smoothstep, `t * t * (3 - 2 t)`.
 171: fn host_smoothstep(t: f32) -> f32 {
 172:     let c = clamp(t, 0.0, 1.0);
 173:     return host_mul(host_mul(c, c), host_sub(3.0, host_mul(2.0, c)));
 174: }
