pr-working:crates/fabelgeist-compute/src/host_float/mod.rs
   1: //! WGSL float arithmetic that rounds as the host's does.
   2: //!
   3: //! A device compiler is free to fuse a product into the sum that consumes
   4: //! it, to reassociate sums -- `(y + h) - (y - h)` becomes `2 h` -- to divide
   5: //! and take square roots a few units in the last place off, and to evaluate
   6: //! `sin` or `pow` more loosely still. Mostly that is invisible. But where a
   7: //! kernel must reproduce a host computation bit for bit -- a finite
   8: //! difference, which amplifies every rounding difference; a weld that merges
   9: //! vertices agreeing to their last bits; a normal whose sign picks the side
  10: //! of a seam -- it must round exactly as the host does. [`wgsl`] is a library
  11: //! of functions that do, which a kernel prepends to its source:
  12: //!
  13: //! * `host_fence(x)`, `host_fence3(v)`: `x` materialised exactly as rounded.
  14: //! * `host_add`, `host_sub`, `host_mul`: one correctly rounded operation,
  15: //!   its operands and result fenced, so that it neither fuses nor
  16: //!   reassociates -- `host_add(a * b, c)` is the host's `a * b + c`.
  17: //! * `host_div`, `host_sqrt`: the correctly rounded quotient and root.
  18: //! * `host_add3`, `host_sub3`, `host_scale3`, `host_div3`, `host_dot`,
  19: //!   `host_cross`, `host_length`: `[f32; 3]` arithmetic in the host's order,
  20: //!   `host_dot` summing `(x + y) + z`.
  21: //! * `host_lerp(a, b, t)` is `a + (b - a) * t`, and `host_smoothstep(t)` the
  22: //!   clamped `t * t * (3 - 2 t)`.
  23: //! * `host_sin`, `host_cos`, `host_sin_cos`, `host_asin`, `host_log`,
  24: //!   `host_exp`, `host_pow`: evaluated in double-float arithmetic and
  25: //!   rounded once, which is correctly rounded but for the rare argument
  26: //!   whose value lies within about `2^-44` of a rounding boundary. A host
  27: //!   whose own `sinf` or `powf` is not correctly rounded differs from them
  28: //!   there instead. `host_pow` takes a positive base, or zero.
  29: //! * `df_*`: the double-float arithmetic beneath them -- `vec2<f32>` values
  30: //!   `x + y` -- for a kernel that needs more than a float's precision.
  31: //!
  32: //! # The fence
  33: //!
  34: //! Every function above passes floats through `host_fence`, which ORs their
  35: //! bits with `host_zero()`: a `u32` zero that the including kernel defines,
  36: //! and that must be read at run time -- a uniform field, or a buffer word the
  37: //! host leaves at zero. Float optimisations act on float operations; a value
  38: //! that went through an integer operation with an operand unknown at compile
  39: //! time is opaque to them, and must be materialised as the float it was.
  40: //! [`zero_hook`] writes the definition, [`PARAMS_ZERO_HOOK`] the one reading
  41: //! a uniform `params.zero: u32`, the convention: set it to `0u` with
  42: //! `parameters.insert(ZERO_FIELD, 0u32)`.
  43: //!
  44: //! Defining a function, rather than assigning a module-scope `var<private>`
  45: //! at the top of each entry point, is deliberate: a kernel that forgets the
  46: //! function does not compile, whereas an entry point that forgets the
  47: //! assignment reads the variable's zero initialiser, a constant the compiler
  48: //! folds away -- silently removing every fence. Reading a uniform in every
  49: //! fence costs nothing measurable; the compiler loads it once.
  50: //!
  51: //! # Limits
  52: //!
  53: //! Residuals are taken with `fma`, which must be fused: the tests below
  54: //! check that it is on the device they run on. Devices flush subnormals to
  55: //! zero, so a result or residual beneath the normal range may still differ
  56: //! from the host's. The quarter-turn reduction of `host_sin` and `host_cos`
  57: //! is exact for arguments up to a few thousand radians.
  58: 
  59: mod arithmetic;
  60: mod double_float;
  61: 
  62: #[cfg(test)]
  63: mod tests;
  64: 
  65: use std::sync::OnceLock;
  66: 
  67: /// The name of the uniform field [`PARAMS_ZERO_HOOK`] reads.
  68: pub const ZERO_FIELD: &str = "zero";
  69: 
  70: /// A `host_zero` reading the kernel's uniform `params.zero`, a `u32` the
  71: /// host sets to zero.
  72: pub const PARAMS_ZERO_HOOK: &str = "fn host_zero() -> u32 {\n    return params.zero;\n}\n";
  73: 
  74: /// The library's WGSL. The kernel including it defines `host_zero`; see
  75: /// the module documentation.
  76: pub fn wgsl() -> &'static str {
  77:     static SOURCE: OnceLock<String> = OnceLock::new();
  78:     SOURCE.get_or_init(|| format!("{}{}", arithmetic::ARITHMETIC, double_float::source()))
  79: }
  80: 
  81: /// A `host_zero` returning `expression`, a `u32` zero read at run time, such
  82: /// as `bitcast<u32>(design[ZERO])` for a buffer word the host leaves at
  83: /// `0.0`.
  84: pub fn zero_hook(expression: &str) -> String {
  85:     format!("fn host_zero() -> u32 {{\n    return {expression};\n}}\n")
  86: }
