   1: //! The algorithms, in one import.
   2: //!
   3: //! The GPU layer is deliberately *not* re-exported to the outside:
   4: //! `WgpuContext`, `Buffer`, `Texture2d`, `ComputePipeline` and the rest come
   5: //! from `fabelgeist_gpu::prelude`, which is the crate that owns them. The
   6: //! `pub(crate)` line below is this crate's own shorthand for that vocabulary,
   7: //! which every algorithm here is written in.
   8: 
   9: pub use crate::*;
  10: pub(crate) use fabelgeist_gpu::data::gpu::*;
  11: pub(crate) use fabelgeist_gpu::globals::*;
  12: // The maths the primitives speak in, from the crate that owns it.
  13: #[allow(unused_imports)]
  14: pub(crate) use anyhow::anyhow;
  15: pub use anyhow::{Error, Result};
  16: pub(crate) use fabelgeist_math::vector::*;

  1: //! Double-float arithmetic and the transcendental functions built on it.
  2: //!
  3: //! A double-float is a `vec2<f32>` holding the unevaluated sum `x + y`, with
  4: //! `|y|` at most half a unit in the last place of `x`: about 48 bits. A
  5: //! function evaluated in it and rounded once to a float is the correctly
  6: //! rounded result unless its true value lies within about `2^-44` of a unit
  7: //! of a rounding boundary -- about one argument in a million.
  8: 
  9: /// Terms of the sine series `r^(2k+1) / (2k+1)!` over an eighth turn; the
 10: /// next is below `2^-64` of the first.
 11: const SINE_TERMS: u32 = 9;
 12: /// Terms of the cosine series `r^2k / (2k)!`.
 13: const COSINE_TERMS: u32 = 10;
 14: /// Terms of the logarithm's series `2 t^(2k+1) / (2k+1)`, whose argument
 15: /// `t = (m - 1) / (m + 1)` is at most `(sqrt 2 - 1) / (sqrt 2 + 1)`.
 16: const LOG_TERMS: u32 = 14;
 17: /// Terms of the exponential series `r^k / k!` over half a doubling.
 18: const EXP_TERMS: u32 = 17;
 19: 
 20: /// A quarter turn as the sum of four floats, the error of each the next,
 21: /// from a 100-digit pi: a reduction by it is exact to about `2^-100` for
 22: /// arguments of a few thousand radians. Given as bits, which a decimal
 23: /// might not round back to.
 24: const QUARTER_TURN: [f32; 4] = [
 25:     f32::from_bits(0x3fc9_0fdb),
 26:     f32::from_bits(0xb33b_bd2e),
 27:     f32::from_bits(0xa6f7_2ced),
 28:     f32::from_bits(0x194c_5170),
 29: ];
 30: /// The natural logarithm of two as the sum of three floats, likewise.
 31: const LN_2: [f32; 3] = [
 32:     f32::from_bits(0x3f31_7218),
 33:     f32::from_bits(0xb102_e308),
 34:     f32::from_bits(0xa4ca_86c4),
 35: ];
 36: 
 37: /// A float as a WGSL literal. The `f` suffix makes the parser round the
 38: /// decimal straight to a float, never through a double.
 39: fn literal(value: f32) -> String {
 40:     format!("{value:e}f")
 41: }
 42: 
 43: /// `value` as a leading float and the float nearest the rest.
 44: fn split(value: f64) -> (f32, f32) {
 45:     let high = value as f32;
 46:     (high, (value - f64::from(high)) as f32)
 47: }
 48: 
 49: fn double_float(value: f64) -> String {
 50:     let (high, low) = split(value);
 51:     format!("vec2<f32>({}, {})", literal(high), literal(low))
 52: }
 53: 
 54: /// A WGSL function evaluating a nonempty double-float polynomial in `z` by
 55: /// Horner's rule; the four series below supply fixed positive term counts.
 56: fn horner<const N: usize>(name: &str, coefficients: [f64; N]) -> String {
 57:     let coefficients = coefficients
 58:         .into_iter()
 59:         .rev()
 60:         .map(double_float)
 61:         .collect::<Vec<_>>()
 62:         .join(",\n        ");
 63:     // A runtime zero keeps the bounded loop from expanding every fenced
 64:     // multiply/add into each caller. Coefficients and evaluation order remain
 65:     // exactly the same as the expanded Horner sequence.
 66:     // Instruction-footprint reference:
 67:     // <REDACTED_URL>
 68:     format!(
 69:         "fn {name}(z: vec2<f32>) -> vec2<f32> {{
 70:     const coefficients = array<vec2<f32>, {N}>(
 71:         {coefficients}
 72:     );
 73:     var sum = coefficients[0];
 74:     let count = {N}u + host_zero();
 75:     for (var index = 1u; index < count; index++) {{
 76:         sum = df_add(df_mul(sum, z), coefficients[index]);
 77:     }}
 78:     return sum;
 79: }}
 80: "
 81:     )
 82: }
 83: 
 84: fn factorial(n: u32) -> f64 {
 85:     (1..=n).map(f64::from).product()
 86: }
 87: 
 88: fn alternating(k: u32) -> f64 {
 89:     if k.is_multiple_of(2) { 1.0 } else { -1.0 }
 90: }
 91: 
 92: /// The double-float operations, the series and the functions.
 93: pub(super) fn source() -> String {
 94:     let mut source = String::from(OPERATIONS);
 95:     for (k, part) in QUARTER_TURN.iter().enumerate() {
 96:         source.push_str(&format!(
 97:             "const DF_QUARTER_TURN_{k}: f32 = {};\n",
 98:             literal(*part)
 99:         ));
100:     }
101:     for (k, part) in LN_2.iter().enumerate() {
102:         source.push_str(&format!("const DF_LN_2_{k}: f32 = {};\n", literal(*part)));
103:     }
104:     source.push_str(&format!(
105:         "const DF_TWO_OVER_PI: f32 = {};\nconst DF_LOG2_E: f32 = {};\n",
106:         literal(std::f32::consts::FRAC_2_PI),
107:         literal(std::f32::consts::LOG2_E)
108:     ));
109:     let sine: [f64; SINE_TERMS as usize] =
110:         std::array::from_fn(|k| alternating(k as u32) / factorial(2 * k as u32 + 1));
111:     let cosine: [f64; COSINE_TERMS as usize] =
112:         std::array::from_fn(|k| alternating(k as u32) / factorial(2 * k as u32));
113:     let logarithm: [f64; LOG_TERMS as usize] =
114:         std::array::from_fn(|k| 2.0 / f64::from(2 * k as u32 + 1));
115:     let exponential: [f64; EXP_TERMS as usize] = std::array::from_fn(|k| 1.0 / factorial(k as u32));
116:     source += &horner("df_sine_series", sine);
117:     source += &horner("df_cosine_series", cosine);
118:     source += &horner("df_atanh_series", logarithm);
119:     source += &horner("df_exp_series", exponential);
120:     source += FUNCTIONS;
121:     source
122: }
123: 
124: /// The error-free transformations fence their operands as well as their
125: /// steps: a compiler that could trace an operand back to how it was
126: /// computed could cancel the very rounding error they measure.
127: const OPERATIONS: &str = r#"
128: fn df_two_sum(a_: f32, b_: f32) -> vec2<f32> {
129:     let a = host_fence(a_);
130:     let b = host_fence(b_);
131:     let s = host_fence(a + b);
132:     let v = host_fence(s - a);
133:     return vec2<f32>(s, host_add(host_sub(a, host_fence(s - v)), host_sub(b, v)));
134: }
135: 
136: // The same, for |a| >= |b|.
137: fn df_quick_two_sum(a_: f32, b_: f32) -> vec2<f32> {
138:     let a = host_fence(a_);
139:     let b = host_fence(b_);
140:     let s = host_fence(a + b);
141:     return vec2<f32>(s, host_sub(b, host_fence(s - a)));
142: }
143: 
144: fn df_two_product(a_: f32, b_: f32) -> vec2<f32> {
145:     let a = host_fence(a_);
146:     let b = host_fence(b_);
147:     let p = host_fence(a * b);
148:     return vec2<f32>(p, fma(a, b, -p));
149: }
150: 
151: fn df_add(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
152:     let high = df_two_sum(a.x, b.x);
153:     let low = df_two_sum(a.y, b.y);
154:     let s = df_quick_two_sum(high.x, host_add(high.y, low.x));
155:     return df_quick_two_sum(s.x, host_add(s.y, low.y));
156: }
157: 
158: fn df_add_f32(a: vec2<f32>, b: f32) -> vec2<f32> {
159:     let high = df_two_sum(a.x, b);
160:     return df_quick_two_sum(high.x, host_add(high.y, a.y));
161: }
162: 
163: fn df_mul(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
164:     let p = df_two_product(a.x, b.x);
165:     let cross = host_add(host_mul(a.x, b.y), host_mul(a.y, b.x));
166:     return df_quick_two_sum(p.x, host_add(p.y, cross));
167: }
168: 
169: fn df_mul_f32(a: vec2<f32>, b: f32) -> vec2<f32> {
170:     let p = df_two_product(a.x, b);
171:     return df_quick_two_sum(p.x, host_add(p.y, host_mul(a.y, b)));
172: }
173: 
174: // Three quotient digits, each from the remainder of the ones before.
175: fn df_div(a: vec2<f32>, b: vec2<f32>) -> vec2<f32> {
176:     let q1 = host_fence(a.x / b.x);
177:     let r1 = df_add(a, -df_mul_f32(b, q1));
178:     let q2 = host_fence(r1.x / b.x);
179:     let r2 = df_add(r1, -df_mul_f32(b, q2));
180:     let q3 = host_fence(r2.x / b.x);

321:     fn show_open_file_picker(options: &js_sys::Object) -> js_sys::Promise;
322: 
