350: pub async fn pick_file_entry(
351:     filter_name: String,
352:     extensions: Vec<String>,
353: ) -> Result<Option<Box<dyn FileEntry>>> {
354:     #[cfg(not(target_arch = "wasm32"))]
355:     {
356:         let extensions_refs: Vec<&str> = extensions.iter().map(|s| s.as_str()).collect();
357:         let dialog = rfd::AsyncFileDialog::new()
358:             .add_filter(&filter_name, &extensions_refs)
359:             .pick_file()
360:             .await;
361: 
362:         if let Some(file_handle) = dialog {
363:             let path = file_handle.path().to_path_buf();
364:             Ok(Some(Box::new(NativeFile { path })))
365:         } else {
366:             Ok(None)
367:         }
368:     }
369: 
370:     #[cfg(target_arch = "wasm32")]
371:     {
372:         use wasm_bindgen::JsCast;
373:         use wasm_bindgen_futures::JsFuture;
374: 
375:         let options = js_sys::Object::new();
376: 
377:         if !extensions.is_empty() {
378:             let types = js_sys::Array::new();
379:             let type_obj = js_sys::Object::new();
380:             js_sys::Reflect::set(&type_obj, &"description".into(), &filter_name.into()).ok();
381: 
382:             let accept = js_sys::Object::new();
383:             let exts = js_sys::Array::new();
384:             for ext in extensions {
385:                 let ext_with_dot = if ext.starts_with('.') {
386:                     ext
387:                 } else {
388:                     format!(".{}", ext)
389:                 };
390:                 exts.push(&ext_with_dot.into());
391:             }
392:             js_sys::Reflect::set(&accept, &"*/*".into(), &exts).ok();
393:             js_sys::Reflect::set(&type_obj, &"accept".into(), &accept).ok();
394:             types.push(&type_obj);
395:             js_sys::Reflect::set(&options, &"types".into(), &types).ok();
396:         }
397: 
398:         js_sys::Reflect::set(&options, &"multiple".into(), &false.into()).ok();
399: 
400:         let promise = show_open_file_picker(&options);
401:         let result = JsFuture::from(promise)
402:             .await
403:             .map_err(|e| anyhow!("showOpenFilePicker failed: {:?}", e))?;
404:         let handles = result
405:             .dyn_into::<js_sys::Array>()
406:             .map_err(|_| anyhow!("Expected array of handles"))?;
407: 
408:         if handles.length() > 0 {
409:             let handle = handles.get(0);
410:             let handle: web_sys::FileSystemFileHandle = handle
411:                 .dyn_into()
412:                 .map_err(|_| anyhow!("Expected FileSystemFileHandle"))?;
413:             Ok(Some(Box::new(WebFile {
414:                 handle: SendFileHandle(handle),
415:             })))
416:         } else {
417:             Ok(None)
418:         }
419:     }
420: }
