605: pub async fn to_data_uri(uri: &str) -> Result<String> {
606:     if uri.starts_with("data:") {
607:         return Ok(uri.to_string());
608:     }
609: 
610:     let bytes = read_bytes(uri).await?;
611:     let mime = detect_mime(uri);
612: 
613:     use base64::{Engine as _, engine::general_purpose};
614:     let b64 = general_purpose::STANDARD.encode(&bytes);
615:     Ok(format!("data:{};base64,{}", mime, b64))
616: }
