618: pub fn detect_mime(uri: &str) -> &'static str {
619:     let lower = uri.to_lowercase();
620:     if lower.ends_with(".glb") {
621:         "application/octet-stream"
622:     } else if lower.ends_with(".gltf") {
623:         "application/json"
624:     } else if lower.ends_with(".png") {
625:         "image/png"
626:     } else if lower.ends_with(".jpg") || lower.ends_with(".jpeg") {
627:         "image/jpeg"
628:     } else if lower.ends_with(".svg") {
629:         "image/svg+xml"
630:     } else {
631:         "application/octet-stream"
632:     }
633: }
