782: async fn load_http(uri: &str) -> Result<Vec<u8>> {
783:     #[cfg(not(target_arch = "wasm32"))]
784:     {
785:         let response = reqwest::get(uri).await?;
786:         Ok(response.bytes().await?.to_vec())
787:     }
788:     #[cfg(target_arch = "wasm32")]
789:     {
790:         use wasm_bindgen::JsCast;
791:         use wasm_bindgen_futures::JsFuture;
792:         use web_sys::{Request, RequestInit, RequestMode, Response};
793: 
794:         use std::sync::{Mutex, OnceLock};
795:         static FAILED_FETCHES: OnceLock<Mutex<std::collections::HashSet<String>>> = OnceLock::new();
796: 
797:         let (tx, rx) = futures_channel::oneshot::channel::<Result<Vec<u8>>>();
798:         let uri = uri.to_string();
799: 
800:         if let Some(failed) = FAILED_FETCHES.get() {

801:             if let Ok(guard) = failed.lock() {
802:                 if guard.contains(&uri) {
803:                     return Err(anyhow!("Fetch failed (cached)"));
804:                 }
805:             }
806:         }
807: 
808:         wasm_bindgen_futures::spawn_local(async move {
809:             let opts = RequestInit::new();
810:             opts.set_method("GET");
811:             opts.set_mode(RequestMode::Cors);
812: 
813:             let result: Result<Vec<u8>> = async {
814:                 let request = Request::new_with_str_and_init(&uri, &opts)
815:                     .map_err(|e| anyhow!("Failed to create request: {:?}", e))?;
816: 
817:                 let window = web_sys::window().ok_or_else(|| anyhow!("No window found"))?;
818:                 let resp_value = JsFuture::from(window.fetch_with_request(&request))
819:                     .await
820:                     .map_err(|e| anyhow!("Fetch failed: {:?}", e))?;
821: 
822:                 let resp: Response = resp_value
823:                     .dyn_into()
824:                     .map_err(|e| anyhow!("Failed to cast response: {:?}", e))?;
825: 
826:                 if !resp.ok() {
827:                     return Err(anyhow!("HTTP error: {}", resp.status()));
828:                 }
829: 
830:                 let array_buffer_value = JsFuture::from(
831:                     resp.array_buffer()
832:                         .map_err(|e| anyhow!("Failed to get array buffer: {:?}", e))?,
833:                 )
834:                 .await
835:                 .map_err(|e| anyhow!("Failed to await array buffer: {:?}", e))?;
836: 
837:                 let array_buffer = js_sys::ArrayBuffer::from(array_buffer_value);
838:                 let uint8_array = js_sys::Uint8Array::new(&array_buffer);
839:                 Ok(uint8_array.to_vec())
840:             }
841:             .await;
842: 
843:             if result.is_err() && uri.starts_with("blob:") {
844:                 let cache =
845:                     FAILED_FETCHES.get_or_init(|| Mutex::new(std::collections::HashSet::new()));
846:                 if let Ok(mut guard) = cache.lock() {
847:                     guard.insert(uri.clone());
848:                 }
849:             }
850:             let _ = tx.send(result);
851:         });
852: 
853:         rx.await.map_err(|_| anyhow!("Channel closed"))?
854:     }
855: }
