22: impl Buffer {
23:     pub fn new(
24:         context: &WgpuContext,
25:         bytes: BufferByteLength,
26:         definition: BufferDefinition,
27:     ) -> Result<Buffer> {
28:         if u64::from(bytes) == 0 {
29:             return Err(anyhow!("Buffer size must be greater than 0"));
30:         }
31:         let buffer = definition.allocate_native(context, bytes);
32:         let usage = buffer.usage();
