40:     pub async fn read<T: bytemuck::AnyBitPattern>(&self, context: &WgpuContext) -> Result<Vec<T>> {
41:         let size = u64::from(self.size);
42:         let readback = readback::Readback::<T>::new(size)?;
43:         let is_mappable = self.usage.contains(wgpu::BufferUsages::MAP_READ);
44: 
45:         let (target_buffer, needs_unmap) = if is_mappable {
46:             (self.buffer.clone(), false)
47:         } else {
48:             // 1. Create staging buffer
49:             let staging_buffer = context.device.create_buffer(&wgpu::BufferDescriptor {
50:                 label: Some("Staging Buffer"),
51:                 size,
52:                 usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
53:                 mapped_at_creation: false,
54:             });
55: 
56:             // 2. Copy data to staging buffer
57:             let mut encoder = context
58:                 .device
59:                 .create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
60:             encoder.copy_buffer_to_buffer(&self.buffer, 0, &staging_buffer, 0, size);
61:             context.queue.submit(Some(encoder.finish()));
62:             (Arc::new(staging_buffer), true)
63:         };
64: 
65:         #[allow(unused_mut)]
66:         let (tx, mut rx) = futures_channel::oneshot::channel();
67: 
68:         // 1. Start mapping
69:         {
70:             let slice = target_buffer.slice(..);
71:             slice.map_async(wgpu::MapMode::Read, move |res| {
72:                 let _ = tx.send(res);
73:             });
74:         }
75: 
76:         // 2. Poll if on native
77:         #[cfg(not(target_arch = "wasm32"))]
78:         {
79:             // Waiting on the queue is what a readback actually costs. Asking
80:             // whether it is done and then sleeping a millisecond between asks
81:             // adds the sleep's granularity to every one -- and on Windows that
82:             // is not a millisecond, it is whatever the system timer is set to,
83:             // which turned a four-megabyte read into four milliseconds and
84:             // sometimes eight. `Wait` returns when the work is done.
85:             let _ = context.device.poll(wgpu::PollType::wait_indefinitely());
86:             loop {
87:                 match rx.try_recv() {
88:                     Ok(Some(res)) => {
89:                         res.map_err(|e| anyhow!("GPU Mapping error: {:?}", e))?;
90:                         break;
91:                     }
92:                     // `Wait` covers submitted work, so this is reached only for
93:                     // a buffer that was already mappable and had nothing
94:                     // submitted for it. Yielding keeps that case from spinning
95:                     // a core without putting a sleep back in the common one.
96:                     Ok(None) => {
97:                         let _ = context.device.poll(wgpu::PollType::Poll);
98:                         std::thread::yield_now();
99:                     }
100:                     Err(_) => return Err(anyhow!("Mapping channel closed")),
101:                 }
102:             }
103:         }
104: 
105:         // 3. Await result (only on wasm, since native loop already consumed rx)
106:         #[cfg(target_arch = "wasm32")]
107:         rx.await
108:             .map_err(|_| anyhow!("Mapping channel closed"))?
109:             .map_err(|_| anyhow!("GPU Mapping error"))?;
110: 
111:         // Allocate before obtaining the mapped view so WASM memory growth
112:         // cannot detach it; initialize typed values only after copying bytes.
113:         let slice = target_buffer.slice(..);
114:         let data = slice.get_mapped_range();
115:         let result = readback.copy_from(&data);
116:         drop(data);
117: 
118:         if needs_unmap {
119:             target_buffer.unmap();
120:         } else {
121:             // If it's the original buffer, we still need to unmap it so it can be used by the GPU again
122:             target_buffer.unmap();
123:         }
124: 
125:         result
126:     }
