1: //! The substep hook: everything a particle must stay out of.
2: //!
3: //! This is what plugs into [`fabelgeist_xpbd::Solver`]. It runs after the
4: //! prediction and before the material constraints, and it resolves purely by
5: //! moving positions -- the substep's own velocity update turns those moves
6: //! into velocity changes, so there is no impulse arithmetic here at all.
7: 
8: use fabelgeist_gpu::prelude::BufferUpload;
9: use std::sync::Arc;
10: 
11: use anyhow::anyhow;
12: use fabelgeist_compute::prelude::*;
13: use fabelgeist_gpu::prelude::*;
14: use fabelgeist_xpbd::{Particles, SubstepHook};
15: 
16: use crate::collider::{Collider, pack_colliders};
17: use crate::mesh::MeshCollider;
18: use crate::wgsl;
19: use count::{ColliderCapacity, ColliderCapacityFit, ColliderCount};
20: 
21: mod count;
22: 
23: /// Analytic shapes plus at most one triangle mesh.
24: ///
25: /// One mesh rather than a list because that is what the case needs -- a body
26: /// is one mesh -- and because a second would want a broad phase over meshes
27: /// that nothing yet asks for. Analytic colliders are unlimited and cheap.
28: pub struct Collisions {
29:     analytic_kernel: Arc<Kernel>,
30:     mesh_kernel: Arc<Kernel>,
31: 
32:     colliders: Vec<Collider>,
33:     collider_buffer: Buffer,
34:     collider_capacity: ColliderCapacity,
35: 
36:     pub mesh: Option<MeshCollider>,
37: 
38:     /// Half the fabric's thickness: how far a particle's centre is held off
39:     /// every analytic surface, on top of that surface's own thickness.
40:     pub particle_radius: f32,
41:     /// Skip collision entirely without tearing anything down.
42:     pub enabled: bool,
43: }
44: 
45: impl Collisions {
46:     pub fn new(context: &WgpuContext, cache: &KernelCache) -> Result<Self> {
47:         Ok(Self {
48:             analytic_kernel: cache.get(context, &wgsl::analytic_source())?,
49:             mesh_kernel: cache.get(context, &MeshCollider::kernel_source())?,
50:             colliders: Vec::new(),
51:             collider_buffer: Buffer::new(
52:                 context,
53:                 ColliderCapacity::INITIAL.byte_length(),
54:                 BufferDefinition::storage().with_label(("colliders").into()),
55:             )?,
56:             collider_capacity: ColliderCapacity::INITIAL,
57:             mesh: None,
58:             particle_radius: 0.0,
59:             enabled: true,
60:         })
61:     }
62: 
63:     pub fn colliders(&self) -> &[Collider] {
64:         &self.colliders
65:     }
66: 
67:     fn collider_count(&self) -> ColliderCount {
68:         ColliderCount::from(self.colliders.len())
69:     }
70: 
71:     /// Replace the analytic collider list and upload it.
72:     pub fn set_colliders(&mut self, context: &WgpuContext, colliders: Vec<Collider>) -> Result<()> {
73:         let count = ColliderCount::from(colliders.len());
74:         if self.collider_capacity.fit(count) == ColliderCapacityFit::GrowthRequired {
75:             self.collider_capacity = ColliderCapacity::for_count(count);
76:             self.collider_buffer = Buffer::new(
77:                 context,
78:                 self.collider_capacity.byte_length(),
79:                 BufferDefinition::storage().with_label(("colliders").into()),
80:             )?;
81:         }
82:         if !colliders.is_empty() {
83:             self.collider_buffer.write(
84:                 context,
85:                 BufferUpload::from_elements(&pack_colliders(&colliders)),
86:             )?;
87:         }
88:         self.colliders = colliders;
89:         Ok(())
90:     }
91: 
92:     /// Move the shapes without changing how many there are -- an animated
93:     /// skeleton driving a set of capsules, frame by frame.
94:     pub fn update_colliders(
95:         &mut self,
96:         context: &WgpuContext,
97:         colliders: &[Collider],
98:     ) -> Result<()> {
99:         let held = self.collider_count();
100:         let provided = ColliderCount::from(colliders.len());
101:         if provided != held {
102:             return Err(anyhow!(
103:                 "Collisions::update_colliders: holds {} colliders, given {}; use `set_colliders` to change the count",
104:                 held,
105:                 provided
106:             ));
107:         }
108:         if !colliders.is_empty() {
109:             self.collider_buffer.write(
110:                 context,
111:                 BufferUpload::from_elements(&pack_colliders(colliders)),
112:             )?;
113:         }
114:         self.colliders = colliders.to_vec();
115:         Ok(())
116:     }
117: 
118:     pub fn set_mesh(&mut self, mesh: Option<MeshCollider>) {
119:         self.mesh = mesh;
120:     }
121: 
122:     /// Record the resolve passes for one substep.
123:     pub fn record(&self, batch: &mut KernelBatch, particles: &Particles) -> Result<()> {
124:         if !self.enabled {
125:             return Ok(());
126:         }
127:         let count = particles.count();
128:         if count == 0 {
129:             return Ok(());
130:         }
131: 
132:         if self.collider_count() != ColliderCount::EMPTY {
133:             let mut parameters = PassParameters::new();
134:             parameters.insert("positions", particles.positions.clone());
135:             parameters.insert("previous", particles.previous.clone());
136:             parameters.insert("colliders", self.collider_buffer.clone());
137:             parameters.insert("count", count);
138:             self.collider_count().bind(&mut parameters);
139:             parameters.insert("particle_radius", self.particle_radius);
140:             parameters.insert("pad", 0u32);
141:             batch.dispatch_items(&self.analytic_kernel, &parameters, count)?;
142:         }
143: 
144:         if self.mesh.is_some() {
145:             self.record_mesh(batch, particles, 0.0)?;
146:         }
147: 
148:         Ok(())
149:     }
