1: //! Conservative advancement for linearly moving thick cloth primitives.
2: //!
3: //! Bound distance decrease by the maximum relative vertex displacement.
4: //! Each advance is shorter than (distance - clearance) / that bound, so it
5: //! cannot step over contact. Exhausting the iteration budget returns the last
6: //! safe time; it must never be interpreted as "no collision".
7: //! See <REDACTED_URL> (additive conservative advancement).
8: use fabelgeist_math::Vec3;
9: use fabelgeist_xpbd::ConstraintGradient;
10: 
11: #[derive(Clone, Copy, Debug)]
12: pub(crate) enum Pair {
13:     VertexTriangle,
14:     EdgeEdge,
15: }
16: 
17: #[derive(Clone, Copy, Debug)]
18: pub(crate) struct Contact {
19:     /// A conservative lower bound for the first contact, in [0, 1].
20:     pub time: f64,
21:     pub weights: [ConstraintGradient; 4],
22:     pub normal: Vec3,
23:     pub distance: f64,
24: }
25: 
26: type V = [f64; 3];
27: fn add(a: V, b: V) -> V {
28:     std::array::from_fn(|i| a[i] + b[i])
29: }
30: fn sub(a: V, b: V) -> V {
31:     std::array::from_fn(|i| a[i] - b[i])
32: }
33: fn mul(a: V, s: f64) -> V {
34:     a.map(|x| x * s)
35: }
36: fn dot(a: V, b: V) -> f64 {
37:     a.iter().zip(b).map(|(x, y)| x * y).sum()
38: }
39: fn norm(a: V) -> f64 {
40:     dot(a, a).sqrt()
41: }
42: fn cross(a: V, b: V) -> V {
43:     [
44:         a[1] * b[2] - a[2] * b[1],
45:         a[2] * b[0] - a[0] * b[2],
46:         a[0] * b[1] - a[1] * b[0],
47:     ]
48: }
49: fn convert(p: Vec3) -> V {
50:     [p.x as f64, p.y as f64, p.z as f64]
51: }
52: 
53: fn segment(p: V, a: V, b: V) -> (V, f64) {
54:     let edge = sub(b, a);
55:     let length = dot(edge, edge);
56:     let t = if length > 0.0 {
57:         (dot(sub(p, a), edge) / length).clamp(0.0, 1.0)
58:     } else {
59:         0.0
60:     };
61:     (add(a, mul(edge, t)), t)
62: }
63: 
64: /// Return the closest point with barycentric coordinates. Edge tests also
65: /// handle degenerate triangles; no division by their area is required.
66: fn triangle(p: V, a: V, b: V, c: V) -> (V, [f64; 3]) {
67:     let ab = sub(b, a);
68:     let ac = sub(c, a);
69:     let normal = cross(ab, ac);
70:     let area2 = dot(normal, normal);
71:     if area2 > 0.0 {
72:         let projected = sub(p, mul(normal, dot(sub(p, a), normal) / area2));
73:         let ap = sub(projected, a);
74:         let v = dot(cross(ap, ac), normal) / area2;
75:         let w = dot(cross(ab, ap), normal) / area2;
76:         let u = 1.0 - v - w;
77:         if u >= 0.0 && v >= 0.0 && w >= 0.0 {
78:             return (projected, [u, v, w]);
79:         }
80:     }
81:     let (q, t) = segment(p, a, b);
82:     let mut best = (q, [1.0 - t, t, 0.0]);
83:     for (q, bary) in [
84:         {
85:             let (q, t) = segment(p, b, c);
86:             (q, [0.0, 1.0 - t, t])
87:         },
88:         {
89:             let (q, t) = segment(p, c, a);
90:             (q, [t, 0.0, 1.0 - t])
91:         },
92:     ] {
93:         if norm(sub(p, q)) < norm(sub(p, best.0)) {
94:             best = (q, bary);
95:         }
96:     }
97:     best
98: }
99: 
100: fn edges(a: V, b: V, c: V, d: V) -> (f64, f64) {
101:     let (u, v, r) = (sub(b, a), sub(d, c), sub(a, c));
102:     let (aa, bb, cc, dd, ee) = (dot(u, u), dot(u, v), dot(v, v), dot(u, r), dot(v, r));
103:     if aa == 0.0 && cc == 0.0 {
104:         return (0.0, 0.0);
105:     }
106:     if aa == 0.0 {
107:         return (0.0, (ee / cc).clamp(0.0, 1.0));
108:     }
109:     if cc == 0.0 {
110:         return ((-dd / aa).clamp(0.0, 1.0), 0.0);
111:     }
112:     let determinant = norm(cross(u, v)).powi(2);
113:     let mut s = if determinant > 1e-28 * aa * cc {
114:         ((bb * ee - cc * dd) / determinant).clamp(0.0, 1.0)
115:     } else {
116:         0.0
117:     };
118:     let mut t = (bb * s + ee) / cc;
119:     if t < 0.0 {
120:         t = 0.0;
121:         s = (-dd / aa).clamp(0.0, 1.0);
122:     } else if t > 1.0 {
123:         t = 1.0;
124:         s = ((bb - dd) / aa).clamp(0.0, 1.0);
125:     }
126:     (s, t)
127: }
128: 
129: fn sample(pair: Pair, p: [V; 4], time: f64, fallback: V) -> Contact {
130:     let weights = match pair {
131:         Pair::VertexTriangle => {
132:             let (_, bary) = triangle(p[0], p[1], p[2], p[3]);
133:             [1.0, -bary[0], -bary[1], -bary[2]]
134:         }
135:         Pair::EdgeEdge => {
136:             let (s, t) = edges(p[0], p[1], p[2], p[3]);
137:             [1.0 - s, s, -(1.0 - t), -t]
138:         }
139:     };
140:     let delta = (0..4).fold([0.0; 3], |sum, i| add(sum, mul(p[i], weights[i])));
141:     let distance = norm(delta);
142:     let direction = if distance > 1e-15 {
143:         mul(delta, 1.0 / distance)
144:     } else if norm(fallback) > 1e-15 {
145:         mul(fallback, 1.0 / norm(fallback))
146:     } else {
147:         let n = match pair {
148:             Pair::VertexTriangle => cross(sub(p[2], p[1]), sub(p[3], p[1])),
149:             Pair::EdgeEdge => cross(sub(p[1], p[0]), sub(p[3], p[2])),
150:         };
151:         if norm(n) > 1e-15 {
152:             mul(n, 1.0 / norm(n))
153:         } else {
154:             [1.0, 0.0, 0.0]
155:         }
156:     };
157:     Contact {
158:         time,
159:         weights: weights.map(ConstraintGradient::from),
160:         normal: Vec3::new(
161:             direction[0] as f32,
162:             direction[1] as f32,
163:             direction[2] as f32,
164:         ),
165:         distance,
166:     }
167: }
168: 
169: /// Closest contact at the end of an interval, including collapsed primitives.
170: pub(crate) fn proximity(pair: Pair, end: [Vec3; 4], start: [Vec3; 4]) -> Contact {
171:     let previous = sample(pair, start.map(convert), 0.0, [0.0; 3]);
172:     sample(pair, end.map(convert), 1.0, convert(previous.normal))
173: }
174: 
175: /// Detect first contact over the whole interval, not just at its endpoints.
176: /// Linear vertex paths include translating, rotating and deforming triangles.
177: /// Geometry is evaluated in f64 even though storage/rendering use f32.
178: pub(crate) fn sweep(
179:     pair: Pair,
180:     start: [Vec3; 4],
181:     end: [Vec3; 4],
182:     clearance: f32,
183: ) -> Option<Contact> {
184:     sweep_with_budget(pair, start, end, clearance, 256)
185: }
186: 
187: fn sweep_with_budget(
188:     pair: Pair,
189:     start: [Vec3; 4],
190:     end: [Vec3; 4],
191:     clearance: f32,
192:     budget: usize,
193: ) -> Option<Contact> {
194:     let start = start.map(convert);
195:     let end = end.map(convert);
196:     let velocity = std::array::from_fn::<_, 4, _>(|i| sub(end[i], start[i]));
197:     let speed = match pair {
198:         Pair::VertexTriangle => (1..4)
199:             .map(|i| norm(sub(velocity[0], velocity[i])))
200:             .fold(0.0, f64::max),
201:         Pair::EdgeEdge => (0..2)
202:             .flat_map(|i| (2..4).map(move |j| norm(sub(velocity[i], velocity[j]))))
203:             .fold(0.0, f64::max),
204:     };
205:     let mut contact = sample(pair, start, 0.0, [0.0; 3]);
206:     let initial = contact.distance;
207:     let clearance = clearance as f64;
208:     if initial <= clearance {
209:         return Some(contact);
210:     }
211:     if speed <= 1e-15 {
212:         return None;
213:     }
214:     // Keep a small fraction of the initial gap. This produces a safe lower
215:     // bound and avoids asymptotically taking infinitely many steps at impact.
216:     let target = clearance + (initial - clearance) * 0.01;
217:     let mut time = 0.0;
218:     for _ in 0..budget {
219:         let distance = contact.distance;
220:         if distance <= target {
221:             return Some(contact);
222:         }
223:         let safe_step = 0.9 * (distance - clearance) / speed;
224:         if safe_step >= 1.0 - time {
225:             return None;
226:         }
227:         let next = time + safe_step;
228:         if next <= time {
229:             return Some(contact);
230:         }
231:         time = next;
232:         let p = std::array::from_fn(|i| add(start[i], mul(velocity[i], time)));
233:         contact = sample(pair, p, time, convert(contact.normal));
234:     }
235:     Some(contact)
236: }
