10: /// A pair of triangles sharing an edge, in the order the bending constraint
11: /// wants: `shared` is the hinge, `wings` are the two opposite vertices.
12: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
13: pub struct BendQuad {
14:     /// The two ends of the shared edge.
15:     pub shared: [u32; 2],
16:     /// The vertex of each triangle that is not on the shared edge.
17:     pub wings: [u32; 2],
18: }
19: 
20: impl BendQuad {
21:     /// Flattened in the order the kernel reads: the hinge, then the wings.
22:     ///
23:     /// The bending weights are computed in this same order, so the two must
24:     /// stay in step -- a permutation here silently pairs each particle with
25:     /// another one's weight.
26:     pub fn particles(&self) -> [u32; 4] {
27:         [self.shared[0], self.shared[1], self.wings[0], self.wings[1]]
28:     }
29: }
