31: #[derive(Clone, Debug, Default)]
32: pub struct Topology {
33:     /// Every edge, once, with the lower index first.
34:     pub edges: Vec<[u32; 2]>,
35:     /// One per interior edge -- an edge shared by exactly two triangles.
36:     pub bends: Vec<BendQuad>,
37:     /// Edges on the boundary: shared by one triangle only. A panel's outline.
38:     pub boundary_edges: Vec<[u32; 2]>,
39: }
40: 
41: fn key(a: u32, b: u32) -> (u32, u32) {
42:     if a < b { (a, b) } else { (b, a) }
43: }
44: 
45: /// Derive the edges and bend pairs of a triangle mesh.
46: ///
47: /// An edge shared by more than two triangles -- a non-manifold seam left in by
48: /// mistake -- contributes its stretch constraint but no bending: there is no
49: /// single pair of triangles to hinge.
50: pub fn build(triangles: &[[u32; 3]]) -> Topology {
51:     let mut adjacency: HashMap<(u32, u32), Vec<u32>> = HashMap::new();
52: 
53:     for triangle in triangles {
54:         for pair in [
55:             (triangle[0], triangle[1], triangle[2]),
56:             (triangle[1], triangle[2], triangle[0]),
57:             (triangle[2], triangle[0], triangle[1]),
58:         ] {
59:             let (a, b, opposite) = pair;
60:             adjacency.entry(key(a, b)).or_default().push(opposite);
61:         }
62:     }
63: 
64:     let mut edges = Vec::with_capacity(adjacency.len());
65:     let mut bends = Vec::new();
66:     let mut boundary_edges = Vec::new();
67: 
68:     // Sorted, so that the same mesh always produces the same constraint order
69:     // -- which makes the graph colouring, and therefore the whole simulation,
70:     // reproducible.
71:     let mut keys: Vec<(u32, u32)> = adjacency.keys().copied().collect();
72:     keys.sort_unstable();
73: 
74:     for edge in keys {
75:         let opposites = &adjacency[&edge];
76:         edges.push([edge.0, edge.1]);
77:         match opposites.len() {
78:             1 => boundary_edges.push([edge.0, edge.1]),
79:             2 => bends.push(BendQuad {
80:                 shared: [edge.0, edge.1],
81:                 wings: [opposites[0], opposites[1]],
82:             }),
83:             _ => {}
84:         }
85:     }
86: 
87:     Topology {
88:         edges,
89:         bends,
90:         boundary_edges,
91:     }
92: }
