94: /// Area-weighted vertex masses: each triangle gives a third of its mass to
95: /// each of its corners.
96: ///
97: /// This is what makes a fine panel and a coarse one fall the same way. Giving
98: /// every particle the same mass instead would make a densely meshed region
99: /// heavier than a sparse one of the same size.
100: pub fn vertex_masses(
101:     positions: &[fabelgeist_math::Vec3],
102:     triangles: &[[u32; 3]],
103:     density: ParticleArealDensity,
104: ) -> Vec<ParticleMass> {
105:     let mut masses = vec![ParticleMass::ZERO; positions.len()];
106:     for triangle in triangles {
107:         let a = positions[triangle[0] as usize];
108:         let b = positions[triangle[1] as usize];
109:         let c = positions[triangle[2] as usize];
110:         let share = density.vertex_share([a, b, c]);
111:         for &vertex in triangle {
112:             masses[vertex as usize] += share;
113:         }
114:     }
115:     masses
116: }
117: 
118: /// Inverse masses, with zero for anything that ended up massless -- a vertex
119: /// in no triangle. Zero pins it, which is the safe answer: it cannot be moved
120: /// by a constraint, rather than being moved infinitely far by one.
121: pub fn inverse_masses(masses: &[ParticleMass]) -> Vec<ParticleInverseMass> {
122:     masses
123:         .iter()
124:         .copied()
125:         .map(ParticleMass::inverse_mass)
126:         .collect()
127: }
