129: /// The affine weights the quadratic bending constraint is built on.
130: ///
131: /// Four points that lie in a plane always admit exactly one dependency
132: /// `sum(k_i) = 0` with `sum(k_i * x_i) = 0`. That combination is unchanged by
133: /// any affine map of the four points, so it measures departure from flatness
134: /// and nothing else -- which is precisely bending.
135: ///
136: /// Found as the null vector of
137: ///
138: /// ```text
139: /// [  1    1    1    1  ]
140: /// [ u0   u1   u2   u3  ]
141: /// [ v0   v1   v2   v3  ]
142: /// ```
143: ///
144: /// where `u` and `v` are coordinates in the points' own plane, via the four
145: /// signed 3x3 minors.
146: ///
147: /// The result is normalised and then scaled by the hinge's own length scale,
148: /// which is what puts the `Fabric` bend compliances into a sensible band --
149: /// see the presets, which were calibrated against this scaling.
150: ///
151: /// It does **not** make bending fully resolution-independent. Sweeping the
152: /// exponent on that length scale (the `bend_scaling_grid` test in
153: /// `fabelgeist-cloth`, which is `#[ignore]`d and meant to be run by hand) shows
154: /// the compliance at which a flap starts to droop still shifts by something
155: /// like a decade when the target edge length is halved, and no exponent tried
156: /// removed that. Part of the drift is not stiffness at all: a flap only a few
157: /// hinges wide cannot represent much curvature whatever its compliance, so the
158: /// coarse end of the sweep is measuring the mesh rather than the material.
159: /// Expect to retune `bend_compliance` after a large change in resolution.
160: ///
161: /// `points` is ordered hinge, hinge, wing, wing -- the order
162: /// [`BendQuad::particles`] produces.
163: ///
164: /// Degenerate input -- three collinear points, a collapsed triangle -- has a
165: /// larger null space and no single answer, so it returns `None` and the caller
166: /// leaves that hinge unconstrained.
167: pub fn bending_weights(points: [fabelgeist_math::Vec3; 4]) -> Option<[f32; 4]> {
168:     use fabelgeist_math::Vec3;
169: 
170:     // A basis for the plane the four points lie in. The longest edge from
171:     // point 0 gives the most stable first axis.
172:     let spokes = [
173:         points[1] - points[0],
174:         points[2] - points[0],
175:         points[3] - points[0],
176:     ];
177:     let first = spokes
178:         .iter()
179:         .copied()
180:         .max_by(|a, b| a.length_squared().total_cmp(&b.length_squared()))?;
181:     if first.length_squared() < 1e-24 {
182:         return None;
183:     }
184:     let u = first.normalize();
185: 
186:     // The second axis is whichever spoke is furthest off the first.
187:     let mut best = Vec3::default();
188:     let mut best_length = 0.0f32;
189:     for spoke in spokes {
190:         let perpendicular = spoke - u * spoke.dot(u);
191:         if perpendicular.length_squared() > best_length {
192:             best_length = perpendicular.length_squared();
193:             best = perpendicular;
194:         }
195:     }
196:     if best_length < 1e-24 {
197:         return None;
198:     }
199:     let v = best.normalize();
200: 
201:     let coordinates: [(f32, f32); 4] = points.map(|point| {
202:         let local = point - points[0];
203:         (local.dot(u), local.dot(v))
204:     });
205: 
206:     // Signed 3x3 minors of the 3x4 matrix, alternating sign: the null vector.
207:     let minor = |a: usize, b: usize, c: usize| {
208:         let (ua, va) = coordinates[a];
209:         let (ub, vb) = coordinates[b];
210:         let (uc, vc) = coordinates[c];
211:         ua * (vb - vc) - va * (ub - uc) + (ub * vc - vb * uc)
212:     };
213:     let weights = [
214:         -minor(1, 2, 3),
215:         minor(0, 2, 3),
216:         -minor(0, 1, 3),
217:         minor(0, 1, 2),
218:     ];
219: 
220:     let norm = weights.iter().map(|w| w * w).sum::<f32>().sqrt();
221:     if norm < 1e-12 {
222:         return None;
223:     }
224: 
225:     // The local length scale: the root of the two triangles' combined area.
226:     // More robust than any single edge when the triangles are not equilateral.
227:     let hinge = (points[0], points[1]);
228:     let area = |wing: Vec3| (hinge.1 - hinge.0).cross(wing - hinge.0).length() * 0.5;
229:     let scale = (area(points[2]) + area(points[3])).sqrt();
230:     if scale < 1e-9 {
231:         return None;
232:     }
233: 
234:     Some(weights.map(|w| w / norm * scale))
235: }
