40: pub(super) fn weld_vertices<I: Geometry<O>, O: Ops>(
41:     context: &I,
42:     triangle_vertices: &mut [FaceVertex],
43: ) {
44:     // make bbox
45:     let Some((min, max)) = triangle_vertices
46:         .iter()
47:         .map(|&i| get_position_from_index(context, i))
48:         .fold(None, |state, v| {
49:             let (mut min, mut max) = state.unwrap_or((v, v));
50: 
51:             for c in 0..3 {
52:                 min[c] = min[c].min(v[c]);
53:                 max[c] = max[c].max(v[c]);
54:             }
55: 
56:             Some((min, max))
