63:     let d = max - min;
64: 
65:     let c_max = if d.y > d.x && d.y > d.z {
66:         1
67:     } else if d.z > d.x {
68:         2
69:     } else {
70:         0
71:     };
72: 
73:     let mut temporary_vertices = triangle_vertices
74:         .iter()
75:         .map(|&v| get_position_from_index(context, v))
76:         .enumerate()
77:         .map(|(index, position)| TemporaryVertex {
78:             bucket: {
79:                 const GROUPS: u16 = 2048;
80:                 let t = (position[c_max] - min[c_max]) / d[c_max];
81:                 let group = (GROUPS as f32 * t.clamp(0., 1.)) as u16;
82:                 group.clamp(0, GROUPS - 1)
83:             },
84:             position,
85:             original_index: index,
