100: ) {
101:     // If there is only a single element (or no elements), merging is complete.
102:     if buffer.len() < 2 {
103:         return;
104:     }
105: 
106:     // make bbox
107:     let (min, max) = buffer
108:         .iter()
109:         .map(|t| t.position)
110:         .fold(None, |state, v| {
111:             let (mut min, mut max) = state.unwrap_or((v, v));
112: 
113:             for c in 0..3 {
114:                 min[c] = min[c].min(v[c]);
115:                 max[c] = max[c].max(v[c]);
116:             }
117: 
118:             Some((min, max))
119:         })
120:         .unwrap();
121: 
122:     let d = max - min;
123: 
124:     let c = if d.y > d.x && d.y > d.z {
125:         1
126:     } else if d.z > d.x {
127:         2
128:     } else {
129:         0
130:     };
