132:     let sep = 0.5f32 * (max[c] + min[c]);
133: 
134:     // stop if all vertices are NaNs
135:     if !sep.is_finite() {
136:         return;
137:     }
138: 
139:     // terminate recursion when the separation/average value
140:     // is no longer strictly between fMin and fMax values.
141:     if !(min[c] < sep && sep < max[c]) {
142:         // complete the weld
143:         for (l, v_a) in buffer.iter().enumerate() {
144:             let i = v_a.original_index;
145:             let index = vertices[i];
146: 
147:             let a = (
148:                 v_a.position,
149:                 get_normal_from_index(context, index),
150:                 get_texture_coordinate_from_index(context, index),
151:             );
152: 
153:             let j = buffer.iter().take(l).find_map(|v_b| {
154:                 let j = v_b.original_index;
155:                 let index = vertices[j];
156: 
157:                 let b = (
158:                     v_b.position,
159:                     get_normal_from_index(context, index),
160:                     get_texture_coordinate_from_index(context, index),
161:                 );
162: 
163:                 (a == b).then_some(j)
164:             });
