182:         unsorted = match (a, b) {
183:             (Some(a), Some(b)) => {
184:                 buffer.swap(a, b);
185:                 (a + 1)..b
186:             }
187:             (None, Some(b)) => unsorted.start..(b + 1),
188:             (Some(a), None) => a..(a + 1),
189:             (None, None) => unsorted,
