38:     fn eq(&self, other: &Self) -> bool {
39:         self.s == other.s
40:             && self.t == other.t
41:             && self.s_magnitude == other.s_magnitude
42:             && self.t_magnitude == other.t_magnitude
43:     }
44: }
45: 
46: impl<O: Ops> Copy for RawTangentSpace<O> {}
47: 
48: impl<O: Ops> Clone for RawTangentSpace<O> {
49:     fn clone(&self) -> Self {
50:         *self
51:     }
52: }
53: 
54: impl<O: Ops> RawTangentSpace<O> {
55:     pub(super) const ZERO: Self = Self {
56:         s: Vec3::ZERO,
57:         t: Vec3::ZERO,
58:         s_magnitude: 0f32,
59:         t_magnitude: 0f32,
60:     };
61: }
62: 
63: impl<O: Ops> RawTangentSpace<O> {
64:     /// Combines two [`RawTangentSpace`] values using an algorithm _similar_ to
65:     /// averaging.
66:     /// This is not strictly a mean, as it combines vector magnitudes and directions
67:     /// separately.
68:     /// For example, if `lhs.s` and `rhs.t` are `a` and `-a` (for some arbitrary vector `a`),
69:     /// the expected mean would be `0`.
70:     /// However, this method will instead return `a` (as `(a + a) / 2 == a`).
71:     pub(super) fn combine(self, rhs: Self) -> Self {
72:         // this if is important. Due to floating point precision
73:         // averaging when ts0==ts1 will cause a slight difference
74:         // which results in tangent space splits later on
75:         if self == rhs {
76:             self
77:         } else {
78:             // TODO: Determine if `s_magnitude` and `t_magnitude` are being calculated incorrectly.
79:             //       This matches the C implementation, but may be incorrect.
80:             RawTangentSpace {
81:                 s_magnitude: 0.5f32 * (self.s_magnitude + rhs.s_magnitude),
82:                 t_magnitude: 0.5f32 * (self.t_magnitude + rhs.t_magnitude),
83:                 s: (self.s + rhs.s).normalized_or_zero(),
84:                 t: (self.t + rhs.t).normalized_or_zero(),
85:             }
86:         }
87:     }
88: }

