"""Qualify exact native index mutation and browser byte provenance reads."""
from pathlib import Path
import hashlib
import json
import subprocess

A = Path(__file__).resolve().parent
R = A.parent
W = R.parent.parent
REV = '33714256b6313ce86fdfbb534c54d92d024d7726'

def sha(p):
    with p.open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()

def read(p):
    return json.loads(p.read_bytes())

def ref(p):
    return {'path': p.relative_to(R).as_posix(), 'sha256': sha(p)}

def checked(value):
    p = R / value['path']
    assert p.resolve().is_relative_to(R) and sha(p) == value['sha256']
    return read(p)

def pointer(value, path):
    for part in path.split('/')[1:]:
        value = value[int(part)] if isinstance(value, list) else value[part]
    return value

def build(ledger, queue):
    co = ledger['segovb_continuation']['lens12']
    inherited, = [v for v in ledger['lens_coverage'] if v['number'] == 12]
    assert len(co['connected_body_receipts']) == 144 and len(co['native_receipts']) == 6
    assert queue['entries'][2249]['status'] == queue['entries'][2250]['status'] == 'open-granular-reconciliation'
    discovery_path = A / 'DISCOVERY-ROOT-L12-TANGENT-MUTATIONS-BROWSER-001.json'
    assert sha(discovery_path) == 'a065a9e182fdbb707d034549e6ff091e99b817e0b5b1a30dfc08444978b4c6de'
    discovery = read(discovery_path)
    assert discovery['unique_receipts'] == 1073 and len(discovery['exact_hash_hits']) == 7
    for value in discovery['searched_own_lens_receipts']:
        checked(value)
    specs = [
        ('READ-ROOT-L12-TANGENT-MUTATIONS-BROWSER-001.json', '34cd2c9be1498bfa0faf570c01012efdd91ca070116b0388115d4efe3f02340f', 64, 408),
        ('READ-ROOT-L12-BROWSER-MESH-PROVENANCE-REASSESSMENT-001.json', '37db64d85062e629e1eeb5a20d74b662ff5fca08c56f1f4a2c2c319902a9dc17', 0, 489),
        ('READ-ROOT-L12-BROWSER-RUNTIME-IDENTITY-REASSESSMENT-001.json', 'bb33cf71edd02e192bc462a3dc1b97f7b89667321d3baf596c64417ec2e4f460', 0, 30),
    ]
    scopes, fresh_scopes, packets, observations = [], [], [], []
    for name, digest, fresh_count, reused_count in specs:
        p = A / name
        assert sha(p) == digest
        packet = read(p)
        reg = checked(packet['registration'])
        assert reg['registered_at'] < packet['at']
        if fresh_count:
            assert reg['prospective'] is True and reg['fresh_lines_registered'] == fresh_count
            assert packet['fresh_root_personal_source_lines'] == fresh_count
        else:
            assert reg['prospective_reassessment'] is True and packet['new_body_credit'] == 0
        assert packet['uncredited_reassessment_lines'] == reused_count
        assert packet['source_adoption_performed'] is packet['product_execution'] is packet['tests_executed'] is False
        fresh, reused = 0, 0
        for ix, row in enumerate(packet['rows']):
            source = row['source']
            assert source == reg['sources'][ix] and source['revision'] == REV
            assert row['assessed_ranges'] == source['ranges'] and row['author'] == '/root'
            assert row['untruncated_body_status']
            raw = (R / source['source_object']).read_bytes()
            assert hashlib.sha256(raw).hexdigest() == source['source_sha256']
            assert len(raw) == source['bytes'] and len(raw.decode().splitlines()) == source['actual_EOF']
            assert raw == subprocess.check_output(['git', 'show', REV + ':' + source['path']], cwd=W)
            row_fresh = row['fresh_root_personal_lines'] if fresh_count else 0
            row_reused = row['uncredited_reassessment_lines']
            assert sum(hi - lo + 1 for lo, hi in source['ranges']) == row_fresh + row_reused
            item = {'packet': ref(p), 'pointer': f'/rows/{ix}', 'source': source,
                    'fresh_root_personal_lines': row_fresh, 'uncredited_reassessment_lines': row_reused}
            if row_fresh:
                assert source['path'].endswith('/lod/gable_openings.rs')
                assert source['ranges'] == [[1, 64]] and row_fresh == 64
                assert source['prior_own_lens_read_candidate'] is None
                assert not any(v['record'].get('source_sha256', v['record'].get('sha256')) == source['source_sha256'] for v in discovery['exact_hash_hits'])
                assert row['output_chunk'] == 'b0ee33'
                fresh_scopes.append(item)
            else:
                if fresh_count:
                    candidate = source['prior_own_lens_read_candidate']
                    prior_ref, prior_pointer = candidate['receipt'], candidate['pointer']
                else:
                    prior_ref, prior_pointer = source['prior_own_lens_read'], source['prior_row_pointer']
                prior_row = pointer(checked(prior_ref), prior_pointer)
                assert prior_row.get('source_sha256', prior_row.get('sha256')) == source['source_sha256']
                if prior_ref['path'].startswith('segovb/'):
                    assert prior_ref in co['discovery_receipts']
                    ranges = prior_row['assessed_ranges']
                else:
                    prefix = 'evidence/continuation-segovb/'
                    assert prior_ref['path'].startswith(prefix)
                    assert prior_ref['path'][len(prefix):] in inherited['authoritative_receipts']
                    ranges = prior_row['actual_ranges']
