            scopes.append(item)
            fresh += row_fresh
            reused += row_reused
        assert (fresh, reused) == (fresh_count, reused_count)
        observations.extend(packet['observations'])
        packets.append(ref(p))
    assert len(fresh_scopes) == 1
    return {
