7: struct VertexKey {
8:     attributes: [u32; 8],
9:     basis: [u32; 6],
10: }
11: 
12: fn bits(value: f32) -> u32 {
13:     if value == 0.0 { 0 } else { value.to_bits() }
14: }
15: 
16: impl LodMesh {
17:     pub(crate) fn remap_vertices(&mut self) {
18:         let mut bases = vec![None; self.vertices.len()];
19:         let mut seams = vec![false; self.vertices.len()];
20:         for triangle in self.indices.as_chunks::<3>().0 {
21:             let basis = tangent_basis(triangle.map(|i| self.vertices[i as usize]));
22:             for &index in triangle {
23:                 let index = index as usize;
24:                 if let Some(previous) = bases[index] {
25:                     seams[index] |= Some(previous) != basis;
26:                 }
27:                 seams[index] |= basis.is_none();
28:                 bases[index] = basis;
29:             }
30:         }
31:         let mut unique = HashMap::with_capacity(self.vertices.len());
32:         let mut remap = Vec::with_capacity(self.vertices.len());
33:         let mut vertices = Vec::with_capacity(self.vertices.len());
34:         for (index, vertex) in self.vertices.iter().copied().enumerate() {
35:             let next = vertices.len() as u32;
36:             let mapped = if !seams[index]
37:                 && let Some(basis) = bases[index]
38:             {
39:                 let key = VertexKey::new(vertex, basis);
40:                 *unique.entry(key).or_insert(next)
41:             } else {
42:                 next
43:             };
44:             if mapped == next {
45:                 vertices.push(vertex);
46:             }
47:             remap.push(mapped);
48:         }
49:         for index in &mut self.indices {
50:             *index = remap[*index as usize];
51:         }
52:         self.vertices = vertices;
53:     }
54: }
