58:         let p = vertex.position;
59:         let n = vertex.normal;
60:         let uv = vertex.uv;
61:         Self {
62:             attributes: [p.x, p.y, p.z, n.x, n.y, n.z, uv.x, uv.y].map(bits),
63:             basis,
64:         }
65:     }
