68: fn tangent_basis([a, b, c]: [LodVertex; 3]) -> Option<[u32; 6]> {
69:     let edge_b = b.position - a.position;
70:     let edge_c = c.position - a.position;
71:     let uv_b = b.uv - a.uv;
72:     let uv_c = c.uv - a.uv;
73:     let determinant = uv_b.perp_dot(uv_c);
74:     if determinant == 0.0 || !determinant.is_finite() {
75:         return None;
76:     }
77:     let tangent = ((edge_b * uv_c.y - edge_c * uv_b.y) / determinant).normalize_or_zero();
78:     let bitangent = ((edge_c * uv_b.x - edge_b * uv_c.x) / determinant).normalize_or_zero();
79:     (tangent.is_finite() && bitangent.is_finite()).then(|| {
80:         [
81:             tangent.x,
82:             tangent.y,
83:             tangent.z,
84:             bitangent.x,
85:             bitangent.y,
86:             bitangent.z,
87:         ]
88:         .map(bits)
89:     })
90: }
