1: //! Projected open aperture follows the replicated leaf transform.
2: use super::field::{InteriorField, LightSample};
3: use adventuresim_tactical_core::prelude::{SceneBuilding, SceneWindow};
4: use bevy::prelude::*;
5: 
6: const APERTURE_CHANGE_TOLERANCE: f32 = 0.001;
7: 
8: #[derive(Clone)]
9: pub(super) struct ShutterLight {
10:     pub opening_id: adventuresim_building_generator::OpeningAssemblyId,
11:     pub contributions: Vec<(usize, LightSample)>,
12:     pub openness: f32,
13: }
14: 
15: impl InteriorField {
16:     fn update_apertures(
17:         &mut self,
18:         apertures: &[(adventuresim_building_generator::OpeningAssemblyId, f32)],
19:     ) -> bool {
20:         let mut changed = false;
21:         for shutter in &mut self.shutters {
22:             let openness = apertures
23:                 .iter()
24:                 .find(|entry| entry.0 == shutter.opening_id)
25:                 .map_or(0.0, |entry| entry.1.clamp(0.0, 1.0));
26:             if (shutter.openness - openness).abs() > APERTURE_CHANGE_TOLERANCE {
27:                 shutter.openness = openness;
28:                 changed = true;
29:             }
30:         }
31:         if changed {
32:             self.samples.clone_from(&self.base_samples);
33:             for shutter in &self.shutters {
34:                 for &(index, light) in &shutter.contributions {
35:                     self.samples[index].positive += light.positive * shutter.openness;
36:                     self.samples[index].negative += light.negative * shutter.openness;
37:                 }
38:             }
39:             for sample in &mut self.samples {
40:                 sample.positive = sample
41:                     .positive
42:                     .truncate()
43:                     .min(Vec3::ONE)
44:                     .extend(sample.positive.w);
45:                 sample.negative = sample.negative.truncate().min(Vec3::ONE).extend(0.0);
46:             }
47:         }
48:         changed
49:     }
50: }
51: 
52: pub(super) fn update_shutter_light(
53:     mut fields: Query<(&SceneBuilding, &mut InteriorField)>,
54:     windows: Query<(&SceneWindow, &GlobalTransform)>,
55: ) {
56:     for (building, mut field) in &mut fields {
57:         if field.shutters.is_empty() {
58:             continue;
59:         }
60:         let apertures = windows
61:             .iter()
62:             .filter(|(window, _)| window.building_id == building.id)
63:             .map(|(window, transform)| {
64:                 let tangent = transform
65:                     .affine()
66:                     .transform_vector3(Vec3::X)
67:                     .normalize_or_zero();
68:                 (
69:                     window.opening_id,
70:                     1.0 - tangent.dot(window.tangent.vector()).abs().clamp(0.0, 1.0),
71:                 )
72:             })
73:             .collect::<Vec<_>>();
74:         if field.bypass_change_detection().update_apertures(&apertures) {
75:             field.set_changed();
76:         }
77:     }
78: }
