8: const SAMPLE_HEIGHT_FRACTION: f32 = 0.5;
9: const MAX_SAMPLE_IRRADIANCE: f32 = 1.0;
10: 
11: /// The six ambient-cube lobes, with a room identifier in positive.w (zero is outside).
12: #[derive(Clone, Copy, Debug, Default, PartialEq, ShaderType)]
