48:     pub fn from_plan(plan: &BuildingPlan, local_origin: Vec3) -> Self {
49:         let cells: Vec<_> = plan
50:             .storeys
51:             .iter()
52:             .flat_map(|s| &s.rooms)
53:             .flat_map(|r| &r.cells)
54:             .collect();
55:         let min_x = cells.iter().map(|c| c.x).min().unwrap_or(0);
56:         let min_z = cells.iter().map(|c| c.z).min().unwrap_or(0);
57:         let width = cells.iter().map(|c| c.x - min_x + 1).max().unwrap_or(1) as u32;
58:         let depth = cells.iter().map(|c| c.z - min_z + 1).max().unwrap_or(1) as u32;
59:         let levels = plan
60:             .storeys
61:             .iter()
62:             .map(|s| u32::from(s.level) + 1)
63:             .max()
64:             .unwrap_or(1);
65:         let dimensions = UVec3::new(width, levels, depth);
66:         let mut samples = vec![LightSample::default(); (width * depth * levels) as usize];
67:         let mut shutters = std::collections::BTreeMap::<
68:             adventuresim_building_generator::OpeningAssemblyId,
69:             Vec<(usize, LightSample)>,
70:         >::new();
71:         for storey in &plan.storeys {
72:             for room in &storey.rooms {
73:                 for cell in &room.cells {
74:                     let centre = cell.centre();
75:                     let point = Vec3::new(
76:                         centre.x,
77:                         plan.storey_height_metres * SAMPLE_HEIGHT_FRACTION,
78:                         centre.y,
79:                     );
80:                     let index = ((u32::from(storey.level) * depth + (cell.z - min_z) as u32)
81:                         * width
82:                         + (cell.x - min_x) as u32) as usize;
83:                     let mut positive = Vec3::ZERO;
84:                     let mut negative = Vec3::ZERO;
85:                     for opening in &storey.openings {
86:                         let wall = storey.walls[opening.wall];
87:                         // Opaque doors contribute no daylight. Glass keeps transmitting when closed.
88:                         if !wall.exterior()
89:                             || wall.inside_room != room.id
90:                             || matches!(opening.kind, OpeningKind::Door)
91:                         {
92:                             continue;
93:                         }
94:                         let (opaque_closure, source_positive, source_negative) =
95:                             opening_light(plan, storey, opening, point);
96:                         if let Some(shutter) = opaque_closure {
97:                             shutters.entry(shutter).or_default().push((
98:                                 index,
99:                                 LightSample {
100:                                     positive: source_positive.extend(0.0),
101:                                     negative: source_negative.extend(0.0),
102:                                 },
103:                             ));
104:                         } else {
105:                             positive += source_positive;
106:                             negative += source_negative;
107:                         }
108:                     }
109:                     let index = ((u32::from(storey.level) * depth + (cell.z - min_z) as u32)
110:                         * width
111:                         + (cell.x - min_x) as u32) as usize;
112:                     samples[index] = LightSample {
113:                         positive: positive
114:                             .min(Vec3::splat(MAX_SAMPLE_IRRADIANCE))
115:                             .extend(f32::from(room.id) + 1.0),
116:                         negative: negative.min(Vec3::splat(MAX_SAMPLE_IRRADIANCE)).extend(0.0),
117:                     };
118:                 }
119:             }
120:         }
121:         Self {
122:             origin: Vec3::new(
123:                 f32::from(min_x) * CELL_SIZE_METRES,
124:                 0.0,
125:                 f32::from(min_z) * CELL_SIZE_METRES,
126:             ) - local_origin,
127:             dimensions,
128:             storey_height: plan.storey_height_metres,
129:             base_samples: samples.clone(),
130:             samples,
131:             shutters: shutters
132:                 .into_iter()
133:                 .map(
134:                     |(opening_id, contributions)| super::shutters::ShutterLight {
135:                         opening_id,
136:                         contributions,
137:                         openness: 0.0,
138:                     },
139:                 )
140:                 .collect(),
141:         }
142:     }
