144:     pub(super) fn sample(&self, local_position: Vec3) -> Option<LightSample> {
145:         let position = (local_position - self.origin)
146:             / Vec3::new(CELL_SIZE_METRES, self.storey_height, CELL_SIZE_METRES);
147:         if position.cmplt(Vec3::ZERO).any() || position.cmpge(self.dimensions.as_vec3()).any() {
148:             return None;
149:         }
150:         let cell = position.floor().as_uvec3();
151:         let index = ((cell.y * self.dimensions.z + cell.z) * self.dimensions.x + cell.x) as usize;
152:         let sample = self.samples[index];
153:         (sample.positive.w > 0.0).then_some(sample)
154:     }
155: }
