157: /// One aperture contributes only within its owning room; opaque leaves start closed.
158: fn opening_light(
159:     plan: &BuildingPlan,
160:     storey: &adventuresim_building_generator::StoreyPlan,
161:     opening: &adventuresim_building_generator::Opening,
162:     point: Vec3,
163: ) -> (
164:     Option<adventuresim_building_generator::OpeningAssemblyId>,
165:     Vec3,
166:     Vec3,
167: ) {
168:     const OPENING_MATCH_TOLERANCE_METRES: f32 = 0.01;
169:     let wall = storey.walls[opening.wall];
170:     let opaque = plan
171:         .opening_assemblies
172:         .iter()
173:         .find(|assembly| {
174:             assembly
175:                 .closure
176:                 .layers
177:                 .contains(&adventuresim_building_generator::ClosureKind::TimberShutter)
178:                 && assembly.frame.origin.distance(wall.centre()) < OPENING_MATCH_TOLERANCE_METRES
179:                 && (assembly.sill_elevation_metres
180:                     - (f32::from(storey.level) * plan.storey_height_metres + opening.sill_metres))
181:                     .abs()
182:                     < OPENING_MATCH_TOLERANCE_METRES
183:         })
184:         .map(|assembly| assembly.id);
185:     let centre = wall.centre();
186:     let source = Vec3::new(
187:         centre.x,
188:         opening.sill_metres + opening.height_metres * 0.5,
189:         centre.y,
190:     );
191:     let delta = source - point;
