19: const MAX_LIT_BUILDINGS: usize = 16;
20: // Two MiB of samples keep the GPU allocation (and material bindings) stable
21: // as nearby buildings enter and leave the daylight field.
22: const MAX_GPU_SAMPLES: usize = 65_536;
23: const FIELD_DISTANCE_METRES: f32 = 100.0;
24: const DAYLIGHT_IRRADIANCE: f32 = 12_000.0;
