28: #[derive(Clone, Copy, Default, Debug, PartialEq, ShaderType)]
29: struct GpuBuilding {
30:     local_from_world: Mat4,
31:     world_min: Vec4,
32:     world_max: Vec4,
33:     origin_and_cell: Vec4,
34:     dimensions_and_offset: UVec4,
35:     height: Vec4,
