38: impl GpuBuilding {
39:     fn from_field(field: &InteriorField, transform: &GlobalTransform, offset: usize) -> Self {
40:         let local_size = field.dimensions.as_vec3()
41:             * Vec3::new(CELL_SIZE_METRES, field.storey_height, CELL_SIZE_METRES);
42:         let centre = transform.transform_point(field.origin + local_size * 0.5);
43:         let half = transform.affine().matrix3.abs() * (local_size * 0.5);
44:         Self {
45:             local_from_world: transform.to_matrix().inverse(),
46:             world_min: (centre - half).extend(0.0),
47:             world_max: (centre + half).extend(0.0),
48:             origin_and_cell: field.origin.extend(CELL_SIZE_METRES),
49:             dimensions_and_offset: field.dimensions.extend(offset as u32),
50:             height: Vec4::new(field.storey_height, 0.0, 0.0, 0.0),
51:         }
52:     }
53: }
