101:     pub(crate) fn sample_at(&self, position: Vec3) -> Vec3 {
102:         for building in self.data.buildings.iter().take(self.data.counts.x as usize) {
103:             let local = building.local_from_world.transform_point3(position);
104:             let cell = (local - building.origin_and_cell.truncate())
105:                 / Vec3::new(
106:                     building.origin_and_cell.w,
107:                     building.height.x,
108:                     building.origin_and_cell.w,
109:                 );
110:             let dimensions = building.dimensions_and_offset;
111:             if cell.cmplt(Vec3::ZERO).any() || cell.cmpge(dimensions.truncate().as_vec3()).any() {
112:                 continue;
113:             }
114:             let cell = cell.floor().as_uvec3();
115:             let index = dimensions.w + (cell.y * dimensions.z + cell.z) * dimensions.x + cell.x;
116:             let sample = self.data.samples[index as usize];
117:             if sample.positive.w > 0.0 {
118:                 return sample.positive.truncate() + sample.negative.truncate();
119:             }
