164: fn daylight_response(celestial: &PresentedCelestialLighting) -> Vec4 {
165:     let Some(snapshot) = &celestial.snapshot else {
166:         return Vec4::ZERO;
167:     };
168:     let day = ((snapshot.sun_altitude_degrees - DAYLIGHT_START_ALTITUDE_DEGREES)
169:         / (FULL_DAYLIGHT_ALTITUDE_DEGREES - DAYLIGHT_START_ALTITUDE_DEGREES))
170:         .clamp(0.0, 1.0);
171:     let day = day * day * (3.0 - 2.0 * day);
172:     (snapshot.ambient_color * DAYLIGHT_IRRADIANCE * day * snapshot.weather_transmission).extend(day)
173: }
174: 
175: fn upload_field(
176:     cameras: Query<(&GlobalTransform, &Camera), With<Camera3d>>,
177:     fields: Query<(Entity, Ref<InteriorField>, &GlobalTransform)>,
178:     celestial: Res<PresentedCelestialLighting>,
179:     mut gpu: ResMut<InteriorLightingGpu>,
180:     mut buffers: ResMut<Assets<ShaderBuffer>>,
181: ) {
182:     let daylight = daylight_response(&celestial);
183:     let mut data = GpuField {
184:         daylight,
185:         outdoor_irradiance: daylight
186:             * (bevy::light::light_consts::lux::RAW_SUNLIGHT / DAYLIGHT_IRRADIANCE),
187:         ..default()
188:     };
189:     let positions = cameras
190:         .iter()
191:         .filter(|(_, camera)| camera.is_active)
192:         .map(|(transform, _)| transform.translation())
193:         .collect::<Vec<_>>();
194:     if !positions.is_empty() {
195:         let mut nearby: Vec<_> = fields
196:             .iter()
197:             .filter_map(|(entity, field, transform)| {
198:                 let size = field.dimensions.as_vec3()
199:                     * Vec3::new(CELL_SIZE_METRES, field.storey_height, CELL_SIZE_METRES);
200:                 let inverse = transform.affine().inverse();
201:                 let distance = positions
202:                     .iter()
203:                     .map(|position| {
204:                         let local = inverse.transform_point3(*position) - field.origin;
205:                         (local - local.clamp(Vec3::ZERO, size)).length_squared()
206:                     })
207:                     .fold(f32::INFINITY, f32::min);
208:                 (distance <= FIELD_DISTANCE_METRES * FIELD_DISTANCE_METRES)
209:                     .then_some((distance, entity, field, transform))
210:             })
211:             .collect();
212:         nearby.sort_by(|a, b| a.0.total_cmp(&b.0).then(a.1.cmp(&b.1)));
213:         nearby.truncate(MAX_LIT_BUILDINGS);
214:         let mut sample_count = data.samples.len();
215:         nearby.retain(|entry| {
216:             let fits = sample_count + entry.2.samples.len() <= MAX_GPU_SAMPLES;
217:             if fits {
218:                 sample_count += entry.2.samples.len();
219:             }
220:             fits
221:         });
222:         // Stable ordering avoids re-uploading every sample when the camera moves
223:         // between two buildings that are already resident.
224:         nearby.sort_by_key(|entry| entry.1);
225:         let selection: Vec<_> = nearby
226:             .iter()
227:             .map(|entry| (entry.1, entry.3.to_matrix()))
228:             .collect();
229:         if selection == gpu.selection
230:             && data.daylight == gpu.data.daylight
231:             && !nearby.iter().any(|entry| entry.2.is_changed())
232:         {
233:             return;
234:         }
235:         gpu.selection = selection;
236:         for (_, _, field, transform) in nearby {
237:             let index = data.counts.x as usize;
238:             data.buildings[index] = GpuBuilding::from_field(&field, transform, data.samples.len());
239:             data.samples.extend_from_slice(&field.samples);
240:             data.counts.x += 1;
241:         }
242:     } else {
243:         gpu.selection.clear();
244:     }
245:     if data != gpu.data {
246:         if let Some(mut buffer) = buffers.get_mut(&gpu.buffer) {
247:             buffer.set_data(data.for_upload());
248:         }
249:         gpu.data = data;
250:     }
251: }

