1: //! Conversation positions use the furnished tactical building's circulation proof.
2: use adventuresim_building_generator::{
3:     CollisionCuboid, ResolvedItemId, StoreyIndex,
4:     interior::{InteriorLayout, StandingClearance},
5:     spatial_geometry::{Architectural, Elevation, Position},
6: };
7: use adventuresim_tactical_core::{prelude::GeneratedBuilding, scene_coordinates::Scene};
8: use bevy::prelude::*;
9: 
10: pub(super) const CONVERSATION_DISTANCE_METRES: f32 = 1.1;
11: const RESIDENT_SPACING_METRES: f32 = 0.65;
12: 
13: #[derive(Clone, Copy)]
14: pub(super) struct ConversationPose {
15:     pub(super) anchor: Position<Scene>,
16:     pub(super) facing: Quat,
17: }
18: 
19: impl ConversationPose {
20:     pub(super) fn in_building(
21:         building: &GeneratedBuilding,
22:         layout: &InteriorLayout,
23:     ) -> Result<Vec<Self>> {
24:         let field = crate::presentation::interior_lighting::InteriorField::from_plan(
25:             &building.plan,
26:             Vec3::ZERO,
27:         );
28:         let obstacles = obstacles(building, layout)?;
29:         let mut candidates = Vec::new();
30:         let mut clearances = std::collections::BTreeMap::new();
31:         // Circulation routes share long runs of points. Score each physical point
32:         // once, preserving first occurrence and the existing daylight ordering.
33:         let mut visited = std::collections::HashSet::new();
34:         for path in &layout.paths {
35:             for point in path
36:                 .points
37:                 .iter()
38:                 .filter(|point| point.storey == StoreyIndex::GROUND)
39:             {
40:                 let centre = point.position_metres.metres();
41:                 if !visited.insert((centre.x.to_bits(), centre.y.to_bits())) {
42:                     continue;
43:                 }
44:                 let height = floor_height(building, centre);
45:                 let clearance = match clearances.entry(height.to_bits()) {
46:                     std::collections::btree_map::Entry::Occupied(entry) => entry.into_mut(),
47:                     std::collections::btree_map::Entry::Vacant(entry) => entry.insert(
48:                         StandingClearance::new(&obstacles, Elevation::from_metres(height)?)?,
49:                     ),
50:                 };
51:                 for direction in [Vec2::X, Vec2::Y, Vec2::NEG_X, Vec2::NEG_Y] {
52:                     let camera = centre + direction * CONVERSATION_DISTANCE_METRES;
53:                     if !clearance.is_clear(
54:                         Position::from_metres(Vec3::new(centre.x, height, centre.y))?,
55:                         Position::from_metres(Vec3::new(camera.x, height, camera.y))?,
56:                     ) {
57:                         continue;
58:                     }
59:                     let anchor = Vec3::new(centre.x, height, centre.y);
60:                     let daylight = field.directional_daylight_at(
61:                         anchor + Vec3::Y,
62:                         Vec3::new(direction.x, 0.0, direction.y),
63:                     );
64:                     candidates.push((daylight, anchor, direction));
65:                 }
66:             }
67:         }
68:         candidates.sort_by(|a, b| b.0.total_cmp(&a.0));
69:         let transform = building.transform()?;
70:         let origin = building.collision.bounds.centre()?.metres();
71:         let mut selected: Vec<Self> = Vec::new();
72:         for (_, point, direction) in candidates {
73:             let anchor = Position::from_metres(transform.transform_point(point - origin))?;
74:             if selected
75:                 .iter()
76:                 .any(|p| p.anchor.metres().distance(anchor.metres()) < RESIDENT_SPACING_METRES)
77:             {
78:                 continue;
79:             }
80:             selected.push(Self {
81:                 anchor,
82:                 facing: transform.rotation * Quat::from_rotation_y(direction.x.atan2(direction.y)),
83:             });
84:         }
85:         Ok(selected)
86:     }
87: }
88: 
89: fn floor_height(building: &GeneratedBuilding, point: Vec2) -> f32 {
90:     building
91:         .collision
92:         .cuboids
93:         .iter()
94:         .filter(|solid| {
95:             solid.crossfall_radians.radians() == 0.0 && solid.longfall_radians.radians() == 0.0
96:         })
97:         .filter(|solid| {
98:             let relative = Quat::from_rotation_y(-solid.yaw_radians.radians())
99:                 * (Vec3::new(point.x, solid.centre.metres().y, point.y) - solid.centre.metres());
100:             relative.x.abs() <= solid.size.metres().x * 0.5
101:                 && relative.z.abs() <= solid.size.metres().z * 0.5
102:         })
103:         .map(|solid| solid.centre.metres().y + solid.size.metres().y * 0.5)
104:         .filter(|height| height.abs() <= 0.3)
105:         .max_by(f32::total_cmp)
106:         .unwrap_or(0.0)
107: }
108: 
109: fn obstacles(
110:     building: &GeneratedBuilding,
111:     layout: &InteriorLayout,
112: ) -> Result<Vec<CollisionCuboid<Architectural>>> {
113:     let mut obstacles = building.collision.cuboids.clone();
114:     for placement in &layout.placements {
115:         let size = placement.key.interior_spec()?.size_metres.metres();
116:         obstacles.push(CollisionCuboid::from_metres(
117:             ResolvedItemId(0),
118:             Vec3::new(
119:                 placement.centre_metres.metres().x,
120:                 placement.floor_height(&building.plan)?.metres() + size.y * 0.5,
121:                 placement.centre_metres.metres().y,
122:             ),
123:             size,
124:             placement.yaw_radians().radians(),
125:             0.0,
126:             0.0,
127:         )?);
128:     }
129:     Ok(obstacles)
130: }

