47: /// Compile fixed bars for every opening declaring an iron-bar closure layer.
48: ///
49: /// Fixed bars compile independently of the opening's operable state. Invalid
50: /// frame or bar geometry returns [`crate::CollisionError`] with the bar's
51: /// source identity, which encodes the opening identity and bar ordinal.
52: pub fn compile_window_bars(plan: &BuildingPlan) -> CollisionResult<Vec<WindowBarSpec>> {
53:     plan.opening_assemblies
54:         .iter()
55:         .filter(|opening| opening.closure.layers.contains(&ClosureKind::IronBars))
56:         .flat_map(|opening| {
57:             let width = opening.profile.interior_width_metres();
58:             let height = opening.profile.clear_height_metres();
59:             let count = if width >= THREE_BAR_MINIMUM_WIDTH_METRES {
60:                 3
61:             } else {
62:                 2
63:             };
64:             (0..count).map(move |index| {
65:                 let fraction = (index + 1) as f32 / (count + 1) as f32;
66:                 let offset = (fraction - 0.5) * width;
67:                 let plan_position = opening.frame.origin + opening.frame.tangent * offset;
68:                 let source = ResolvedItemId((7_u64 << 60) | (opening.id.0 << 8) | index as u64);
69:                 let admit = || -> GeometryResult<WindowBarSpec> {
70:                     // Bars retain the authored frame without normalizing set-out arithmetic.
71:                     PlanDirection::<Architectural>::from_normalized(opening.frame.tangent)?;
72:                     PlanDirection::<Architectural>::from_normalized(opening.frame.outward)?;
73:                     Ok(WindowBarSpec {
74:                         opening: opening.id,
75:                         source,
76:                         centre: Position::from_metres(Vec3::new(
77:                             plan_position.x,
78:                             opening.sill_elevation_metres + height * 0.5,
79:                             plan_position.y,
80:                         ))?,
81:                         size_metres: CuboidDimensions::from_metres(Vec3::new(
82:                             0.035, height, 0.035,
83:                         ))?,
84:                         yaw_radians: Radians::new(
85:                             -opening.frame.tangent.y.atan2(opening.frame.tangent.x),
86:                         )?,
87:                     })
88:                 };
89:                 admit().map_err(|cause| crate::CollisionError {
90:                     source_id: source,
91:                     cause,
92:                 })
93:             })
94:         })
95:         .collect()
96: }
