100: /// Ineligible openings are excluded. A missing supported closure or invalid
101: /// selected leaf geometry returns [`WindowError`] with the opening identity and
102: /// available closure-source identities.
103: pub fn compile_operable_windows(
104:     plan: &BuildingPlan,
105: ) -> WindowResult<Vec<WindowSpec<Architectural>>> {
106:     let solids = plan
107:         .resolved_geometry
108:         .solids
109:         .iter()
110:         .map(|solid| (solid.id, solid))
111:         .collect::<BTreeMap<_, _>>();
112:     plan.opening_assemblies
113:         .iter()
114:         .filter(|opening| {
115:             opening.use_kind == OpeningUse::Window
116:                 && opening.closure.state == ClosureState::Operable
117:                 && opening.frame.inside_room.is_some()
118:                 && opening.frame.outside_room.is_none()
119:         })
120:         .map(|opening| {
121:             let solid = opening
122:                 .closure_solids
123:                 .iter()
124:                 .find_map(|id| {
125:                     solids.get(id).copied().filter(|solid| {
126:                         matches!(
127:                             solid.role,
128:                             SolidRole::LeadedGlazing | SolidRole::OpeningClosure
129:                         )
130:                     })
131:                 })
132:                 .ok_or_else(|| WindowError {
133:                     opening: opening.id,
134:                     source_id: opening.closure_solids.first().copied(),
135:                     cause: WindowErrorCause::MissingClosure {
136:                         sources: opening.closure_solids.clone(),
137:                     },
138:                 })?;
139:             let admit = || {
140:                 WindowSpec::from_solid(
141:                     opening.id,
142:                     PlanDirection::from_vector(opening.frame.tangent)?,
143:                     PlanDirection::from_vector(opening.frame.outward)?,
144:                     if opening.closure.layers.contains(&ClosureKind::IronBars) {
145:                         WindowBarPresence::Present
146:                     } else {
147:                         WindowBarPresence::Absent
148:                     },
149:                     solid,
150:                 )
151:             };
152:             admit().map_err(|cause| WindowError {
153:                 opening: opening.id,
154:                 source_id: Some(solid.id),
155:                 cause: cause.into(),
156:             })
157:         })
158:         .collect()
159: }
