161: impl WindowSpec<Architectural> {
162:     fn from_solid(
163:         opening: OpeningAssemblyId,
164:         tangent: PlanDirection<Architectural>,
165:         outward: PlanDirection<Architectural>,
166:         bars: WindowBarPresence,
167:         solid: &ResolvedSolid,
168:     ) -> GeometryResult<Self> {
169:         let tangent_owner = tangent;
170:         let outward_owner = outward;
171:         let tangent = tangent_owner.vector();
172:         let outward = outward_owner.vector();
173:         let width =
174:             tangent.x.abs() * solid.size.metres().x + tangent.y.abs() * solid.size.metres().z;
175:         let thickness =
176:             outward.x.abs() * solid.size.metres().x + outward.y.abs() * solid.size.metres().z;
177:         let hinge_centre =
178:             solid.centre.metres() - Vec3::new(tangent.x, 0.0, tangent.y) * width * 0.5;
179:         let positive_swing = Quat::from_rotation_y(SWING_DIRECTION_PROBE_RADIANS)
180:             * Vec3::new(tangent.x, 0.0, tangent.y);
181:         let enters_room = Vec2::new(positive_swing.x, positive_swing.z).dot(-outward) > 0.0;
182:         Ok(Self {
183:             leaf: if solid.role == SolidRole::LeadedGlazing {
184:                 WindowLeafKind::LeadedGlass
185:             } else {
186:                 WindowLeafKind::TimberShutter
187:             },
188:             opening,
189:             source: solid.id,
190:             closed_centre: solid.centre,
191:             hinge_centre: Position::from_metres(hinge_centre)?,
192:             size_metres: LeafDimensions::from_metres(Vec3::new(
193:                 width,
194:                 solid.size.metres().y,
195:                 thickness.max(MINIMUM_LEAF_THICKNESS_METRES),
196:             ))?,
197:             closed_yaw_radians: Radians::new(-tangent.y.atan2(tangent.x))?,
198:             tangent: tangent_owner,
199:             outward: outward_owner,
200:             open_angle_radians: Radians::new(if enters_room {
201:                 CASEMENT_OPEN_ANGLE_RADIANS
202:             } else {
203:                 -CASEMENT_OPEN_ANGLE_RADIANS
204:             })?,
205:             bars,
206:         })
207:     }
208: }
