513:     fn redraw_requested(&mut self, event_loop: &ActiveEventLoop) {
514:         let mut redraw_message_cursor = MessageCursor::<RequestRedraw>::default();
515:         let mut close_message_cursor = MessageCursor::<WindowCloseRequested>::default();
516: 
517:         let mut focused_windows_state: SystemState<(Res<WinitSettings>, Query<(Entity, &Window)>)> =
518:             SystemState::new(self.world_mut());
519: 
520:         let (config, windows) = focused_windows_state.get(self.world()).unwrap();
521:         let focused = windows.iter().any(|(_, window)| window.focused);
522: 
523:         let mut update_mode = config.update_mode(focused);
524:         let mut should_update = self.should_update(update_mode);
525: 
526:         if self.startup_forced_updates > 0 {
527:             self.startup_forced_updates -= 1;
528:             // Ensure that an update is triggered on the first iterations for app initialization
529:             should_update = true;
530:         }
531: 
532:         if self.lifecycle == AppLifecycle::WillSuspend {
533:             self.lifecycle = AppLifecycle::Suspended;
534:             // Trigger one last update to enter the suspended state
535:             should_update = true;
536:             self.ran_update_since_last_redraw = false;
537: 
538:             #[cfg(target_os = "android")]
539:             {
540:                 // Remove the `RawHandleWrapper` from the primary window.
541:                 // This will trigger the surface destruction.
542:                 let mut query = self
543:                     .world_mut()
544:                     .query_filtered::<Entity, With<PrimaryWindow>>();
545:                 if let Ok(entity) = query.single(&self.world()) {
546:                     self.world_mut()
547:                         .entity_mut(entity)
548:                         .remove::<RawHandleWrapper>();
549:                 }
550:             }
551:         }
552: 
553:         if self.lifecycle == AppLifecycle::WillResume {
554:             self.lifecycle = AppLifecycle::Running;
555:             // Trigger the update to enter the running state
556:             should_update = true;
557:             // Trigger the next redraw to refresh the screen immediately
558:             self.redraw_requested = true;
559: 
560:             #[cfg(target_os = "android")]
561:             {
562:                 // Get windows that are cached but without raw handles. Those window were already created, but got their
563:                 // handle wrapper removed when the app was suspended.
564: 
565:                 let mut query = self.world_mut()
566:                     .query_filtered::<(Entity, &Window, &CursorOptions), (With<CachedWindow>, Without<RawHandleWrapper>)>();
567:                 if let Ok((entity, window, cursor_options)) = query.single(&self.world()) {
568:                     let window = window.clone();
569:                     let cursor_options = cursor_options.clone();
570: 
571:                     WINIT_WINDOWS.with_borrow_mut(|winit_windows| {
572:                         ACCESS_KIT_ADAPTERS.with_borrow_mut(|adapters| {
573:                             let mut create_window =
574:                                 SystemState::<CreateWindowParams>::from_world(self.world_mut());
575: 
576:                             let (.., mut handlers, accessibility_requested, monitors) =
577:                                 create_window.get_mut(self.world_mut()).unwrap();
578: 
579:                             let winit_window = winit_windows.create_window(
580:                                 event_loop,
581:                                 entity,
582:                                 &window,
583:                                 &cursor_options,
584:                                 adapters,
585:                                 &mut handlers,
586:                                 &accessibility_requested,
587:                                 &monitors,
588:                             );
589: 
590:                             let wrapper = RawHandleWrapper::new(winit_window).unwrap();
591: 
592:                             self.world_mut().entity_mut(entity).insert(wrapper);
593:                         });
594:                     });
595:                 }
596:             }
597:         }
598: 
599:         // Notifies a lifecycle change
600:         if self.lifecycle != self.previous_lifecycle {
601:             self.previous_lifecycle = self.lifecycle;
602:             self.bevy_window_events.send(self.lifecycle);
603:         }
604: 
605:         // This is recorded before running app.update(), to run the next cycle after a correct timeout.
606:         // If the cycle takes more than the wait timeout, it will be re-executed immediately.
607:         let begin_frame_time = Instant::now();
608: 
609:         if should_update {
610:             let (_, windows) = focused_windows_state.get(self.world()).unwrap();
611:             // If no windows exist, this will evaluate to `true`.
612:             let all_invisible = windows.iter().all(|w| !w.1.visible);
613: 
614:             // Not redrawing, but the timeout elapsed.
615:             //
616:             // Additional condition for Windows OS.
617:             // If no windows are visible, redraw calls will never succeed, which results in no app update calls being performed.
618:             // This is a temporary solution, full solution is mentioned here: <REDACTED_URL>
619:             if !self.ran_update_since_last_redraw || all_invisible {
620:                 self.run_app_update();
621:                 #[cfg(feature = "custom_cursor")]
622:                 self.update_cursors(event_loop);
623:                 #[cfg(not(feature = "custom_cursor"))]
624:                 self.update_cursors();
625:                 self.ran_update_since_last_redraw = true;
626:             } else {
627:                 self.redraw_requested = true;
628:             }
629: 
630:             // Read RequestRedraw events that may have been sent during the update
631:             if let Some(app_redraw_events) = self.world().get_resource::<Messages<RequestRedraw>>()
632:                 && redraw_message_cursor
633:                     .read(app_redraw_events)
634:                     .last()
635:                     .is_some()
636:             {
637:                 self.redraw_requested = true;
638:             }
639: 
640:             // Running the app may have produced WindowCloseRequested events that should be processed
641:             if let Some(close_request_messages) = self
642:                 .world()
643:                 .get_resource::<Messages<WindowCloseRequested>>()
644:                 && close_message_cursor
645:                     .read(close_request_messages)
646:                     .last()
647:                     .is_some()
648:             {
649:                 self.redraw_requested = true;
650:             }

651: 
652:             // Running the app may have changed the WinitSettings resource, so we have to re-extract it.
653:             let (config, windows) = focused_windows_state.get(self.world()).unwrap();
654:             let focused = windows.iter().any(|(_, window)| window.focused);
655:             update_mode = config.update_mode(focused);
656:         }
657: 
658:         // The update mode could have been changed, so we need to redraw and force an update
659:         if update_mode != self.update_mode {
660:             // Trigger the next redraw since we're changing the update mode
661:             self.redraw_requested = true;
662:             // Consider the wait as elapsed since it could have been cancelled by a user event
663:             self.wait_elapsed = true;
664:             // reset the scheduled start time
665:             self.scheduled_tick_start = None;
666: 
667:             self.update_mode = update_mode;
668:         }
669: 
670:         match update_mode {
671:             UpdateMode::Continuous => {
672:                 // per winit's docs on [Window::is_visible](<REDACTED_URL>),
673:                 // we cannot use the visibility to drive rendering on these platforms
674:                 // so we cannot discern whether to beneficially use `Poll` or not?
675:                 cfg_select! {
676:                     not(any(
677:                         target_arch = "wasm32",
678:                         target_os = "android",
679:                         target_os = "ios",
680:                         all(target_os = "linux", any(feature = "x11", feature = "wayland"))
681:                     )) =>
682:                     {
683:                         let visible = WINIT_WINDOWS.with_borrow(|winit_windows| {
684:                             winit_windows.windows.iter().any(|(_, w)| {
685:                                 w.is_visible().unwrap_or(false)
686:                             })
687:                         });
688: 
689:                         event_loop.set_control_flow(if visible {
690:                             ControlFlow::Wait
691:                         } else {
692:                             ControlFlow::Poll
693:                         });
694:                     }
695:                     _ => {
696:                         event_loop.set_control_flow(ControlFlow::Wait);
697:                     }
698:                 }
699: 
700:                 // Trigger the next redraw to refresh the screen immediately if waiting
701:                 if let ControlFlow::Wait = event_loop.control_flow() {
702:                     self.redraw_requested = true;
703:                 }
704:             }
705:             UpdateMode::Reactive { wait, .. } => {
706:                 // Set the next timeout, starting from the instant we were scheduled to begin
707:                 if self.wait_elapsed {
708:                     self.redraw_requested = true;
709: 
710:                     let begin_instant = self.scheduled_tick_start.unwrap_or(begin_frame_time);
711:                     if let Some(next) = begin_instant.checked_add(wait) {
712:                         let now = Instant::now();
713:                         if next < now {
714:                             // request next redraw as soon as possible if we are already past the next scheduled frame start time
715:                             event_loop.set_control_flow(ControlFlow::Poll);
716:                             self.scheduled_tick_start = Some(now);
717:                         } else {
718:                             event_loop.set_control_flow(ControlFlow::WaitUntil(next));
719:                             self.scheduled_tick_start = Some(next);
720:                         }
721:                     }
722:                 }
723:             }
724:         }
725: 
726:         if self.redraw_requested && self.lifecycle != AppLifecycle::Suspended {
727:             WINIT_WINDOWS.with_borrow(|winit_windows| {
728:                 for window in winit_windows.windows.values() {
729:                     window.request_redraw();
730:                 }
731:             });
732:             self.redraw_requested = false;
733:         }
734: 
735:         if let Some(app_exit) = self.app.should_exit() {
736:             self.app_exit = Some(app_exit);
737: 
738:             event_loop.exit();
739:         }
740:     }
741: 
742:     fn should_update(&self, update_mode: UpdateMode) -> bool {
743:         let handle_event = match update_mode {
744:             UpdateMode::Continuous => {
745:                 self.wait_elapsed
746:                     || self.user_event_received
747:                     || self.window_event_received
748:                     || self.device_event_received
749:             }
750:             UpdateMode::Reactive {
751:                 react_to_device_events,
752:                 react_to_user_events,
753:                 react_to_window_events,
754:                 ..
755:             } => {
756:                 self.wait_elapsed
757:                     || (react_to_device_events && self.device_event_received)
758:                     || (react_to_user_events && self.user_event_received)
759:                     || (react_to_window_events && self.window_event_received)
760:             }
761:         };
762: 
763:         handle_event && self.lifecycle.is_active()
764:     }
765: 
766:     fn run_app_update(&mut self) {
767:         self.reset_on_update();
768: 
769:         self.forward_bevy_events();
770: 
771:         if self.app.plugins_state() == PluginsState::Cleaned {
772:             self.app.update();
773:         }
774:     }
