1185: fn require_open_recruitment_offer(
1186:     ctx: &ReducerContext,
1187:     party: &Party,
1188: ) -> Result<Option<RecruitmentOffer>, String> {
1189:     let Some(leader) = ctx.db.character().id().find(party.leader_id) else {
1190:         return Err("Recruiting party leader not found".into());
1191:     };
1192:     let offer = ctx
1193:         .db
1194:         .recruitment_offer()
1195:         .recruiting_party_id()
1196:         .find(&party.id);
1197:     let Some(mut offer) = offer else {
1198:         return if leader.temporary {
1199:             Err("NPC company has no recruitment authority".into())
1200:         } else {
1201:             Ok(None)
1202:         };
1203:     };
1204:     let now = crate::time::refresh_clock(ctx)?;
1205:     if offer.status != RecruitmentOfferStatus::Open {
1206:         return Err("This recruitment offer is no longer open".into());
1207:     }
1208:     let bindings_are_live =
1209:         recruitment_offer_bindings_are_live(ctx, &offer, now);
1210:     let refreshed = refreshed_recruitment_offer_status(
1211:         offer.status,
1212:         now,
1213:         offer.expires_at_minute,
1214:         bindings_are_live,
1215:     );
1216:     if refreshed != RecruitmentOfferStatus::Open {
1217:         // A valid generated offer remains Open-but-expired until settlement
1218:         // activity renews it in place. Persisting Expired here would strand
1219:         // its unique NPC/party identity and prevent that renewal.
1220:         if refreshed == RecruitmentOfferStatus::Closed {
1221:             offer.status = refreshed;
1222:             ctx.db.recruitment_offer().id_key().update(offer);
1223:         }
1224:         return Err(if refreshed == RecruitmentOfferStatus::Expired {
1225:             "This recruitment offer has expired".into()
1226:         } else {
1227:             "Recruiting company's advertised identity or presence is stale".into()
1228:         });
1229:     }
1230:     Ok(Some(offer))
1231: }
