1233: fn refreshed_recruitment_offer_status(
1234:     current: RecruitmentOfferStatus,
1235:     now: StrategicMinute,
1236:     expires_at: StrategicMinute,
1237:     bindings_are_live: bool,
1238: ) -> RecruitmentOfferStatus {
1239:     if current != RecruitmentOfferStatus::Open {
1240:         current
1241:     } else if !bindings_are_live {
1242:         RecruitmentOfferStatus::Closed
1243:     } else if now >= expires_at {
1244:         RecruitmentOfferStatus::Expired
1245:     } else {
1246:         RecruitmentOfferStatus::Open
1247:     }
1248: }
