1267: pub fn request_to_join_party(
1268:     ctx: &ReducerContext,
1269:     character_id: u64,
1270:     recruitment_role_id: u64,
1271: ) -> Result<(), String> {
1272:     require_strategic_character_authority(ctx, character_id)?;
1273:     crate::character::require_living_character(ctx, character_id)?;
1274:     let Some(character) = ctx.db.character().id().find(character_id) else {
1275:         return Err("Character not found".into());
1276:     };
1277:     let current_party_id = character.party_id.clone().ok_or("Character has no party")?;
1278:     let current_party = ctx
1279:         .db
1280:         .party_authority()
1281:         .id()
1282:         .find(&current_party_id)
1283:         .ok_or("Current party not found")?;
1284:     if current_party.leader_id != character_id {
1285:         return Err("Only a party leader may request a party merge".into());
1286:     }
1287:     if current_party.active_contract_id.is_some() {
1288:         return Err("Abandon the current quest before joining another party".into());
1289:     }
1290:     let role = ctx
1291:         .db
1292:         .party_recruitment_role()
1293:         .id()
1294:         .find(recruitment_role_id)
1295:         .ok_or("Recruitment role not found")?;
1296:     let party_id = role.party_id.clone();
1297:     let Some(party) = ctx.db.party_authority().id().find(&party_id) else {
1298:         return Err("Party not found".into());
1299:     };
1300:     if current_party_id == party_id {
1301:         return Err("Cannot join your own party".into());
1302:     }
1303:     if current_party.current_settlement_id.is_none()
1304:         || party.current_settlement_id.is_none()
1305:         || current_party.wilderness_canonical_anchor_minute.is_some()
1306:         || party.wilderness_canonical_anchor_minute.is_some()
1307:     {
1308:         return Err("Parties can merge only while synchronized at a settlement".into());
1309:     }
1310:     require_living_recruitment_target(ctx, &party)?;
1311:     require_open_recruitment_offer(ctx, &party)?;
1312:     if !crate::simulation::same_simulation_scope(ctx, character_id, party.leader_id) {
1313:         return Err("Simulation and ordinary parties cannot merge".into());
1314:     }
1315:     if current_party.current_settlement_id != party.current_settlement_id
1316:         || current_party.current_case_site_id != party.current_case_site_id
1317:     {
1318:         return Err("Parties must be in the same location to merge".into());
1319:     }
1320:     if role.quantity > 0 && filled_role_slots(ctx, role.id) >= role.quantity {
1321:         return Err("Recruitment role is full".into());
1322:     }
1323:     if ctx
1324:         .db
1325:         .party_join_request()
1326:         .character_id()
1327:         .filter(character_id)
1328:         .any(|request| request.recruitment_role_id == recruitment_role_id)
1329:     {
1330:         return Ok(());
1331:     }
1332:     let capabilities = crate::capability::refresh_character_capability(ctx, character_id)?;
1333:     ctx.db.party_join_request().insert(PartyJoinRequest {
1334:         id: 0,
1335:         party_id,
1336:         recruitment_role_id,
1337:         character_id,
1338:         meets_requirements: capabilities.meets(role_requirements(&role)),
1339:     });
1340:     Ok(())
1341: }
