104: fn available_item_micros(
105:     ctx: &ReducerContext,
106:     owner: u64,
107:     party_scope: bool,
108:     item_id: &str,
109:     settled: bool,
110: ) -> u32 {
111:     let total = if party_scope {
112:         ctx.db
113:             .character()
114:             .id()
115:             .find(owner)
116:             .and_then(|character| character.party_id)
117:             .map_or(0_u64, |party_id| {
118:                 ctx.db
119:                     .party_inventory_item()
120:                     .party_id()
121:                     .filter(&party_id)
122:                     .filter(|row| row.item_id == item_id)
123:                     .filter(|row| {
124:                         !crate::inventory_container::row_is_fireplace_rooted(
125:                             ctx,
126:                             CarriedInventoryScope::Party,
127:                             row.id,
128:                         )
129:                     })
130:                     .map(|row| {
131:                         u64::from(
132:                             crate::inventory_amount::party_fraction(ctx, row.id)
133:                                 .unwrap_or_default()
134:                                 .get(),
135:                         )
136:                     })
137:                     .sum()
138:             })
139:     } else {
140:         ctx.db
141:             .inventory_item()
142:             .character_id()
143:             .filter(owner)
144:             .filter(|row| row.item_id == item_id)
145:             .filter(|row| {
146:                 !crate::inventory_container::row_is_fireplace_rooted(
147:                     ctx,
148:                     CarriedInventoryScope::Personal,
149:                     row.id,
150:                 )
151:             })
152:             .map(|row| {
153:                 u64::from(
154:                     crate::inventory_amount::personal_fraction(ctx, row.id)
155:                         .unwrap_or_default()
156:                         .get(),
157:                 )
158:             })
159:             .sum()
160:     };
161:     let reserve = if settled {
162:         u64::from(target_for(ctx, owner, party_scope, item_id))
163:             .saturating_mul(u64::from(ConsumableFractionMicros::MICROS_PER_WHOLE))
164:     } else {
165:         0
166:     };
167:     u32::try_from(total.saturating_sub(reserve).min(u64::from(u32::MAX))).unwrap_or(u32::MAX)
168: }
