408: fn tavern_purchase(ctx: &ReducerContext, character_id: u64, target: u32) -> u32 {
409:     let Some(def) = ctx.db.item().id().find(TAVERN_DRINK_ITEM_ID.to_string()) else {
410:         return 0;
411:     };
412:     let each = ethanol_ml(properties(&def));
413:     let price = u64::from(def.base_value.unwrap_or(0));
414:     let mut bought = 0_u32;
415:     let units = adventuresim_core::alcohol::tavern_units_affordable(
416:         target,
417:         each,
418:         price,
419:         crate::item::personal_currency_total(ctx, character_id),
420:     );
421:     for _ in 0..units {
422:         // Affordability was computed from the same personal-only balance. Keep
423:         // the reducer transaction authoritative if inventory changed.
424:         if crate::item::consume_personal_currency(ctx, character_id, price).is_err() {
425:             break;
426:         }
427:         bought = bought.saturating_add(each);
428:     }
429:     bought
430: }
