432: pub fn process_rest_evenings(
433:     ctx: &ReducerContext,
434:     character_id: u64,
435:     start: StrategicMinute,
436:     end: StrategicMinute,
437:     settled: bool,
438: ) -> Result<(), String> {
439:     use crate::personality::Temperance;
440:     let temperament = crate::personality::personality_or_neutral(ctx, character_id).temperance;
441:     let temperance_score =
442:         crate::personality::personality_scores_or_neutral(ctx, character_id).temperance;
443:     if temperament == Temperance::Temperate {
444:         return Ok(());
445:     }
446:     let mut morale_changed = false;
447:     for evening in rest_evenings(start, end).map_err(str::to_string)? {
448:         let id = ledger_id(character_id, evening);
449:         if ctx
450:             .db
451:             .alcohol_consumption()
452:             .id()
453:             .find(&id)
454:             .is_some_and(|row| row.morale_evaluated)
455:         {
456:             continue;
457:         }
458:         let weekly_heavy =
459:             temperament == Temperance::Neutral && !had_recent_heavy(ctx, character_id, evening);
460:         let preference = match temperament {
461:             Temperance::Neutral => TemperancePreference::Neutral,
462:             Temperance::Temperate => TemperancePreference::Temperate,
463:             Temperance::Drunkard => TemperancePreference::Drunkard,
464:         };
465:         let had_recent_heavy = !weekly_heavy;
466:         let target = evening_target(preference, had_recent_heavy);
467:         let existing = ctx
468:             .db
469:             .alcohol_consumption()
470:             .id()
471:             .find(&id)
472:             .map_or(0, |row| row.ethanol_ml);
473:         let mut consumed = existing;
474:         if consumed < target {
475:             consumed = consumed.saturating_add(consume_for_ethanol(
476:                 ctx,
477:                 character_id,
478:                 target - consumed,
479:                 settled,
480:                 false,
481:             ));
482:         }
483:         if consumed < target
484:             && temperament == Temperance::Drunkard
485:             && current_morale(ctx, character_id) < LOW_MORALE_THRESHOLD
486:             && !ordinary_potable_exists(ctx, character_id)
487:         {
488:             consumed = consumed.saturating_add(consume_for_ethanol(
489:                 ctx,
490:                 character_id,
491:                 target - consumed,
492:                 settled,
493:                 true,
494:             ));
495:         }
496:         if settled && consumed < target {
497:             consumed =
498:                 consumed.saturating_add(tavern_purchase(ctx, character_id, target - consumed));
499:         }
500:         mark_evening_evaluated(ctx, character_id, evening, &id, consumed);
501:         let effect =
502:             nightly_morale_effect(evening, preference, had_recent_heavy, consumed >= target)
503:                 .ok_or("Alcohol morale effect unexpectedly absent")?;
504:         let neutral_effect = nightly_morale_effect(
505:             evening,
506:             TemperancePreference::Neutral,
507:             had_recent_heavy,
508:             consumed >= target,
509:         )
510:         .ok_or("Neutral alcohol morale effect unexpectedly absent")?;
511:         let magnitude = crate::personality::temperance_morale_magnitude(
512:             temperance_score,
513:             f32::from(neutral_effect.magnitude),
514:             consumed >= target,
515:         );
516:         crate::condition::upsert_refreshable_morale_event_at_without_refresh(
517:             ctx,
518:             character_id,
519:             effect.kind,
520:             magnitude,
521:             effect.occurred_at_minute,
522:             NIGHTLY_MORALE_SOURCE_ID,
523:         )?;
524:         morale_changed = true;
525:     }
526:     if morale_changed {
527:         crate::condition::refresh_character_strategic_condition(ctx, character_id)?;
528:     }
529:     Ok(())
530: }
