170: fn available_stacks(
171:     ctx: &ReducerContext,
172:     character_id: u64,
173:     settled: bool,
174:     allow_medical: bool,
175:     hydration: bool,
176: ) -> Vec<(Stack, crate::Item, ConsumableFractionMicros)> {
177:     let character = match ctx.db.character().id().find(character_id) {
178:         Some(row) => row,
179:         None => return Vec::new(),
180:     };
181:     let mut rows = Vec::new();
182:     if let Some(party_id) = character.party_id.as_ref()
183:         && let Some(party) = ctx.db.party_authority().id().find(party_id)
184:     {
185:         for stack in ctx.db.party_inventory_item().party_id().filter(party_id) {
186:             if crate::inventory_container::row_is_fireplace_rooted(
187:                 ctx,
188:                 CarriedInventoryScope::Party,
189:                 stack.id,
190:             ) {
191:                 continue;
192:             }
193:             if let Some(def) = ctx.db.item().id().find(&stack.item_id) {
194:                 let p = properties(&def);
195:                 if p.potable
196:                     && ethanol_ml(p) > 0
197:                     && (!hydration || emergency_hydration_ml(p) > 0)
198:                     && (allow_medical || !p.disinfectant_focused)
199:                     && available_item_micros(ctx, party.leader_id, true, &stack.item_id, settled)
200:                         > 0
201:                 {
202:                     let tagged = Stack::Party(stack);
203:                     let available_micros =
204:                         stack_fraction(ctx, &tagged)
205:                             .get()
206:                             .min(available_item_micros(
207:                                 ctx,
208:                                 party.leader_id,
209:                                 true,
210:                                 &def.id,
211:                                 settled,
212:                             ));
213:                     let available = ConsumableFractionMicros::try_new(available_micros)
214:                         .expect("available stack fraction cannot exceed one whole");
215:                     if !available.is_zero() {
216:                         rows.push((tagged, def, available));
217:                     }
218:                 }
219:             }
220:         }
221:     }
222:     for stack in ctx.db.inventory_item().character_id().filter(character_id) {
223:         if crate::inventory_container::row_is_fireplace_rooted(
224:             ctx,
225:             CarriedInventoryScope::Personal,
226:             stack.id,
227:         ) {
228:             continue;
229:         }
230:         if let Some(def) = ctx.db.item().id().find(&stack.item_id) {
231:             let p = properties(&def);
232:             if p.potable
233:                 && ethanol_ml(p) > 0
234:                 && (!hydration || emergency_hydration_ml(p) > 0)
235:                 && (allow_medical || !p.disinfectant_focused)
236:                 && available_item_micros(ctx, character_id, false, &stack.item_id, settled) > 0
237:             {
238:                 let tagged = Stack::Personal(stack);
239:                 let available_micros =
240:                     stack_fraction(ctx, &tagged)
241:                         .get()
242:                         .min(available_item_micros(
243:                             ctx,
244:                             character_id,
245:                             false,
246:                             &def.id,
247:                             settled,
248:                         ));
249:                 let available = ConsumableFractionMicros::try_new(available_micros)
250:                     .expect("available stack fraction cannot exceed one whole");
251:                 if !available.is_zero() {
252:                     rows.push((tagged, def, available));
253:                 }
254:             }
255:         }
256:     }
257:     rows.sort_by(|(a, ad, _), (b, bd, _)| {
258:         let scope = |s: &Stack| if matches!(s, Stack::Party(_)) { 0 } else { 1 };
259:         let id = |s: &Stack| match s {
260:             Stack::Party(x) => x.id,
261:             Stack::Personal(x) => x.id,
262:         };
263:         (
264:             scope(a),
265:             ad.alcohol_disinfectant_effectiveness,
266:             &ad.id,
267:             id(a),
268:         )
269:             .cmp(&(
270:                 scope(b),
271:                 bd.alcohol_disinfectant_effectiveness,
272:                 &bd.id,
273:                 id(b),
274:             ))
275:     });
276:     rows
277: }
278: 
279: fn consume_stack(
280:     ctx: &ReducerContext,
281:     stack: Stack,
282:     requested_fraction: ConsumableFractionMicros,
283: ) -> Result<ConsumableFractionMicros, String> {
284:     let (scope, row_id, available) = match &stack {
285:         Stack::Party(row) => (
286:             CarriedInventoryScope::Party,
287:             row.id,
288:             crate::inventory_amount::party_fraction(ctx, row.id),
289:         ),
290:         Stack::Personal(row) => (
291:             CarriedInventoryScope::Personal,
292:             row.id,
293:             crate::inventory_amount::personal_fraction(ctx, row.id),
294:         ),
295:     };
296:     crate::inventory_container::reconcile_consumed_row(ctx, scope, row_id, false)?;
297:     let consumed = match stack {
298:         Stack::Party(row) => {
299:             crate::inventory_amount::consume_party(ctx, row.id, requested_fraction)?
300:         }
301:         Stack::Personal(row) => {
302:             crate::inventory_amount::consume_personal(ctx, row.id, requested_fraction)?
303:         }
304:     };
305:     if available.is_some_and(|amount| consumed >= amount) {
306:         crate::inventory_container::reconcile_consumed_row(ctx, scope, row_id, true)?;
307:     }
308:     Ok(consumed)
309: }
310: 
311: fn consume_for_ethanol(
312:     ctx: &ReducerContext,
313:     character_id: u64,
314:     target: u32,
315:     settled: bool,
316:     allow_medical: bool,
317: ) -> u32 {
318:     let mut total = 0_u32;
319:     while total < target {
320:         let Some((stack, def, available)) =
321:             available_stacks(ctx, character_id, settled, allow_medical, false)
322:                 .into_iter()
323:                 .next()
324:         else {
325:             break;
326:         };
327:         let full_effect = ethanol_ml(properties(&def));
328:         let requested = ConsumableFractionMicros::try_from_ratio(
329:             u64::from(target - total),
330:             u64::from(full_effect),
331:         )
332:         .unwrap_or(ConsumableFractionMicros::WHOLE)
333:         .min(available);
334:         let consumed = consume_stack(ctx, stack, requested).unwrap_or_default();
335:         if consumed.is_zero() {
336:             break;
337:         }
338:         total = total.saturating_add(consumed.scale_floor(u64::from(full_effect)) as u32);
339:     }
340:     total
341: }
