198: impl Iterator for EveningIds {
199:     type Item = u64;
200: 
201:     fn next(&mut self) -> Option<Self::Item> {
202:         let last = self.last?;
203:         if self.next > last {
204:             self.last = None;
205:             return None;
206:         }
207:         let value = self.next;
208:         self.next = self.next.saturating_add(1);
209:         Some(value)
