213: fn checked_interval(start: StrategicMinute, end: StrategicMinute) -> Result<(), &'static str> {
214:     if end < start {
215:         return Err("Alcohol interval ends before it starts");
216:     }
217:     let elapsed = end.elapsed_since(start);
218:     if elapsed > MAX_ALCOHOL_INTERVAL_MINUTES {
219:         return Err("Alcohol interval cannot exceed one year");
220:     }
