242: #[derive(Clone, Debug)]
243: pub struct RestEvenings {
244:     next: u64,
245:     last: u64,
246:     start: StrategicMinute,
247:     end: StrategicMinute,
248: }
249: 
250: impl Iterator for RestEvenings {
251:     type Item = u64;
252: 
253:     fn next(&mut self) -> Option<Self::Item> {
254:         while self.next <= self.last {
255:             let evening = self.next;
256:             self.next = self.next.saturating_add(1);
257:             let boundary = evening_boundary(evening)?;
258:             let sleep_end = boundary
259:                 .day_start()
260:                 .checked_add_days(1)?
261:                 .checked_add_minutes(NIGHT_END_MINUTE)?;
262:             if self.start < sleep_end && self.end >= boundary {
263:                 return Some(evening);
264:             }
265:         }
266:         None
267:     }
268: }
269: 
270: /// Nightly opportunities overlapped by a rest interval. This includes the
271: /// current unprocessed evening for rests beginning after 18:00 or before 08:00.
272: pub fn rest_evenings(
273:     start: StrategicMinute,
274:     end: StrategicMinute,
275: ) -> Result<RestEvenings, &'static str> {
276:     checked_interval(start, end)?;
277:     let first = start.day_index().saturating_sub(1);
278:     let last = end.day_index();
279:     Ok(RestEvenings {
280:         next: first,
281:         last,
282:         start,
283:         end,
284:     })
285: }
