287: #[derive(Clone, Debug)]
288: pub struct TravelEveningSegments {
289:     cursor: StrategicMinute,
290:     end: StrategicMinute,
291: }
292: 
293: impl Iterator for TravelEveningSegments {
294:     type Item = (StrategicMinute, StrategicMinute, StrategicMinute);
295: 
296:     fn next(&mut self) -> Option<Self::Item> {
297:         if self.cursor >= self.end {
298:             return None;
299:         }
300:         let start = self.cursor;
301:         let end =
302:             next_evening_boundary_after(start).map_or(self.end, |boundary| boundary.min(self.end));
303:         self.cursor = end;
304:         Some((start, end, end.saturating_sub_minutes(1)))
305:     }
306: }
307: 
308: /// Travel need intervals split at evening boundaries so emergency servings
309: /// are attributed to the same nightly history independent of reducer chunking.

