24:       [24, [3, 6, 16], [8, 13, 29], 0.98, 22, 0],
25:     ];
26:     const right = stops.findIndex(([at]) => at >= hour);
27:     const left = Math.max(0, right - 1);
28:     const span = stops[right][0] - stops[left][0] || 1;
29:     const amount = (hour - stops[left][0]) / span;
30:     const daylight = hour >= 6 && hour < 18;
31:     const progress = daylight ? (hour - 6) / 12 : ((hour + 6) % 24) / 12;
32:     const arc = progress * 2 - 1;
33:     const glowX = 50 + 56 * Math.sign(arc) * Math.abs(arc) ** 1.45;
34:     const glowY = 10 + 54 * arc * arc;
35:     const twilight = Math.min(Math.abs(hour - 6), Math.abs(hour - 18));
36:     const glow = daylight
37:       ? (twilight < 2 ? "rgb(255 169 94 / 76%)" : "rgb(255 244 194 / 82%)")
38:       : "rgb(181 207 255 / 42%)";
39:     const building = stops[left][4] + (stops[right][4] - stops[left][4]) * amount;
40:     const light = Math.max(0, Math.min(1, (building - 22) / 60));
41:     const warmth = stops[left][5] + (stops[right][5] - stops[left][5]) * amount;
42:     return {
43:       low: rgb(mix(stops[left][1], stops[right][1], amount)),
44:       high: rgb(mix(stops[left][2], stops[right][2], amount)),
45:       stars: stops[left][3] + (stops[right][3] - stops[left][3]) * amount,
46:       building: Math.round(building),
47:       light,
48:       warmth,
49:       glowX,
50:       glowY,
51:       glow,
52:     };
53:   };
