62:     root.setProperty("--sky-glow-y", `${value.glowY}%`);
63:     root.setProperty("--star-opacity", value.stars.toFixed(2));
64:     root.setProperty("--building-light", `${value.building}%`);
65:     root.setProperty("--environment-light", value.light.toFixed(3));
66:     root.setProperty("--environment-warmth", value.warmth.toFixed(3));
67:     root.setProperty("--environment-tint", value.high);
68:     root.setProperty("--scene-atmosphere-opacity", ((0.3 - value.light * 0.22 + value.warmth * 0.05) * 0.65).toFixed(3));
69:   };
