1066:         );
1067:     }
1068:     if let Some(pack) = item.get("animation_pack")
1069:         && pack.as_str().is_none_or(|pack| !valid_id(pack))
1070:     {
1071:         errors.push(
1072:             format!("{path}.animation_pack"),
1073:             "must be a safe lowercase animation pack ID",
1074:         );
1075:     }
1076:     for field in ["reach_m", "moment_of_inertia_kg_m2"] {
1077:         finite_in(item, field, 0.0, 10_000.0, path, errors);
1078:     }
