15: enum TerminalLifecycle {
16:     #[default]
17:     Running,
18:     RetryScheduled {
19:         frozen: FrozenTerminal,
20:         not_before: Duration,
21:     },
22:     Submitting {
23:         frozen: FrozenTerminal,
24:         ack_deadline: Duration,
25:     },
26:     TransportFailed,
27:     Presenting {
28:         outcome: TacticalOutcome,
29:         remaining: Duration,
30:     },
31:     Finished {
32:         outcome: TacticalOutcome,
33:     },
34: }
35: 
36: impl TerminalLifecycle {
37:     pub(crate) fn is_running(&self) -> bool {
38:         matches!(self, Self::Running)
39:     }
40: 
41:     pub(crate) fn begin(
42:         &mut self,
43:         frozen: FrozenTerminal,
44:         now: Duration,
45:         ack_timeout: Duration,
46:     ) -> Option<FrozenTerminal> {
47:         if !self.is_running() {
48:             return None;
49:         }
50:         let submission = frozen.clone();
51:         *self = Self::Submitting {
52:             frozen,
53:             ack_deadline: now.saturating_add(ack_timeout),
54:         };
55:         Some(submission)
56:     }
57: 
58:     pub(crate) fn retry_due(
59:         &mut self,
60:         now: Duration,
61:         ack_timeout: Duration,
62:     ) -> Option<FrozenTerminal> {
63:         let Self::RetryScheduled { frozen, not_before } = self else {
64:             return None;
65:         };
66:         if now < *not_before {
67:             return None;
68:         }
69:         let frozen = frozen.clone();
70:         let submission = frozen.clone();
71:         *self = Self::Submitting {
72:             frozen,
73:             ack_deadline: now.saturating_add(ack_timeout),
74:         };
75:         Some(submission)
76:     }
77: 
78:     pub(crate) fn enqueue_failed(&mut self, now: Duration, retry_backoff: Duration) {
79:         let Self::Submitting { frozen, .. } = self else {
80:             return;
81:         };
82:         let frozen = frozen.clone();
83:         *self = Self::RetryScheduled {
84:             frozen,
85:             not_before: now.saturating_add(retry_backoff),
86:         };
87:     }
88: 
89:     pub(crate) fn apply_submission_result(
90:         &mut self,
91:         result: TerminalSubmissionResult,
92:         now: Duration,
93:         retry_backoff: Duration,
94:         presentation_delay: Duration,
95:     ) -> Option<TacticalOutcome> {
96:         let Self::Submitting { frozen, .. } = self else {
97:             return None;
98:         };
99:         match result {
100:             TerminalSubmissionResult::Accepted => {
101:                 let outcome = presentation_outcome(frozen.resolution);
102:                 *self = Self::Presenting {
103:                     outcome,
104:                     remaining: presentation_delay,
105:                 };
106:                 Some(outcome)
107:             }
108:             TerminalSubmissionResult::Rejected(_) => {
109:                 let frozen = frozen.clone();
110:                 *self = Self::RetryScheduled {
111:                     frozen,
112:                     not_before: now.saturating_add(retry_backoff),
113:                 };
114:                 None
115:             }
116:         }
117:     }
118: 
119:     pub(crate) fn fail_if_ack_stalled(&mut self, now: Duration) -> bool {
120:         let stalled = matches!(
121:             self,
122:             Self::Submitting { ack_deadline, .. } if now >= *ack_deadline
123:         );
124:         if stalled {
125:             *self = Self::TransportFailed;
126:         }
127:         stalled
128:     }
129: 
130:     pub(crate) fn advance_presentation(&mut self, delta: Duration) -> Option<TacticalOutcome> {
131:         let Self::Presenting { outcome, remaining } = self else {
132:             return None;
133:         };
134:         *remaining = remaining.saturating_sub(delta);
135:         if !remaining.is_zero() {
136:             return None;
137:         }
138:         let outcome = *outcome;
139:         *self = Self::Finished { outcome };
140:         Some(outcome)
141:     }
142: }
