26: /// A SpacetimeDB connection whose initial identity handshake has completed.
27: ///
28: /// `DbConnection::build` returns before the SDK necessarily receives this
29: /// identity. Systems which invoke reducers with the server identity must wait
30: /// for this resource instead of calling the SDK's panicking `identity()` API.
31: #[derive(Resource, Debug, Clone, Copy)]
32: pub struct SpacetimeDbReady {
33:     identity: Identity,
34: }
35: 
36: impl SpacetimeDbReady {
37:     /// Identity assigned to this tactical server connection.
38:     pub fn identity(self) -> Identity {
39:         self.identity
40:     }
41: }
42: 
43: /// Connection to SpacetimeDB.
44: ///
45: /// SDK callbacks never touch the Bevy world � they only push rows into a
46: /// mailbox, which ordinary systems drain on their own schedule.
47: #[derive(Resource)]
48: pub struct SpacetimeDb {
49:     conn: DbConnection,
50:     connected_players: Arc<Mutex<Vec<ConnectedPlayer>>>,
51:     terminal_results: Arc<Mutex<Vec<TerminalSubmissionResult>>>,
52: }
53: 
54: #[derive(Clone, Debug, PartialEq, Eq)]
55: pub(crate) enum TerminalSubmissionResult {
56:     Accepted,
57:     Rejected(String),
58: }
59: 
60: impl SpacetimeDb {
61:     /// Access spacetime db reducers.
62:     pub fn reducers(&self) -> &RemoteReducers {
63:         &self.conn.reducers
64:     }
65: 
66:     /// Subscribe to `connected_players` and start collecting inserted rows.
67:     ///
68:     /// For native subscriptions, see: <REDACTED_URL>
69:     pub fn subscribe_connected_players(&self) -> SubscriptionHandle {
70:         // This is the callback handler. Standard Arc<Mutex<>> pattern for sharing state between threads.
71:         let connected_players = self.connected_players.clone();
72:         self.conn
73:             .db
74:             .connected_players()
75:             .on_insert(move |_ctx, row| {
76:                 connected_players.lock().unwrap().push(row.clone());
77:             });
78: 
79:         self.conn
80:             .subscription_builder()
81:             .on_error(|ctx, error| {
82:                 error!(
83:                     "SpacetimeDB subscription failed: {error} (event: {:?})",
84:                     ctx.event
85:                 );
86:             })
87:             .add_query(|query| query.from.connected_players())
88:             .subscribe()
89:     }
90: 
91:     /// Take every `connected_players` row inserted since the last call.
92:     pub fn take_connected_players(&self) -> Vec<ConnectedPlayer> {
93:         std::mem::take(&mut *self.connected_players.lock().unwrap())
94:     }
95: 
96:     /// Queue a terminal reducer and mailbox its eventual nested callback
97:     /// result. Queue success is not reducer acceptance.
98:     pub fn submit_terminal(
99:         &self,
100:         resolution: TacticalMissionResolution,
101:         receipt: TacticalConsequenceReceipt,
102:     ) -> spacetimedb_sdk::Result<()> {
103:         let terminal_results = self.terminal_results.clone();
104:         self.conn
105:             .reducers
106:             .end_tactical_server_then(resolution, receipt, move |_, result| {
107:                 let result = match result {
108:                     Ok(Ok(())) => TerminalSubmissionResult::Accepted,
109:                     Ok(Err(error)) => TerminalSubmissionResult::Rejected(error),
110:                     Err(error) => TerminalSubmissionResult::Rejected(format!(
111:                         "internal reducer callback error: {error:?}"
112:                     )),
113:                 };
114:                 terminal_results.lock().unwrap().push(result);
115:             })
116:     }
117: 
118:     pub(crate) fn take_terminal_results(&self) -> Vec<TerminalSubmissionResult> {
119:         std::mem::take(&mut *self.terminal_results.lock().unwrap())
120:     }
121: }
122: 
123: /// Pump the connection; SDK callbacks fire here and fill the mailboxes.
124: pub fn update_spacetimedb(stdb: Res<SpacetimeDb>) -> Result {
125:     stdb.conn.frame_tick()?;
126:     Ok(())
127: }
128: 
129: /// Publish readiness only after `frame_tick` receives the initial identity.
130: fn publish_spacetimedb_ready(
131:     mut commands: Commands,
132:     stdb: Res<SpacetimeDb>,
133:     ready: Option<Res<SpacetimeDbReady>>,
134: ) {
135:     if ready.is_some() {
136:         return;
137:     }
138: 
139:     let Some(identity) = stdb.conn.try_identity() else {
140:         return;
141:     };
142: 
143:     info!("SpacetimeDB connection is ready: {identity}");
144:     commands.insert_resource(SpacetimeDbReady { identity });
145: }
146: 
147: /// On app exit, close the connection cleanly.
148: fn disconnect_spacetimedb(mut exit: MessageReader<AppExit>, stdb: Res<SpacetimeDb>) {
149:     if exit.read().next().is_none() {
150:         return;
151:     }
152: 
153:     info!("Disconnecting from SpacetimeDB...");
154:     if stdb.conn.disconnect().is_ok() {
155:         // `disconnect` only queues the close; pump until the stream ends so
156:         // queued reducer calls (e.g. mission results) reach the server first.
157:         while stdb.conn.advance_one_message_blocking().is_ok() {}
158:     }
159: }
160: 
161: fn connect_spacetimedb(mut commands: Commands, args: Res<Args>) -> Result {
162:     info!("Connecting to SpacetimeDB: {}", args.spacetimedb_url);
163:     let conn = DbConnection::builder()
164:         .with_uri(&args.spacetimedb_url)
165:         .with_database_name(&args.spacetimedb_module)
166:         .on_connect(move |_, i, _| {
167:             info!("SpacetimeDB connected: {i}");
168:         })
169:         .on_connect_error(|_, err| {
170:             error!("SpacetimeDB connection failed: {err}");
171:             // A mission server without its database is useless;
172:             // die and let the orchestrator deal with it.
173:             std::process::exit(1);
174:         })
175:         .on_disconnect(|_, err| {
176:             if let Some(err) = err {
177:                 warn!("SpacetimeDB disconnected: {err}")
178:             } else {
179:                 warn!("SpacetimeDB disconnected: no error")
180:             }
181:         })
182:         .build()?;
183: 
184:     commands.insert_resource(SpacetimeDb {
185:         conn,
186:         connected_players: default(),
187:         terminal_results: default(),
188:     });
189: 
190:     Ok(())
191: }

