1: //! The non-linear pose-corrective network.
2: //!
3: //! Joint rotations are turned into a 6D rotation feature per joint, pushed
4: //! through a sparse 750 -> 3000 layer, a ReLU, and a dense 3000 -> `3 * V`
5: //! layer, giving a per-vertex offset applied before skinning.
6: 
7: use std::path::Path;
8: 
9: use anyhow::Result;
10: use burn::tensor::{Device, Tensor, activation};
11: use fabelgeist_numpy_storage::NpyDimension;
12: use fabelgeist_rig::RigJointCount;
13: 
14: use crate::character::MeshVertexCount;
15: 
16: pub use archive::CorrectiveArchiveBytes;
17: use archive::CorrectiveArchives;
18: use import::{CorrectiveBasis, CorrectiveLayout};
19: pub use import::{
20:     CorrectiveExtent, CorrectiveFeatureIndex, CorrectiveHiddenIndex, CorrectiveImportError,
21: };
22: pub use input::CorrectiveForwardError;
23: use input::CorrectiveInput;
24: 
25: mod archive;
26: mod import;
27: mod input;
28: 
29: /// The first two joints do not define a local pose, so they carry no feature.
30: pub const SKIPPED_JOINTS: NpyDimension = NpyDimension::new(2);
31: 
32: pub struct PoseCorrectives {
33:     /// Sparse activation layer, densified and transposed: `[posed * 6, hidden]`.
34:     activation: Tensor<2>,
35:     /// Corrective basis: `[hidden, vertices * 3]`.
36:     basis: Tensor<2>,
37:     layout: CorrectiveLayout,
38: }
39: 
40: impl PoseCorrectives {
41:     /// Loads the corrective network for one level of detail, or `None` when the
42:     /// LOD ships no corrective basis.
43:     ///
44:     /// `activation_path` holds the sparse mask and weights shared by every LOD;
45:     /// `basis_path` holds this LOD's corrective basis.
46:     pub fn load(
47:         activation_path: &Path,
48:         basis_path: &Path,
49:         num_joints: RigJointCount,
50:         num_vertices: MeshVertexCount,
51:         device: &Device,
52:     ) -> Result<Option<Self>> {
53:         Self::from_archives(
54:             CorrectiveArchives::open(activation_path, basis_path)?,
55:             num_joints,
56:             num_vertices,
57:             device,
58:         )
59:     }
60: 
61:     /// Loads corrective archives already held in memory (for web/streamed assets).
62:     pub fn from_bytes(
63:         archives: CorrectiveArchiveBytes,
64:         num_joints: RigJointCount,
65:         num_vertices: MeshVertexCount,
66:         device: &Device,
67:     ) -> Result<Option<Self>> {
68:         Self::from_archives(
69:             CorrectiveArchives::from_bytes(archives)?,
70:             num_joints,
71:             num_vertices,
72:             device,
73:         )
74:     }
75: 
76:     fn from_archives(
77:         archives: CorrectiveArchives,
78:         num_joints: RigJointCount,
79:         num_vertices: MeshVertexCount,
80:         device: &Device,
81:     ) -> Result<Option<Self>> {
82:         let Some(array) = archives.basis()? else {
83:             return Ok(None);
84:         };
85:         let basis = CorrectiveBasis::new(array, num_joints, num_vertices)?;
86:         let activation = archives.activation(basis.layout())?.into_tensor(device);
87:         let tensor = basis.to_tensor(device)?;
88:         Ok(Some(Self {
89:             activation,
90:             basis: tensor,
91:             layout: basis.into_layout(),
92:         }))
93:     }
94: 
95:     pub fn num_vertices(&self) -> MeshVertexCount {
96:         self.layout.vertices()
97:     }
98: 
99:     /// Per-vertex corrective offsets `[batch, vertices, 3]`, from joint
100:     /// parameters in the model's seven-channel order. Joint count and channel
101:     /// width must match the admitted network before any tensor operation.
102:     /// Batch-dependent products remain fallible layout admissions.
103:     pub fn forward(
104:         &self,
105:         joint_parameters: Tensor<3>,
106:     ) -> std::result::Result<Tensor<3>, CorrectiveForwardError> {
107:         let input = CorrectiveInput::new(joint_parameters, &self.layout)?;
108:         let output_dimensions = input.output_dimensions()?;
109:         let features = input.into_features()?;
110:         let hidden = activation::relu(features.matmul(self.activation.clone()));
111:         Ok(hidden.matmul(self.basis.clone()).reshape(output_dimensions))
112:     }
113: }
