1: //! Native IEEE word decoding and encoding for independent solver snapshots.
2: use fabelgeist_math::Vec3;
3: use serde_json::Value;
4: 
5: pub(crate) fn decode_native_vectors(value: &Value) -> Vec<Vec3> {
6:     let mut vectors = Vec::new();
7:     for words in value.as_array().expect("native vector records") {
8:         let x = f32::from_bits(words[0].as_u64().expect("x word") as u32);
9:         let y = f32::from_bits(words[1].as_u64().expect("y word") as u32);
10:         let z = f32::from_bits(words[2].as_u64().expect("z word") as u32);
11:         vectors.push(Vec3::new(x, y, z));
12:     }
13:     vectors
14: }
15: pub(crate) fn encode_native_vectors(vectors: &[Vec3]) -> Value {
16:     let mut records = Vec::new();
17:     for vector in vectors {
18:         records.push([vector.x.to_bits(), vector.y.to_bits(), vector.z.to_bits()]);
19:     }
20:     serde_json::json!(records)
21: }

