1: //! Conservative advancement for linearly moving thick cloth primitives.
2: //!
3: //! Bound distance decrease by the maximum relative vertex displacement.
4: //! Each advance is shorter than (distance - clearance) / that bound, so it
5: //! cannot step over contact. Exhausting the iteration budget returns the last
6: //! safe time; it must never be interpreted as "no collision".
7: //! See <REDACTED_URL> (additive conservative advancement).
8: use fabelgeist_math::Vec3;
9: use fabelgeist_xpbd::ConstraintGradient;
10: 
11: #[derive(Clone, Copy, Debug)]
12: pub(crate) enum Pair {
13:     VertexTriangle,
14:     EdgeEdge,
15: }
16: 
17: #[derive(Clone, Copy, Debug)]
18: pub(crate) struct Contact {
19:     /// A conservative lower bound for the first contact, in [0, 1].
20:     pub time: f64,
21:     pub weights: [ConstraintGradient; 4],
22:     pub normal: Vec3,
23:     pub distance: f64,
24: }
25: 
26: type V = [f64; 3];
27: fn add(a: V, b: V) -> V {
28:     std::array::from_fn(|i| a[i] + b[i])
29: }
30: fn sub(a: V, b: V) -> V {
100: fn edges(a: V, b: V, c: V, d: V) -> (f64, f64) {
101:     let (u, v, r) = (sub(b, a), sub(d, c), sub(a, c));
102:     let (aa, bb, cc, dd, ee) = (dot(u, u), dot(u, v), dot(v, v), dot(u, r), dot(v, r));
103:     if aa == 0.0 && cc == 0.0 {
104:         return (0.0, 0.0);
105:     }
106:     if aa == 0.0 {
107:         return (0.0, (ee / cc).clamp(0.0, 1.0));
108:     }
109:     if cc == 0.0 {
110:         return ((-dd / aa).clamp(0.0, 1.0), 0.0);
111:     }
112:     let determinant = norm(cross(u, v)).powi(2);
113:     let mut s = if determinant > 1e-28 * aa * cc {
114:         ((bb * ee - cc * dd) / determinant).clamp(0.0, 1.0)
115:     } else {
116:         0.0
117:     };
118:     let mut t = (bb * s + ee) / cc;
119:     if t < 0.0 {
120:         t = 0.0;
121:         s = (-dd / aa).clamp(0.0, 1.0);
122:     } else if t > 1.0 {
123:         t = 1.0;
124:         s = ((bb - dd) / aa).clamp(0.0, 1.0);
125:     }
126:     (s, t)
127: }
128: 
129: fn sample(pair: Pair, p: [V; 4], time: f64, fallback: V) -> Contact {
130:     let weights = match pair {
131:         Pair::VertexTriangle => {
132:             let (_, bary) = triangle(p[0], p[1], p[2], p[3]);
133:             [1.0, -bary[0], -bary[1], -bary[2]]
134:         }
135:         Pair::EdgeEdge => {
136:             let (s, t) = edges(p[0], p[1], p[2], p[3]);
137:             [1.0 - s, s, -(1.0 - t), -t]
138:         }
139:     };
140:     let delta = (0..4).fold([0.0; 3], |sum, i| add(sum, mul(p[i], weights[i])));
141:     let distance = norm(delta);
142:     let direction = if distance > 1e-15 {
143:         mul(delta, 1.0 / distance)
144:     } else if norm(fallback) > 1e-15 {
145:         mul(fallback, 1.0 / norm(fallback))
146:     } else {
147:         let n = match pair {
148:             Pair::VertexTriangle => cross(sub(p[2], p[1]), sub(p[3], p[1])),
149:             Pair::EdgeEdge => cross(sub(p[1], p[0]), sub(p[3], p[2])),
150:         };
151:         if norm(n) > 1e-15 {
152:             mul(n, 1.0 / norm(n))
153:         } else {
154:             [1.0, 0.0, 0.0]
155:         }
156:     };
157:     Contact {
158:         time,
159:         weights: weights.map(ConstraintGradient::from),
160:         normal: Vec3::new(
161:             direction[0] as f32,
162:             direction[1] as f32,
163:             direction[2] as f32,
164:         ),
165:         distance,

