71: impl CoreLoopConfig {
72:     pub fn validate(&self) -> Result<(), String> {
73:         const MAX_DURATION_YEARS: u32 = 100;
74:         const MAX_DURATION_DAYS: u32 =
75:             adventuresim_world_schema::calendar::DAYS_PER_YEAR as u32 * MAX_DURATION_YEARS;
76: 
77:         validate_loopback_url(&self.host)?;
78:         if !self.database.starts_with("adventuresim-sim-")
79:             || !self
80:                 .database
81:                 .bytes()
82:                 .all(|b| b.is_ascii_alphanumeric() || b == b'-')
83:         {
84:             return Err("database must be a unique adventuresim-sim-* disposable name".into());
85:         }
86:         if !(2..=32).contains(&self.population)
87:             || !(1..=10_000).contains(&self.cycles)
88:             || !(1..=MAX_DURATION_DAYS).contains(&self.duration_days)
89:             || !(2..=8).contains(&self.party_size)
90:             || self.party_size > self.population
91:         {
92:             return Err(format!(
93:                 "population 2..=32, party_size 2..=8, cycles 1..=10000, and duration_days 1..={MAX_DURATION_DAYS} are required"
94:             ));
95:         }
96:         let work = u64::from(self.population)
97:             .checked_mul(u64::from(self.cycles))
98:             .ok_or("core-loop work overflow")?;
99:         if work > MAX_CORE_LOOP_WORK {
100:             return Err(format!(
101:                 "population * cycles must be <= {MAX_CORE_LOOP_WORK}"
102:             ));
103:         }
104:         if !(16..=96).contains(&self.run_nonce.len())
105:             || !self
106:                 .run_nonce
107:                 .bytes()
108:                 .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
109:         {
110:             return Err("run_nonce must be 16..=96 ASCII alphanumeric/dash characters".into());
111:         }
112:         if !SIMULATION_DISEASE_SCENARIOS.contains(&self.fixture_disease.as_str()) {
113:             return Err(format!(
114:                 "fixture_disease must be one of {}",
115:                 SIMULATION_DISEASE_SCENARIOS.join(", ")
116:             ));
117:         }
118:         if self.use_imported_world {
119:             if self.require_quest_coverage {
120:                 return Err("quest coverage fixture cannot use an imported world".into());
121:             }
122:             let digest = self
123:                 .expected_world_manifest_digest
124:                 .as_deref()
125:                 .ok_or("imported-world mode requires an expected manifest digest")?;
126:             if digest.len() != 64
127:                 || !digest
128:                     .bytes()
129:                     .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
130:             {
131:                 return Err("expected world manifest digest must be 64 lowercase hex".into());
132:             }
133:         } else if self.expected_world_manifest_digest.is_some() {
134:             return Err("fixture mode cannot claim an expected world manifest".into());
135:         }
136:         if self.require_quest_coverage && self.population <= self.party_size {
137:             return Err("quest coverage fixture requires at least two parties".into());
138:         }
139:         Ok(())
140:     }
141: }
