65: /// HTTP client for SpacetimeDB
193:     pub async fn call(&self, reducer: &str, args: &[Value]) -> Result<()> {
194:         let url = format!(
195:             "{}/v1/database/{}/call/{}",
196:             self.base_url, self.database, reducer
197:         );
198: 
199:         let mut request = self.http.post(&url).json(args);
200: 
201:         if let Some(token) = &self.token {
202:             request = request.header("Authorization", format!("Bearer {}", token));
203:         }
204: 
205:         let started = Instant::now();
206:         let response = request.send().await;
207:         let elapsed = started.elapsed();
208:         if elapsed >= Duration::from_millis(250) {
209:             tracing::warn!(?elapsed, reducer, "slow SpacetimeDB reducer call");
210:         }
211:         let response = response?;
212: 
213:         if !response.status().is_success() {
214:             let error_text = response.text().await.unwrap_or_default();
215:             return Err(SpacetimeError::Spacetime(error_text));
216:         }
217: 
218:         Ok(())
219:     }
220: }
