112: pub(crate) fn process_terminal_submission_results(
113:     time: Res<Time>,
114:     conn: Res<SpacetimeDb>,
115:     mut state: ResMut<MissionState>,
116:     mut cmd: Commands,
117: ) {
118:     for result in conn.take_terminal_results() {
119:         let rejection = match &result {
120:             TerminalSubmissionResult::Rejected(error) => Some(error.clone()),
121:             TerminalSubmissionResult::Accepted => None,
122:         };
123:         if let Some(outcome) = state.apply_terminal_submission_result(
124:             result,
125:             time.elapsed(),
126:             TERMINAL_RETRY_BACKOFF,
127:             TERMINAL_PRESENTATION_DELAY,
128:         ) {
129:             cmd.server_trigger(ToClients {
130:                 targets: SendTargets::All,
131:                 message: TacticalOutcomeResponse { outcome },
132:             });
133:             info!(
134:                 ?outcome,
135:                 "Mission terminal result accepted; presenting outcome"
136:             );
137:         } else if let Some(error) = rejection {
138:             warn!(
139:                 "Terminal reducer rejected submission; retrying in {}s: {error}",
140:                 TERMINAL_RETRY_BACKOFF.as_secs()
141:             );
142:         }
143:     }
144: }
