86:     positions: &[Vec3],
87:     values: &[f32],
88: ) -> TerrainRecipeResult<(Vec<Vec3>, Vec<u32>)> {
89:     let sample_id = |x: usize, y: usize, z: usize| (z * dimensions[1] + y) * dimensions[0] + x;
90:     let mut mesh_positions = Vec::new();
91:     let mut indices = Vec::new();
92:     let mut edge_vertices = HashMap::new();
93:     let sample_at = |index| LatticeSample {
94:         position: positions[index],
95:         value: values[index],
96:     };
97:     for z in 0..dimensions[2] - 1 {
98:         for y in 0..dimensions[1] - 1 {
99:             for x in 0..dimensions[0] - 1 {
100:                 let cube =
101:                     CUBE.map(|offset| sample_id(x + offset[0], y + offset[1], z + offset[2]));
102:                 // Uniform cells contribute no surface. Keep the same <= zero
103:                 // classification, including snapped lattice endpoints, and
104:                 // preserve the visitation order of every mixed cell.
105:                 // Trimming reference: <REDACTED_URL>
106:                 let solid = values[cube[0]] <= 0.0;
107:                 if cube.iter().all(|&index| (values[index] <= 0.0) == solid) {
108:                     continue;
109:                 }
110:                 for tet in TETS {
111:                     emit_tetrahedron(
112:                         tet.map(|corner| cube[corner]),
113:                         &sample_at,
114:                         &mut edge_vertices,
115:                         &mut mesh_positions,
116:                         &mut indices,
117:                     )?;
118:                 }
119:             }
120:         }
121:     }
122:     Ok((mesh_positions, indices))
123: }
124: 
125: fn emit_tetrahedron(
126:     vertices: [usize; 4],
127:     sample_at: &impl Fn(usize) -> LatticeSample,
128:     edge_vertices: &mut HashMap<(usize, usize), u32>,
129:     mesh_positions: &mut Vec<Vec3>,
130:     indices: &mut Vec<u32>,
131: ) -> TerrainRecipeResult<()> {
132:     let mut inside = [0; 4];
133:     let mut outside = [0; 4];
134:     let mut inside_count = 0;
135:     let mut outside_count = 0;
136:     for index in vertices {
137:         if sample_at(index).value <= 0.0 {
138:             inside[inside_count] = index;
139:             inside_count += 1;
140:         } else {
141:             outside[outside_count] = index;
142:             outside_count += 1;
143:         }
144:     }
145:     let inside = &inside[..inside_count];
146:     let outside = &outside[..outside_count];
147:     let first_triangle = indices.len();
148:     let mut vertex = |a, b| vertex_on_edge(a, b, sample_at, edge_vertices, mesh_positions);
149:     match (inside.len(), outside.len()) {
150:         (1, 3) => {
151:             for &b in outside {
152:                 indices.push(vertex(inside[0], b)?);
153:             }
154:         }
155:         (3, 1) => {
156:             let triangle = [
157:                 vertex(inside[0], outside[0])?,
158:                 vertex(inside[1], outside[0])?,
159:                 vertex(inside[2], outside[0])?,
160:             ];
161:             indices.extend([triangle[0], triangle[2], triangle[1]]);
162:         }
163:         (2, 2) => {
164:             let ac = vertex(inside[0], outside[0])?;
165:             let ad = vertex(inside[0], outside[1])?;
166:             let bc = vertex(inside[1], outside[0])?;
167:             let bd = vertex(inside[1], outside[1])?;
168:             indices.extend([ac, bc, ad, ad, bc, bd]);
169:         }
170:         _ => {}
171:     }
172:     if let (Some(&solid), Some(&empty)) = (inside.first(), outside.first()) {
173:         // The extracted surface is linear within this tetrahedron. Its normal
174:         // must face from the solid sample toward the empty sample. A gradient
175:         // of the original nonlinear field at a triangle centre can face the
176:         // other way at a cusp, breaking winding across shared edges.
177:         let outward = sample_at(empty).position.as_dvec3() - sample_at(solid).position.as_dvec3();
178:         for triangle in indices[first_triangle..].as_chunks_mut::<3>().0 {
179:             let [a, b, c] = [triangle[0], triangle[1], triangle[2]]
180:                 .map(|index| mesh_positions[index as usize].as_dvec3());
181:             if (b - a).cross(c - a).dot(outward) < 0.0 {
182:                 triangle.swap(1, 2);
183:             }
184:         }
185:     }
186:     Ok(())
187: }
188: 
189: fn vertex_on_edge(
190:     a: usize,
191:     b: usize,
192:     sample_at: &impl Fn(usize) -> LatticeSample,
193:     edge_vertices: &mut HashMap<(usize, usize), u32>,
194:     mesh_positions: &mut Vec<Vec3>,
195: ) -> TerrainRecipeResult<u32> {
196:     // Several tetrahedra can reach the same zero-valued lattice vertex along
197:     // different edges. Give that endpoint one identity to preserve topology.
198:     let start = sample_at(a);
199:     let end = sample_at(b);
200:     let key = if start.value == 0.0 {
201:         (a, a)
202:     } else if end.value == 0.0 {
203:         (b, b)
204:     } else if a < b {
205:         (a, b)
206:     } else {
207:         (b, a)
208:     };
209:     if let Some(&index) = edge_vertices.get(&key) {
210:         return Ok(index);
211:     }
212:     let denominator = start.value - end.value;
213:     let fraction = if denominator.abs() < 1e-7 {
214:         0.5
215:     } else {
216:         start.value / denominator
217:     }
218:     .clamp(0.0, 1.0);
219:     let index =
220:         u32::try_from(mesh_positions.len()).map_err(|_| TerrainRecipeError::VertexCountOverflow)?;
221:     mesh_positions.push(start.position.lerp(end.position, fraction));
222:     edge_vertices.insert(key, index);
223:     Ok(index)
224: }
225: 
226: fn snap_field_zero(value: f32) -> f32 {
227:     if value.abs() <= FIELD_ZERO_TOLERANCE_METRES {
228:         0.0
229:     } else {
230:         value
231:     }
232: }
233: 
234: fn build_surface(
235:     mesh_positions: Vec<Vec3>,
236:     indices: Vec<u32>,
237:     transition_collar: TerrainTransitionCollar,
238: ) -> TerrainRecipeResult<SceneTerrainPatch> {
239:     let oriented = indices
240:         .par_chunks_exact(3)
241:         .map(|source| triangle_normal(source, &mesh_positions))
242:         .collect::<Vec<_>>();
243:     let mut normals = vec![Vec3::ZERO; mesh_positions.len()];
244:     let mut oriented_indices = Vec::with_capacity(indices.len());
245:     for (triangle, normal) in oriented.into_iter().flatten() {
246:         for &index in &triangle {
247:             normals[index as usize] += normal;
248:         }
249:         oriented_indices.extend(triangle);
250:     }
251:     if oriented_indices.is_empty() {
252:         return Err(TerrainRecipeError::EmptySurface);
253:     }
254:     SceneTerrainPatch::from_mesh_buffers(
255:         transition_collar,
256:         mesh_positions
257:             .into_iter()
258:             .map(|position| position.to_array())
259:             .collect(),
260:         normals
261:             .into_iter()
262:             .map(|normal| normal.normalize_or_zero().to_array())
263:             .collect(),
264:         oriented_indices,
265:     )
266: }
267: 
268: fn triangle_normal(source: &[u32], positions: &[Vec3]) -> Option<([u32; 3], Vec3)> {
269:     let triangle = [source[0], source[1], source[2]];
270:     let [a, b, c] = triangle.map(|index| positions[index as usize]);
271:     let normal = (b - a).cross(c - a);
272:     // Tiny triangles close a valid surface near lattice corners. Dropping
273:     // them on an arbitrary area threshold opens cracks around carved roofs.
274:     if normal.length_squared() == 0.0 {
275:         return None;
276:     }
277:     Some((triangle, normal))
278: }
