1: //! Trim monotone vertical height columns before tetrahedron extraction.
2: use super::*;
3: use crate::volumetric_terrain::{TerrainRecipeError, TerrainRecipeResult};
4: 
5: /// Extract `position.y - height[x,z]` on the producer's native metre lattice.
6: /// Positions use identical horizontal coordinates at every elevation, with
7: /// increasing Y shared by all columns. Other erosion fields use the general
8: /// three-dimensional sampler because they can contain caves and overhangs.
9: pub(crate) fn marching_height_surface(
10:     dimensions: [usize; 3],
11:     position_at: impl Fn([usize; 3]) -> Vec3,
12:     heights: &[f32],
13:     transition_collar: TerrainTransitionCollar,
14: ) -> TerrainRecipeResult<SceneTerrainPatch> {
15:     let [width, vertical, depth] = dimensions;
16:     let columns = width
17:         .checked_mul(depth)
18:         .ok_or(TerrainRecipeError::SampleCountOverflow)?;
19:     columns
20:         .checked_mul(vertical)
21:         .ok_or(TerrainRecipeError::SampleCountOverflow)?;
22:     if dimensions.iter().any(|&side| side < 2) || heights.len() != columns {
23:         return Err(TerrainRecipeError::VoxelGridBound);
24:     }
25:     let elevations = (0..vertical)
26:         .map(|y| position_at([0, y, 0]).y)
27:         .collect::<Vec<_>>();
28:     if heights
29:         .iter()
30:         .chain(&elevations)
31:         .any(|value| !value.is_finite())
32:         || heights.iter().any(|&height| {
33:             !(elevations[0] - height).is_finite()
34:                 || !(elevations[vertical - 1] - height).is_finite()
35:         })
36:         || elevations.windows(2).any(|pair| pair[0] >= pair[1])
37:         || (0..columns).any(|column| {
38:             let x = column % width;
39:             let z = column / width;
40:             !position_at([x, 0, z]).is_finite() || !position_at([x, vertical - 1, z]).is_finite()
41:         })
42:     {
43:         return Err(TerrainRecipeError::NonFiniteField);
44:     }
45:     // First positive endpoint, using the original subtraction and zero snap.
46:     // No float-to-grid inversion changes classification at lattice corners.
47:     let crossings = heights
48:         .iter()
49:         .map(|&height| elevations.partition_point(|&y| snap_field_zero(y - height) <= 0.0))
50:         .collect::<Vec<_>>();
51:     let sample_at = |index| {
52:         let yz = index / width;
53:         let coordinate = [index % width, yz % vertical, yz / vertical];
54:         let position = position_at(coordinate);
55:         LatticeSample {
56:             position,
57:             value: snap_field_zero(position.y - heights[coordinate[2] * width + coordinate[0]]),
58:         }
59:     };
60:     let (positions, indices) = extract_height_surface(dimensions, &crossings, &sample_at)?;
61:     build_surface(positions, indices, transition_collar)
62: }
63: 
64: fn extract_height_surface(
65:     dimensions: [usize; 3],
66:     crossings: &[usize],
67:     sample_at: &impl Fn(usize) -> LatticeSample,
68: ) -> TerrainRecipeResult<(Vec<Vec3>, Vec<u32>)> {
69:     let [width, vertical, depth] = dimensions;
70:     let sample_id = |x: usize, y: usize, z: usize| (z * vertical + y) * width + x;
71:     let mut positions = Vec::new();
72:     let mut indices = Vec::new();
73:     let mut edge_vertices = HashMap::new();
74:     for z in 0..depth - 1 {
75:         let rows = &crossings[z * width..(z + 2) * width];
76:         let first = rows.iter().copied().min().unwrap_or(0).saturating_sub(1);
77:         let end = rows.iter().copied().max().unwrap_or(0).min(vertical - 1);
78:         // Keep z/y/x/tetrahedron visitation and global edge identities exactly
79:         // as in the full lattice, skipping only cells with one classification.
80:         // Edge trimming: <REDACTED_URL>
81:         for y in first..end {
82:             for x in 0..width - 1 {
83:                 let corners = [rows[x], rows[x + 1], rows[width + x], rows[width + x + 1]];
84:                 if corners.iter().all(|&crossing| y + 1 < crossing)
85:                     || corners.iter().all(|&crossing| y >= crossing)
86:                 {
87:                     continue;
88:                 }
89:                 let cube =
90:                     CUBE.map(|offset| sample_id(x + offset[0], y + offset[1], z + offset[2]));
91:                 for tet in TETS {
92:                     emit_tetrahedron(
93:                         tet.map(|corner| cube[corner]),
94:                         sample_at,
95:                         &mut edge_vertices,
96:                         &mut positions,
97:                         &mut indices,
98:                     )?;
99:                 }
100:             }
101:         }
102:     }
103:     Ok((positions, indices))
104: }
