35:     let spacing = f32::from(recipe.lod().voxel_cm()) / 100.0;
36:     let origin = Vec2::new(recipe.origin_cm()[0] as f32, recipe.origin_cm()[1] as f32) / 100.0;
37:     let radius = f32::from(recipe.half_length_cm().max(recipe.half_width_cm())) / 100.0 + 2.0;
38:     let radius = (radius / spacing).ceil() * spacing + spacing;
39:     let side = (radius * 2.0 / spacing).round() as usize + 1;
40:     let mut minimum = f32::INFINITY;
41:     let mut maximum = f32::NEG_INFINITY;
42:     for z in 0..side {
43:         for x in 0..side {
44:             let point = ScenePlanPoint::from_metres(
45:                 origin + Vec2::new(x as f32, z as f32) * spacing - Vec2::splat(radius),
46:             )
47:             .ok_or(TerrainRecipeError::NonFiniteField)?;
48:             let height = height_at_extended_edge(terrain, point)?.metres();
49:             minimum = minimum.min(height);
50:             maximum = maximum.max(height);
51:         }
52:     }
53:     let relief = f32::from(recipe.relief_cm()) / 100.0;
54:     let bottom = ((minimum - relief - spacing * SAMPLE_MARGIN_CELLS) / spacing).floor() * spacing
55:         - spacing * 0.5;
56:     let top = maximum + spacing * SAMPLE_MARGIN_CELLS;
57:     let vertical = ((top - bottom) / spacing).ceil() as usize + 1;
58:     if side > MAX_GRID_SIDE || vertical > MAX_GRID_HEIGHT {
59:         return Err(TerrainRecipeError::ErosionVoxelGridBound);
60:     }
61:     marching_tetrahedra(
62:         [side, vertical, side],
63:         |index| {
64:             Vec3::new(
65:                 origin.x + index[0] as f32 * spacing - radius,
66:                 bottom + index[1] as f32 * spacing,
67:                 origin.y + index[2] as f32 * spacing - radius,
68:             )
69:         },
70:         |position| field(terrain, recipe, position),
71:         recipe.transition_collar(),
72:     )
73: }
