44: pub(crate) fn marching_tetrahedra(
45:     dimensions: [usize; 3],
46:     position_at: impl Fn([usize; 3]) -> Vec3 + Sync,
47:     field: impl Fn(Vec3) -> TerrainRecipeResult<f32> + Sync,
48:     transition_collar: TerrainTransitionCollar,
49: ) -> TerrainRecipeResult<SceneTerrainPatch> {
50:     let (positions, values) = sample_field(dimensions, &position_at, &field)?;
51:     let (mesh_positions, indices) = extract_surface(dimensions, &positions, &values)?;
52:     build_surface(mesh_positions, indices, transition_collar)
53: }
