125: fn emit_tetrahedron(
126:     vertices: [usize; 4],
127:     sample_at: &impl Fn(usize) -> LatticeSample,
128:     edge_vertices: &mut HashMap<(usize, usize), u32>,
129:     mesh_positions: &mut Vec<Vec3>,
130:     indices: &mut Vec<u32>,
131: ) -> TerrainRecipeResult<()> {
132:     let mut inside = [0; 4];
133:     let mut outside = [0; 4];
134:     let mut inside_count = 0;
135:     let mut outside_count = 0;
136:     for index in vertices {
137:         if sample_at(index).value <= 0.0 {
138:             inside[inside_count] = index;
139:             inside_count += 1;
140:         } else {
141:             outside[outside_count] = index;
142:             outside_count += 1;
143:         }
144:     }
145:     let inside = &inside[..inside_count];
146:     let outside = &outside[..outside_count];
147:     let first_triangle = indices.len();
148:     let mut vertex = |a, b| vertex_on_edge(a, b, sample_at, edge_vertices, mesh_positions);
149:     match (inside.len(), outside.len()) {
150:         (1, 3) => {
151:             for &b in outside {
152:                 indices.push(vertex(inside[0], b)?);
153:             }
154:         }
155:         (3, 1) => {
156:             let triangle = [
157:                 vertex(inside[0], outside[0])?,
158:                 vertex(inside[1], outside[0])?,
159:                 vertex(inside[2], outside[0])?,
160:             ];
161:             indices.extend([triangle[0], triangle[2], triangle[1]]);
162:         }
163:         (2, 2) => {
164:             let ac = vertex(inside[0], outside[0])?;
165:             let ad = vertex(inside[0], outside[1])?;
166:             let bc = vertex(inside[1], outside[0])?;
167:             let bd = vertex(inside[1], outside[1])?;
168:             indices.extend([ac, bc, ad, ad, bc, bd]);
169:         }
170:         _ => {}
171:     }
172:     if let (Some(&solid), Some(&empty)) = (inside.first(), outside.first()) {
173:         // The extracted surface is linear within this tetrahedron. Its normal
174:         // must face from the solid sample toward the empty sample. A gradient
175:         // of the original nonlinear field at a triangle centre can face the
176:         // other way at a cusp, breaking winding across shared edges.
177:         let outward = sample_at(empty).position.as_dvec3() - sample_at(solid).position.as_dvec3();
178:         for triangle in indices[first_triangle..].as_chunks_mut::<3>().0 {
179:             let [a, b, c] = [triangle[0], triangle[1], triangle[2]]
180:                 .map(|index| mesh_positions[index as usize].as_dvec3());
181:             if (b - a).cross(c - a).dot(outward) < 0.0 {
182:                 triangle.swap(1, 2);
183:             }
184:         }
185:     }
186:     Ok(())
187: }
188: 
189: fn vertex_on_edge(
190:     a: usize,
191:     b: usize,
192:     sample_at: &impl Fn(usize) -> LatticeSample,
193:     edge_vertices: &mut HashMap<(usize, usize), u32>,
194:     mesh_positions: &mut Vec<Vec3>,
195: ) -> TerrainRecipeResult<u32> {
196:     // Several tetrahedra can reach the same zero-valued lattice vertex along
197:     // different edges. Give that endpoint one identity to preserve topology.
198:     let start = sample_at(a);
199:     let end = sample_at(b);
200:     let key = if start.value == 0.0 {
201:         (a, a)
202:     } else if end.value == 0.0 {
203:         (b, b)
204:     } else if a < b {
205:         (a, b)
206:     } else {
207:         (b, a)
208:     };
209:     if let Some(&index) = edge_vertices.get(&key) {
210:         return Ok(index);
211:     }
212:     let denominator = start.value - end.value;
213:     let fraction = if denominator.abs() < 1e-7 {
214:         0.5
215:     } else {
216:         start.value / denominator
217:     }
218:     .clamp(0.0, 1.0);
219:     let index =
220:         u32::try_from(mesh_positions.len()).map_err(|_| TerrainRecipeError::VertexCountOverflow)?;
221:     mesh_positions.push(start.position.lerp(end.position, fraction));
222:     edge_vertices.insert(key, index);
223:     Ok(index)
224: }
