234: fn build_surface(
235:     mesh_positions: Vec<Vec3>,
236:     indices: Vec<u32>,
237:     transition_collar: TerrainTransitionCollar,
238: ) -> TerrainRecipeResult<SceneTerrainPatch> {
239:     let oriented = indices
240:         .par_chunks_exact(3)
241:         .map(|source| triangle_normal(source, &mesh_positions))
242:         .collect::<Vec<_>>();
243:     let mut normals = vec![Vec3::ZERO; mesh_positions.len()];
244:     let mut oriented_indices = Vec::with_capacity(indices.len());
245:     for (triangle, normal) in oriented.into_iter().flatten() {
246:         for &index in &triangle {
247:             normals[index as usize] += normal;
248:         }
249:         oriented_indices.extend(triangle);
250:     }
251:     if oriented_indices.is_empty() {
252:         return Err(TerrainRecipeError::EmptySurface);
253:     }
254:     SceneTerrainPatch::from_mesh_buffers(
255:         transition_collar,
256:         mesh_positions
257:             .into_iter()
258:             .map(|position| position.to_array())
259:             .collect(),
260:         normals
261:             .into_iter()
262:             .map(|normal| normal.normalize_or_zero().to_array())
263:             .collect(),
264:         oriented_indices,
265:     )
266: }
267: 
268: fn triangle_normal(source: &[u32], positions: &[Vec3]) -> Option<([u32; 3], Vec3)> {
269:     let triangle = [source[0], source[1], source[2]];
270:     let [a, b, c] = triangle.map(|index| positions[index as usize]);
271:     let normal = (b - a).cross(c - a);
272:     // Tiny triangles close a valid surface near lattice corners. Dropping
273:     // them on an arbitrary area threshold opens cracks around carved roofs.
274:     if normal.length_squared() == 0.0 {
275:         return None;
276:     }
277:     Some((triangle, normal))
278: }

