241: fn validate_family_frequencies<'a>(
242:     repertoire: &'a NameRepertoireDefinition,
243:     families: &FamilyIndex<'_>,
244: ) -> Result<BTreeSet<&'a str>, String> {
245:     let mut eligible_families = BTreeSet::new();
246:     for &sex in Sex::VARIANTS {
247:         let frequencies = repertoire
248:             .families
249:             .get(&sex)
250:             .map(Vec::as_slice)
251:             .unwrap_or(&[]);
252:         if frequencies.is_empty() {
253:             return Err(format!(
254:                 "repertoire {} has no {:?} families",
255:                 repertoire.id, sex
256:             ));
257:         }
258:         for frequency in frequencies {
259:             if frequency.frequency == 0 || !eligible_families.insert(frequency.family_id.as_str()) {
260:                 return Err(format!(
261:                     "repertoire {} has a zero or duplicate family frequency for {}",
262:                     repertoire.id, frequency.family_id
263:                 ));
264:             }
265:             if families.get(frequency.family_id.as_str()) != Some(&sex) {
266:                 return Err(format!(
267:                     "repertoire {} frequencies {} under the wrong sex",
268:                     repertoire.id, frequency.family_id
269:                 ));
270:             }
271:         }
272:     }
273:     Ok(eligible_families)
274: }
