276: fn validate_form_frequencies(
277:     repertoire: &NameRepertoireDefinition,
278:     forms: &FormIndex<'_>,
279:     eligible_families: &BTreeSet<&str>,
280: ) -> Result<(), String> {
281:     let mut eligible_forms = BTreeSet::new();
282:     let mut families_with_forms = BTreeSet::new();
283:     let mut form_totals = BTreeMap::<&str, u64>::new();
284:     for frequency in &repertoire.everyday_forms {
285:         if frequency.frequency == 0
286:             || !eligible_forms.insert((frequency.family_id.as_str(), frequency.form_id.as_str()))
287:         {
288:             return Err(format!(
289:                 "repertoire {} has a zero or duplicate form frequency for {}/{}",
290:                 repertoire.id, frequency.family_id, frequency.form_id
291:             ));
292:         }
293:         if !eligible_families.contains(frequency.family_id.as_str()) {
294:             return Err(format!(
295:                 "repertoire {} lists a form frequency for ineligible family {}",
296:                 repertoire.id, frequency.family_id
297:             ));
298:         }
299:         let form = forms.get(frequency.form_id.as_str()).ok_or_else(|| {
300:             format!(
301:                 "repertoire {} references unknown form {}",
302:                 repertoire.id, frequency.form_id
303:             )
304:         })?;
305:         if form.register != NameRegister::Everyday
306:             || form.culture != repertoire.culture
307:             || !form.family_ids.iter().any(|id| id == &frequency.family_id)
308:         {
309:             return Err(format!(
310:                 "repertoire {} form {} is incompatible with family, culture, or register",
311:                 repertoire.id, frequency.form_id
312:             ));
313:         }
314:         families_with_forms.insert(frequency.family_id.as_str());
315:         let total = form_totals.entry(frequency.family_id.as_str()).or_default();
316:         *total = total
317:             .checked_add(frequency.frequency)
318:             .ok_or_else(|| format!("form frequencies overflow for {}", frequency.family_id))?;
319:     }
320:     for family_id in eligible_families.iter().copied() {
321:         if !families_with_forms.contains(family_id) {
322:             return Err(format!(
323:                 "repertoire {} family {} has no everyday form",
324:                 repertoire.id, family_id
325:             ));
326:         }
327:     }
328:     Ok(())
329: }
