331: fn validate_surname_frequencies(
332:     repertoire: &NameRepertoireDefinition,
333:     surnames: &SurnameIndex<'_>,
334:     surname_forms: &SurnameFormIndex<'_>,
335: ) -> Result<(), String> {
336:     if repertoire.surnames.is_empty() {
337:         return Err(format!(
338:             "repertoire {} has no surname frequency",
339:             repertoire.id
340:         ));
341:     }
342:     let mut eligible_surnames = BTreeSet::new();
343:     for frequency in &repertoire.surnames {
344:         if frequency.frequency == 0 || !eligible_surnames.insert(frequency.surname_id.as_str()) {
345:             return Err(format!(
346:                 "repertoire {} has a zero or duplicate surname frequency for {}",
347:                 repertoire.id, frequency.surname_id
348:             ));
349:         }
350:         if surnames.get(frequency.surname_id.as_str()) != Some(&SurnameClass::HereditaryCommoner) {
351:             return Err(format!(
352:                 "repertoire {} may generate only hereditary commoner surnames: {}",
353:                 repertoire.id, frequency.surname_id
354:             ));
355:         }
356:         let compatible_forms = surname_forms
357:             .get(frequency.surname_id.as_str())
358:             .into_iter()
359:             .flatten()
360:             .filter(|form| form.culture == repertoire.culture)
361:             .collect::<Vec<_>>();
362:         for &sex in Sex::VARIANTS {
