366:             {
367:                 return Err(format!(
368:                     "repertoire {} surname {} has no compatible {:?} form",
369:                     repertoire.id, frequency.surname_id, sex
370:                 ));
371:             }
372:         }
373:     }
374:     Ok(())
375: }
