143: pub(super) fn validate_loopback_url(host: &str) -> Result<(), String> {
144:     let parsed = Url::parse(host).map_err(|error| format!("invalid SpacetimeDB URL: {error}"))?;
145:     if parsed.scheme() != "http"
146:         || !parsed.username().is_empty()
147:         || parsed.password().is_some()
148:         || parsed.path() != "/"
149:         || parsed.query().is_some()
150:         || parsed.fragment().is_some()
151:         || !matches!(parsed.host_str(), Some("localhost" | "127.0.0.1" | "::1"))
152:     {
153:         return Err("host must be a credential-free <REDACTED_URL> 127.0.0.1, or [::1] origin with no path/query/fragment".into());
154:     }
155:     Ok(())
156: }
